QT_ISI(20,{"3215":["(Maka tidak lain jawaban kaumnya melainkan mengatakan \"Usirlah Luth beserta keluarganya) (dari negeri kalian, karena sesungguhnya mereka itu orang-orang yang mengklaim dirinya bersih\") dari dubur kaum laki-laki, yakni tidak mau melakukan homosex.",[["۞ فَمَا","Tetapi tidak"],["كَانَ","adalah"],["جَوَابَ","(the) jawapan"],["قَوْمِهِۦٓ","(dari) kaumnya"],["إِلَّآ","kecuali"],["أَن","bahawa"],["قَالُوٓا۟","mereka berkata"],["أَخْرِجُوٓا۟","memandu keluar"],["ءَالَ","(keluarga)."],["لُوطٍۢ","(dari) Lut"],["مِّن","daripada"],["قَرْيَتِكُمْ ۖ","bandar kamu"],["إِنَّهُمْ","Sesungguhnya mereka"],["أُنَاسٌۭ","(adalah) orang"],["يَتَطَهَّرُونَ","yang menjaga kebersihan dan kesucian"]]],"3216":["(Maka Kami selamatkan dia beserta keluarganya kecuali istrinya, Kami telah menakdirkan dia) telah memastikannya (termasuk orang-orang yang tertinggal) tetap terkena azab.",[["فَأَنجَيْنَـٰهُ","Maka Kami selamatkan dia"],["وَأَهْلَهُۥٓ","dan keluarganya"],["إِلَّا","kecuali"],["ٱمْرَأَتَهُۥ","isterinya"],["قَدَّرْنَـٰهَا","Kami takdirkan dia"],["مِنَ","(menjadi) daripada"],["ٱلْغَـٰبِرِينَ","mereka yang tinggal di belakang"]]],"3217":["(Dan Kami turunkan hujan atas mereka) berupa batu dari sijjil, maka binasalah mereka (maka amat buruklah) seburuk-buruk (hujan yang ditimpakan atas orang-orang yang diberi peringatan itu) yaitu hujan azab yang ditimpakan atas mereka.",[["وَأَمْطَرْنَا","Dan Kami menghujani"],["عَلَيْهِم","ke atas mereka"],["مَّطَرًۭا ۖ","hujan"],["فَسَآءَ","dan adalah jahat"],["مَطَرُ","(hujan)."],["ٱلْمُنذَرِينَ","(pada) orang-orang yang diberi peringatan"]]],"3218":["(Katakanlah) hai Muhammad!, (\"Segala puji bagi Allah) atas binasanya orang-orang kafir dari umat-umat terdahulu (dan kesejahteraan atas hamba-hamba-Nya yang dipilih-Nya) yakni mereka yang dipilih-Nya (Apakah Allah) Allah dapat dibaca Tahqiq dan Tas-hil (yang lebih baik) bagi orang yang menyembah-Nya (ataukah apa yang mereka persekutukan dengan Dia) dapat dibaca, Yusyrikuna dan Tusyrikuna. Maksudnya apa yang dipersekutukan oleh para kuffar Mekah yaitu berhala-berhala. Apakah berhala-berhala itu lebih baik bagi para penyembahnya?",[["قُلِ","Katakanlah"],["ٱلْحَمْدُ","Segala puji (semoga)"],["لِلَّهِ","kepada Allah"],["وَسَلَـٰمٌ","dan damai sejahtera"],["عَلَىٰ","ke atas"],["عِبَادِهِ","hambanya"],["ٱلَّذِينَ","mereka yang"],["ٱصْطَفَىٰٓ ۗ","Dia telah memilih"],["ءَآللَّهُ","Adakah Allah"],["خَيْرٌ","lebih baik"],["أَمَّا","atau apa"],["يُشْرِكُونَ","mereka mempersekutukan (dengan Dia)"]]],"3219":["(Atau siapakah yang telah menciptakan langit dan bumi dan yang menurunkan air dari langit buat kalian, lalu Kami tumbuhkan) di dalam ungkapan ini terdapat Iltifat yakni sindiran dari Ghaibah kepada Mutakallim (dengan air itu kebun-kebun) lafal Hada-iq bentuk jamak dari lafal Hadiqatun artinya kebun yang dipagari (yang berpemandangan indah) tampak indah (yang kalian sekali-kali tidak mampu menumbuhkan pohon-pohonnya?) karena kalian tidak akan mempunyai kemampuan dan kekuasaan untuk itu. (Apakah ada tuhan) a-ilahun dapat dibaca Tahqiq dan Tas-hil (di samping Allah) yang membantu-Nya untuk melakukan hal-hal tersebut? Maksudnya tidak ada tuhan lain di samping Dia. (Bahkan sebenarnya mereka adalah orang-orang yang menyimpang) yakni menyekutukan Allah dengan selain-Nya.",[["أَمَّنْ","Atau Siapa"],["خَلَقَ","telah mencipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["وَأَنزَلَ","dan diturunkan"],["لَكُم","bagi kamu"],["مِّنَ","daripada"],["ٱلسَّمَآءِ","langit"],["مَآءًۭ","air"],["فَأَنۢبَتْنَا","Dan Kami tumbuhkan"],["بِهِۦ","dengan itu"],["حَدَآئِقَ","taman-taman"],["ذَاتَ","keindahan (dan kegembiraan)"],["بَهْجَةٍۢ","keindahan (dan kegembiraan)"],["مَّا","tidak"],["كَانَ","ia adalah"],["لَكُمْ","bagi kamu"],["أَن","bahawa"],["تُنۢبِتُوا۟","kamu menyebabkan berkembang"],["شَجَرَهَآ ۗ","pokok mereka"],["أَءِلَـٰهٌۭ","Adakah ada tuhan"],["مَّعَ","dengan"],["ٱللَّهِ ۚ","Allah"],["بَلْ","Bahkan"],["هُمْ","mereka"],["قَوْمٌۭ","(adalah) suatu kaum"],["يَعْدِلُونَ","yang menganggap sama"]]],"3220":["(Atau siapakah yang telah menjadikan bumi sebagai tempat berdiam) sehingga ia tidak menggoncangkan penduduknya (dan yang menjadikan di cekah-celahnya) yakni di antara celah-celahnya (sungai-sungai dan yang menjadikan gunung-gunung untuk mengokohkannya) sebagai pengokoh Bumi (dan menjadikan suatu pemisah antara dua laut) antara air tawar dan air asin, satu sama lainnya tidak bercampur baur. (Apakah di samping Allah ada tuhan yang lain? Bahkan sebenarnya kebanyakan dari mereka tidak mengetahui) keesaaan-Nya",[["أَمَّن","Atau Siapa"],["جَعَلَ","dibuat"],["ٱلْأَرْضَ","bumi"],["قَرَارًۭا","tempat tinggal yang kukuh"],["وَجَعَلَ","dan dibuat"],["خِلَـٰلَهَآ","(di) tengah-tengahnya"],["أَنْهَـٰرًۭا","sungai-sungai"],["وَجَعَلَ","dan dibuat"],["لَهَا","baginya"],["رَوَٰسِىَ","gunung yang kukuh"],["وَجَعَلَ","dan dibuat"],["بَيْنَ","antara"],["ٱلْبَحْرَيْنِ","dua lautan itu"],["حَاجِزًا ۗ","penghalang"],["أَءِلَـٰهٌۭ","Adakah ada tuhan"],["مَّعَ","dengan"],["ٱللَّهِ ۚ","Allah"],["بَلْ","Bahkan"],["أَكْثَرُهُمْ","kebanyakan mereka"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"3221":["(Atau siapakah yang memperkenankan doa orang yang dalam kesulitan) orang yang sengsara kemudian tertimpa kemudaratan (apabila ia berdoa kepada-Nya, dan yang menghilangkan kesusahan) dari dirinya dan dari diri orang selainnya (dan yang menjadikan kalian sebagai khalifah di bumi) Idhafah dalam lafal Khulafa-al Ardhi mengandung makna Fi. Maksudnya. setiap generasi menjadi pengganti generasi sebelumnya. (Apakah di samping Allah ada tuhan yang lain? Amat sedikitlah kalian mengingati-Nya) mengambil pelajaran dari hal ini. Lafal Tadzakkaruna dapat pula dibaca Yadzdzakkaruna; kemudian huruf Ta di-idgham-kan kepada huruf Dzal. Dan huruf Ma di sini untuk menunjukkan makna sedikit sekali. bintang sebagai pemandunya di waktu tengah malam, dan, dengan tanda-tanda yang ada di daratan di waktu siang hari",[["أَمَّن","Atau Siapa"],["يُجِيبُ","menjawab"],["ٱلْمُضْطَرَّ","(kepada) orang yang susah"],["إِذَا","apabila"],["دَعَاهُ","dia memanggil-Nya"],["وَيَكْشِفُ","dan Dia menghilangkan"],["ٱلسُّوٓءَ","yang jahat"],["وَيَجْعَلُكُمْ","dan menjadikan kamu"],["خُلَفَآءَ","pewaris"],["ٱلْأَرْضِ ۗ","(dari) bumi"],["أَءِلَـٰهٌۭ","Adakah ada tuhan"],["مَّعَ","dengan"],["ٱللَّهِ ۚ","Allah"],["قَلِيلًۭا","sedikit"],["مَّا","(ialah) apa"],["تَذَكَّرُونَ","kamu ingat"]]],"3222":["(Atau siapakah yang memimpin kalian) yakni yang membimbing kalian kepada tujuan-tujuan kalian (dalam kegelapan di daratan dan lautan) dengan bintang-bintang sebagai pemandunya di waktu tengah malam dan dengan tanda-tanda yang ada di daratan di waktu siang hari (dan siapa pulakah yang mendatangkan angin sebagai kabar gembira sebelum kedatangan rahmat-Nya) sebelum hujan tiba (Apakah di samping Allah ada tuhan yang lain? Maha Tinggi Allah terhadap apa yang mereka persekutukan) dengan-Nya.",[["أَمَّن","Atau Siapa"],["يَهْدِيكُمْ","membimbing kamu"],["فِى","dalam"],["ظُلُمَـٰتِ","(the) kegelapan[es]"],["ٱلْبَرِّ","(dari) tanah itu"],["وَٱلْبَحْرِ","dan laut"],["وَمَن","dan Siapa"],["يُرْسِلُ","menghantar"],["ٱلرِّيَـٰحَ","angin"],["بُشْرًۢا","(sebagai) berita gembira"],["بَيْنَ","sebelum"],["يَدَىْ","sebelum"],["رَحْمَتِهِۦٓ ۗ","KerahimanNya"],["أَءِلَـٰهٌۭ","Adakah ada tuhan"],["مَّعَ","dengan"],["ٱللَّهِ ۚ","Allah"],["تَعَـٰلَى","Tinggi adalah"],["ٱللَّهُ","Allah"],["عَمَّا","atas apa"],["يُشْرِكُونَ","mereka mempersekutukan (dengan Dia)"]]],"3223":["(Atau siapakah yang menciptakan manusia dari permulaannya) di dalam rahim, yakni dari air mani (kemudian mengulanginya lagi) menghidupkannya kembali sesudah mati, sekalipun kalian tidak mengakui adanya hari berbangkit itu, karena bukti-bukti yang menunjukkannya telah jelas (dan siapa pula yang memberikan rezeki dari langit) melalui hujan (dan bumi?) melalui tumbuh-tumbuhan. (Apakah di samping Allah ada tuhan yang lain?\") maksudnya, tidak ada yang dapat melakukan sedikit pun dari hal-hal yang telah disebutkan tadi melainkan hanya Allah semata, dan tiada Tuhan selain-Nya. (Katakanlah) hai Muhammad!, (\"Unjukkanlah bukti kebenaran kalian) argumentasi kalian (jika kalian memang orang-orang yang benar\") bahwasanya di samping-Ku ada tuhan lain yang mampu berbuat sesuatu dari hal-hal yang telah disebutkan tadi. Kemudian orang-orang kafir itu bertanya kepada Nabi saw. tentang waktu kiamat, maka turunlah firman-Nya,",[["أَمَّن","Atau Siapa"],["يَبْدَؤُا۟","berasal"],["ٱلْخَلْقَ","penciptaan"],["ثُمَّ","kemudian"],["يُعِيدُهُۥ","mengulanginya"],["وَمَن","dan Siapa"],["يَرْزُقُكُم","menyediakan kamu"],["مِّنَ","daripada"],["ٱلسَّمَآءِ","langit"],["وَٱلْأَرْضِ ۗ","dan bumi"],["أَءِلَـٰهٌۭ","Adakah ada tuhan"],["مَّعَ","dengan"],["ٱللَّهِ ۚ","Allah"],["قُلْ","Katakanlah"],["هَاتُوا۟","bawa keluar"],["بُرْهَـٰنَكُمْ","bukti kamu"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"3224":["(Katakanlah!, \"Tidak ada seorang pun di langit dan di bumi yang mengetahui) baik dari kalangan para Malaikat maupun manusia (perkara yang gaib) dari mereka (kecuali) hanya (Allah saja) yang mengetahuinya (dan mereka tidak mengetahui) maksudnya orang-orang kafir Mekah sama pula dengan orang-orang selain mereka (bila) kapan waktunya (mereka dibangkitkan hidup kembali.\")",[["قُل","Katakanlah"],["لَّا","tiada (satu)"],["يَعْلَمُ","mengetahui"],["مَن","sesiapa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["ٱلْغَيْبَ","(dari) yang ghaib"],["إِلَّا","kecuali"],["ٱللَّهُ ۚ","Allah"],["وَمَا","dan bukan"],["يَشْعُرُونَ","mereka rasa"],["أَيَّانَ","apabila"],["يُبْعَثُونَ","mereka akan dibangkitkan"]]],"3225":["(Apakah) lafal Bal di sini bermakna Hal, yakni apakah (sampai ke sana) lafal Iddaraka pada asalnya adalah Tadaraka, kemudian huruf Ta diganti menjadi Dal kemudian di-idgam-kan kepada Dal, lalu ditariklah Hamzali Washal, artinya sama dengan lafal Balagha, Lahiqa, atau Tataba'a dan Talahaqa, yaitu, sampai ke sana. Menurut qiraat yang lain dibaca Adraka menurut wazan Akrama, sehingga artinya menjadi, Apakah telah sampai ke sana (pengetahuan mereka tentang akhirat?) yakni mengenai hari akhirat, sehingga mereka menanyakan tentang kedatangannya. Pada kenyataannya tidaklah demikian (sebenarnya mereka ragu-ragu tentang akhirat itu, bahkan mereka buta daripadanya) 'Amuna berasal dari kata Umyul Qalbi yang artinya buta hatinya; pengertian ungkapan ini lebih mengena daripada kalimat sebelumnya. Pada asalnya lafal 'Amuna adalah 'Amiyuna, oleh karena harakat Dhammah atas Ya dianggap berat untuk diucapkan, maka harakat Dhammah-nya dipindahkan kepada Mim, hal ini dilakukan sesudah terlebih dahulu harakat Kasrah-nya dibuang, sehingga jadilah 'Amuna.",[["بَلِ","Bahkan"],["ٱدَّٰرَكَ","ditangkap"],["عِلْمُهُمْ","pengetahuan mereka"],["فِى","daripada"],["ٱلْـَٔاخِرَةِ ۚ","akhirat"],["بَلْ","Bahkan"],["هُمْ","mereka"],["فِى","(ada) dalam"],["شَكٍّۢ","keraguan"],["مِّنْهَا ۖ","mengenainya"],["بَلْ","Bahkan"],["هُم","mereka"],["مِّنْهَا","mengenainya"],["عَمُونَ","(adalah) buta"]]],"3226":["Berkata pula orang-orang kafir) yang mengingkari adanya hari berbangkit (\"Apakah setelah kita menjadi tanah dan begitu pula bapak-bapak kita; apakah sesungguhnya kita akan dikeluarkan kembali?) dari kuburan kita, maksudnya akan dihidupkan kembali.",[["وَقَالَ","Dan katakan"],["ٱلَّذِينَ","orang yang"],["كَفَرُوٓا۟","kufur"],["أَءِذَا","Apa, apabila"],["كُنَّا","kita telah menjadi"],["تُرَٰبًۭا","habuk"],["وَءَابَآؤُنَآ","dan nenek moyang kita"],["أَئِنَّا","akan kita"],["لَمُخْرَجُونَ","pasti dibawa keluar"]]],"3227":["(Sesungguhnya kami telah diberi ancaman dengan ini dan juga bapak-bapak kami dahulu, tiada lain) yakni tidak lain (ini hanyalah dongeng-dongengan orang dahulu kala\") lafal Asathir bentuk jamak dari lafal Usthurah, artinya dongeng yang tidak ada kenyataannya, atau cerita dusta.",[["لَقَدْ","Sungguh"],["وُعِدْنَا","kita telah dijanjikan"],["هَـٰذَا","ini"],["نَحْنُ","kita"],["وَءَابَآؤُنَا","dan nenek moyang kita"],["مِن","sebelum"],["قَبْلُ","sebelum"],["إِنْ","Tidak"],["هَـٰذَآ","(adalah) ini"],["إِلَّآ","kecuali"],["أَسَـٰطِيرُ","cerita-cerita"],["ٱلْأَوَّلِينَ","(dari) orang-orang dahulu"]]],"3228":["(Katakanlah!, \"Berjalanlah kalian di muka bumi, lalu perhatikanlah bagaimana akibat orang-orang yang berdosa) karena ingkar kepada adanya hari berbangkit, yaitu dibinasakan-Nya mereka oleh azab-Nya.",[["قُلْ","Katakanlah"],["سِيرُوا۟","Perjalanan"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["فَٱنظُرُوا۟","dan lihat"],["كَيْفَ","bagaimana"],["كَانَ","adalah"],["عَـٰقِبَةُ","(akhirnya)."],["ٱلْمُجْرِمِينَ","(dari) penjenayah"]]],"3229":["(Dan janganlah kamu berduka cita terhadap mereka dan janganlah dadamu merasa sempit terhadap apa yang mereka tipu dayakan\") ayat ini merupakan hiburan dan penenang hati Nabi saw. Maksudnya, janganlah kamu hiraukan makar mereka terhadap dirimu, karena sesungguhnya Kami akan menolong kamu dari mereka.",[["وَلَا","Dan jangan"],["تَحْزَنْ","bersedih"],["عَلَيْهِمْ","atas mereka"],["وَلَا","dan bukan"],["تَكُن","jadilah"],["فِى","dalam"],["ضَيْقٍۢ","kesusahan"],["مِّمَّا","daripada apa"],["يَمْكُرُونَ","mereka merancang"]]],"3230":["(Dan mereka berkata, \"Bilakah datangnya ancaman itu) azab yang diancamkan itu (jika memang kamu orang-orang yang benar.\") di dalam pengakuanmu itu.",[["وَيَقُولُونَ","Dan mereka berkata"],["مَتَىٰ","Apabila"],["هَـٰذَا","(akan) ini"],["ٱلْوَعْدُ","janji (ditepati)"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"3231":["(Katakanlah!, \"Mungkin telah hampir datang) artinya telah dekat (kepada kalian sebagian dari azab yang kalian minta supaya disegerakan itu.\") maka terjadilah hal itu, yaitu dengan dibunuhnya mereka dalam perang Badar, sedangkan azab yang lainnya akan menimpa mereka sesudah mereka mati.",[["قُلْ","Katakanlah"],["عَسَىٰٓ","barangkali"],["أَن","bahawa"],["يَكُونَ","ialah"],["رَدِفَ","dekat belakang"],["لَكُم","kamu"],["بَعْضُ","beberapa"],["ٱلَّذِى","(daripada) yang"],["تَسْتَعْجِلُونَ","kamu berusaha untuk menyegerakan"]]],"3232":["(Dan sesungguhnya Rabbmu, benar-benar mempunyai karunia yang besar yang diberikan-Nya kepada manusia) antara lain; penangguhan azab atas orang-orang kafir (tetapi kebanyakan mereka tidak mensyukurinya) orang-orang kafir tidak mensyukuri ditangguhkannya azab atas mereka, karena mereka tidak mempercayai akan adanya azab itu.",[["وَإِنَّ","Dan sesungguhnya"],["رَبَّكَ","Tuhanmu"],["لَذُو","(adalah) penuh dengan Bounty"],["فَضْلٍ","(adalah) penuh dengan Bounty"],["عَلَى","bagi"],["ٱلنَّاسِ","umat manusia"],["وَلَـٰكِنَّ","tetapi"],["أَكْثَرَهُمْ","kebanyakan mereka"],["لَا","(adalah) tidak"],["يَشْكُرُونَ","bersyukur"]]],"3233":["(Dan sesungguhnya Rabbmu, benar-benar mengetahui apa yang disembunyikan hati mereka) maksudnya apa yang tersimpan di dalam hati mereka (dan apa yang mereka nyatakan) melalui lisan-lisan mereka.",[["وَإِنَّ","Dan sesungguhnya"],["رَبَّكَ","Tuhanmu"],["لَيَعْلَمُ","pasti tahu"],["مَا","apa"],["تُكِنُّ","menyembunyikan"],["صُدُورُهُمْ","buah dada mereka"],["وَمَا","dan apa"],["يُعْلِنُونَ","mereka mengisytiharkan"]]],"3234":["(Tiada sesuatu pun yang gaib di langit dan di bumi) huruf Ha pada lafal Ghaibah untuk menunjukkan makna Mubalaghah atau sangat, maksudnya sangat gaib di mata manusia (melainkan terdapat dalam kitab yang nyata) yakni Lohmahfuz dan rahasia ilmu Allah swt. antara lain diazabnya orang-orang kafir.",[["وَمَا","Dan bukan (adalah)"],["مِنْ","apa-apa (benda)"],["غَآئِبَةٍۢ","tersembunyi"],["فِى","dalam"],["ٱلسَّمَآءِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["إِلَّا","tetapi"],["فِى","(berada) dalam"],["كِتَـٰبٍۢ","sebuah Rekod"],["مُّبِينٍ","yang nyata"]]],"3235":["(Sesungguhnya Alquran ini menjelaskan kepada Bani Israel) yang ada di zaman Nabi saw. (sebagian besar dari perkara-perkara yang mereka berselisih tentangnya) dengan menjelaskan hal tersebut sesuai dengan kedudukannya, sehingga hilanglah semua perselisihan yang ada pada mereka, jika mereka mau mengambilnya dan masuk Islam.",[["إِنَّ","Sesungguhnya"],["هَـٰذَا","ini"],["ٱلْقُرْءَانَ","[al-Quran]."],["يَقُصُّ","mengaitkan"],["عَلَىٰ","kepada"],["بَنِىٓ","(the) Kanak-kanak"],["إِسْرَٰٓءِيلَ","(dari) Israel"],["أَكْثَرَ","kebanyakannya"],["ٱلَّذِى","(daripada) itu"],["هُمْ","mereka"],["فِيهِ","di dalamnya"],["يَخْتَلِفُونَ","berbeza"]]],"3236":["Dan sesungguhnya Alquran itu benar-benar menjadi petunjuk) dari kesesatan (dan rahmat bagi orang-orang yang beriman) yakni terhindar dari azab.",[["وَإِنَّهُۥ","Dan sesungguhnya, ia"],["لَهُدًۭى","(adalah) sesungguhnya petunjuk"],["وَرَحْمَةٌۭ","dan rahmat"],["لِّلْمُؤْمِنِينَ","untuk orang yang beriman"]]],"3237":["(Sesungguhnya Rabbmu akan menyelesaikan perkara di antara mereka) sama dengan orang-orang selain mereka, kelak di hari kiamat (dengan keputusan-Nya) dengan keadilan-Nya. (Dan Dia-lah yang Maha Perkasa) Maha Menang (lagi Maha Mengetahui) tentang ketentuan yang akan diputuskan-Nya, tidak mungkin bagi seorang pun menentangnya, tidak sebagaimana di dunia di mana orang-orang kafir masih dapat menentang Nabi-nabi-Nya.",[["إِنَّ","Sesungguhnya"],["رَبَّكَ","Tuhanmu"],["يَقْضِى","akan menilai"],["بَيْنَهُم","antara mereka"],["بِحُكْمِهِۦ ۚ","oleh PenghakimanNya"],["وَهُوَ","dan Dia"],["ٱلْعَزِيزُ","(ialah) Yang Maha Perkasa"],["ٱلْعَلِيمُ","yang Maha Mengetahui"]]],"3238":["(Sebab itu bertakwalah kepada Allah) percayakanlah kepada-Nya (sesungguhnya kamu berada di atas kebenaran yang nyata) yakni agama yang nyata, maka akibatnya kamulah yang akan mendapat kemenangan atas orang-orang kafir. Kemudian pada ayat selanjutnya Allah membuat perumpamaan tentang orang-orang kafir, sebagai orang-orang mati, tuli dan buta, untuk itu Allah swt. berfirman,",[["فَتَوَكَّلْ","Jadi letakkan kepercayaan kamu"],["عَلَى","dalam"],["ٱللَّهِ ۖ","Allah"],["إِنَّكَ","sesungguhnya, kamu"],["عَلَى","(ada) pada"],["ٱلْحَقِّ","kebenaran"],["ٱلْمُبِينِ","nyata"]]],"3239":["(\"Sesungguhnya kamu tidak dapat menjadikan orang-orang yang mati mendengar dan tidak pula menjadikan orang-orang yang tuli mendengar panggilan, apabila) dapat dibaca Tahqiq dan Tas-hil (mereka telah berpaling membelakang).",[["إِنَّكَ","Sesungguhnya kamu"],["لَا","(boleh) tidak"],["تُسْمِعُ","sebab dengar"],["ٱلْمَوْتَىٰ","yang mati"],["وَلَا","dan bukan"],["تُسْمِعُ","boleh kamu dengar"],["ٱلصُّمَّ","yang pekak"],["ٱلدُّعَآءَ","panggilan itu"],["إِذَا","apabila"],["وَلَّوْا۟","mereka berpatah balik"],["مُدْبِرِينَ","berundur"]]],"3240":["Dan kamu sekali-kali tidak dapat memimpin orang-orang buta dari kesesatan mereka, tidak lain kamu hanya dapat membuat mendengar) dengan pendengaran yang disertai pemahaman dan mau menerima apa yang didengarnya yaitu (orang-orang yang beriman kepada ayat-ayat Kami) kepada Alquran (lalu mereka berserah diri) mengikhlaskan diri mereka untuk mentauhidkan Allah.",[["وَمَآ","Dan tidak"],["أَنتَ","(boleh) kamu"],["بِهَـٰدِى","panduan"],["ٱلْعُمْىِ","yang buta"],["عَن","daripada"],["ضَلَـٰلَتِهِمْ ۖ","kesilapan mereka"],["إِن","Tidak"],["تُسْمِعُ","kamu boleh menyebabkan untuk mendengar"],["إِلَّا","kecuali"],["مَن","(mereka) yang"],["يُؤْمِنُ","beriman"],["بِـَٔايَـٰتِنَا","dalam Tanda-tanda Kami"],["فَهُم","jadi mereka"],["مُّسْلِمُونَ","(adalah) orang Islam"]]],"3241":["(Dan apabila perkataan telah jatuh atas mereka) yakni azab telah pasti menimpa mereka termasuk orang-orang kafir lainnya. (Kami keluarkan sejenis binatang melata dari bumi yang akan mengatakan kepada mereka) yaitu akan berbicara kepada orang-orang yang ada dari kalangan mereka; sewaktu binatang melata itu keluar ia langsung berbicara kepada mereka dengan memakai bahasa Arab. Dan garis besar dari apa yang dikatakannya itu ialah (bahwa sesungguhnya manusia) orang-orang kafir Mekah. Lafal Anna menurut qiraat yang lain dibaca Inna; qiraat ini dapat dipakai pula bilamana diperkirakan adanya huruf Ba sesudah lafal Tukallimuhum (dahulu tidak yakin kepada ayat-ayat Kami.\") mereka tidak beriman kepada Alquran yang di dalamnya disebutkan tentang adanya hari berbangkit, hari hisab amal perbuatan dan hari pembalasan. Dengan keluarnya binatang melata ini, maka terhentilah fungsi Amar Makruf dan Nahi Mungkar dan orang kafir yang beriman pada saat itu tidak dianggap lagi keimanannya, sebagaimana yang telah diwahyukan oleh Allah swt. kepada Nabi Nuh melalui firman-Nya, \"Bahwasanya sekali-kali, tidak akan beriman di antara kaummu, kecuali orang-orang yang telah beriman saja.\" (Q.S. 11 Hud, 36).",[["۞ وَإِذَا","Dan apabila"],["وَقَعَ","(sedang) dipenuhi"],["ٱلْقَوْلُ","perkataan itu"],["عَلَيْهِمْ","terhadap mereka"],["أَخْرَجْنَا","Kami akan melahirkan"],["لَهُمْ","bagi mereka"],["دَآبَّةًۭ","makhluk"],["مِّنَ","daripada"],["ٱلْأَرْضِ","bumi"],["تُكَلِّمُهُمْ","bercakap dengan mereka"],["أَنَّ","bahawa"],["ٱلنَّاسَ","manusia"],["كَانُوا۟","adalah"],["بِـَٔايَـٰتِنَا","daripada Tanda-tanda Kami"],["لَا","tidak"],["يُوقِنُونَ","pasti"]]],"3242":["(Dan) ingatlah (hari ketika Kami kumpulkan dari tiap-tiap umat segolongan) yakni sekumpulan (orang-orang yang mendustakan ayat-ayat Kami) mereka adalah pemimpin-pemimpin yang menjadi panutannya (lalu mereka dibagi-bagi) dikumpulkan dalam kelompok-kelompok kemudian mereka digiring.",[["وَيَوْمَ","Dan (hari) itu"],["نَحْشُرُ","Kami akan berkumpul"],["مِن","daripada"],["كُلِّ","setiap"],["أُمَّةٍۢ","bangsa"],["فَوْجًۭا","sebuah pasukan"],["مِّمَّن","daripada (mereka) yang"],["يُكَذِّبُ","menafikan"],["بِـَٔايَـٰتِنَا","Tanda-Tanda Kami"],["فَهُمْ","dan mereka"],["يُوزَعُونَ","akan ditetapkan dalam baris"]]],"3243":["Sehingga apabila mereka datang) di tempat perhitungan amal perbuatan (Allah berfirman) kepada mereka, (\"Apakah kalian telah mendustakan) nabi-nabi-Ku yang membawa (ayat-ayat-Ku, padahal tidak sampai ke sana) disebabkan kalian tidak mempercayainya (ilmu kalian, atau apakah) pada lafal Amma ini terdapat Ma Istifham yang diidgamkan kepada Am (yang) Dza di sini merupakan Isim Maushul, artinya apakah yang (telah kalian kerjakan?\") dari apa yang telah diperintahkan kepada kalian untuk melakukannya.",[["حَتَّىٰٓ","Sehinggalah"],["إِذَا","apabila"],["جَآءُو","mereka datang"],["قَالَ","Dia akan berkata"],["أَكَذَّبْتُم","Adakah kamu menafikan"],["بِـَٔايَـٰتِى","Tanda-tanda Aku"],["وَلَمْ","manakala tidak"],["تُحِيطُوا۟","kamu meliputi"],["بِهَا","mereka"],["عِلْمًا","(dalam) pengetahuan"],["أَمَّاذَا","atau apa"],["كُنتُمْ","kamu pernah (untuk)"],["تَعْمَلُونَ","lakukan"]]],"3244":["(Dan jatuhlah perkataan) yakni telah pasti azab (atas mereka disebabkan kelaliman mereka) disebabkan kemusyrikan mereka (maka mereka tidak dapat berkata apa-apa) karena mereka tidak mempunyai argumentasi.",[["وَوَقَعَ","Dan (akan) dipenuhi"],["ٱلْقَوْلُ","perkataan itu"],["عَلَيْهِم","terhadap mereka"],["بِمَا","kerana"],["ظَلَمُوا۟","mereka melakukan kesalahan"],["فَهُمْ","dan mereka"],["لَا","(akan) tidak"],["يَنطِقُونَ","bercakap"]]],"3245":["(Apakah mereka tidak memperhatikan, bahwa sesungguhnya Kami telah menjadikan) maksudnya telah menciptakan (malam supaya mereka beristirahat padanya) sama dengan orang-orang lain (dan siang yang menerangi?) supaya mereka dapat berusaha padanya. (Sesuugguhnya pada yang demikian itu terdapat tanda-tanda) yang menunjukkan kekuasaan Allah swt. (bagi orang-orang yang beriman) di sini hanya disebutkan mereka yang beriman, karena hanya mereka sajalah yang dapat mengambil manfaat dari hal ini untuk mempertebal keimanan mereka, berbeda halnya dengan orang-orang kafir.",[["أَلَمْ","Jangan"],["يَرَوْا۟","mereka lihat"],["أَنَّا","bahawa Kami"],["جَعَلْنَا","[Kami] telah buat"],["ٱلَّيْلَ","malam"],["لِيَسْكُنُوا۟","supaya mereka boleh berehat"],["فِيهِ","di dalamnya"],["وَٱلنَّهَارَ","dan hari"],["مُبْصِرًا ۚ","memberi keterlihatan"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَـٰتٍۢ","sesungguhnya (adalah) tanda-tanda"],["لِّقَوْمٍۢ","bagi kaum"],["يُؤْمِنُونَ","yang beriman"]]],"3246":["(Dan hari ketika ditiup sangkakala) tiupan sangkakala malaikat Israfil yang pertama (maka terkejutlah segala yang di langit dan segala yang di bumi) mereka ketakutan, sehingga ketakutan itu mematikan mereka, sebagaimana yang diungkapkan oleh ayat lainnya, yaitu dengan ungkapan Sha'iqa, yakni terkejut yang mematikan. Dan ungkapan dalam ayat ini dipakai Fi'il Madhi untuk menggambarkan kepastian terjadinya hal ini (kecuali siapa yang dikehendaki Allah) yaitu malaikat Jibril, malaikat Mikail, malaikat Israfil dan malaikat Maut. Tetapi menurut suatu riwayat yang bersumber dari sahabat Ibnu Abbas disebutkan, bahwa mereka yang tidak terkejut adalah para Syuhada, karena mereka hidup di sisi Rabb mereka dengan diberi rezeki. (Dan semua mereka) lafal Kullun ini harakat Tanwinnya merupakan pergantian daripada Mudhaf Ilaih, artinya mereka semua sesudah dihidupkan kembali di hari kiamat (datang menghadap kepada-Nya) dapat dibaca Atauhu dan Atuhu (dengan merendahkan diri) artinya merasa rendah diri. Dan ungkapan lafal Atauhu dengan memakai Fi'il Madhi untuk menunjukkan, bahwa hal itu pasti terjadi.",[["وَيَوْمَ","Dan (hari) itu"],["يُنفَخُ","akan ditiup"],["فِى","[dalam]"],["ٱلصُّورِ","sangkakala"],["فَفَزِعَ","dan akan ketakutan"],["مَن","sesiapa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَن","dan sesiapa"],["فِى","(berada) dalam"],["ٱلْأَرْضِ","bumi"],["إِلَّا","kecuali"],["مَن","yang"],["شَآءَ","Allah berkehendak"],["ٱللَّهُ ۚ","Allah berkehendak"],["وَكُلٌّ","Dan semua"],["أَتَوْهُ","(akan) datang kepada-Nya"],["دَٰخِرِينَ","merendah diri"]]],"3247":["(Dan kamu lihat gunung-gunung itu) yakni kamu saksikan gunung-gunung itu sewaktu terjadinya tiupan malaikat Israfil (kamu sangka dia) (tetap) diam di tempatnya karena besarnya (padahal ia berjalan sebagai jalannya awan) bagaikan hujan yang tertiup angin, maksudnya gunung-gunung itu tampak seolah-olah tetap, padahal berjalan lambat saking besarnya, kemudian jatuh ke bumi lalu hancur lebur kemudian menjadi abu bagaikan bulu-bulu yang beterbangan. (Begitulah perbuatan Allah) lafal Shun'a merupakan Mashdar yang mengukuhkan jumlah sebelumnya yang kemudian di-mudhaf-kan kepada Fa'il-nya Sesudah 'Amil-nya dibuang, bentuk asalnya ialah Shana'allahu Dzalika Shun'an. Selanjutnya hanya disebutkan lafal Shun'a yang kemudian dimudhaf-kan kepada Fa'il-nya yaitu lafal Allah, sehingga jadilah Shun'allahi; artinya begitulah perbuatan Allah (yang membuat dengan kokoh) rapih dan kokoh (tiap-tiap sesuatu) yang dibuat-Nya (sesungguhnya Allah Maha Mengetahui apa yang kalian kerjakan) lafal Taf'aluna dapat dibaca Yaf'aluna, yakni perbuatan maksiat yang dilakukan oleh musuh-musuh-Nya dan perbuatan taat yang dilakukan oleh kekasih-kekasih-Nya.",[["وَتَرَى","Dan kamu lihat"],["ٱلْجِبَالَ","pergunungan"],["تَحْسَبُهَا","memikirkan mereka"],["جَامِدَةًۭ","tetap kukuh"],["وَهِىَ","sedangkan mereka"],["تَمُرُّ","akan berlalu"],["مَرَّ","(sebagai) berlalu"],["ٱلسَّحَابِ ۚ","(dari) awan"],["صُنْعَ","(The) Kerja"],["ٱللَّهِ","(milik) Allah"],["ٱلَّذِىٓ","Siapa"],["أَتْقَنَ","disempurnakan"],["كُلَّ","semua"],["شَىْءٍ ۚ","benda"],["إِنَّهُۥ","Sesungguhnya Dia"],["خَبِيرٌۢ","(adalah) Maha Mengetahui"],["بِمَا","tentang apa"],["تَفْعَلُونَ","kamu lakukan"]]],"3248":["(Barang siapa yang membawa kebaikan) yakni membawa pengamalan kalimah \"La ilaha illallah\" kelak di hari kiamat (maka ia memperoleh kebaikan) pahala (daripadanya) disebabkan, lafal Khairun di sini bukan mengandung arti Tafdhil, karena tiada suatu pekerjaan pun yang lebih baik daripadanya. Di dalam ayat lain disebutkan bahwa pahala itu ialah sepuluh kali lipat daripadanya (sedangkan mereka) orang-orang yang datang membawanya (daripada kejutan yang dahsyat pada hari itu) dapat dibaca Faza'i Yaumaidzin dan Faza'in Yaumaidzin (merasa aman tenteram).",[["مَن","Siapa pun"],["جَآءَ","datang"],["بِٱلْحَسَنَةِ","dengan kebaikan"],["فَلَهُۥ","kemudian untuk dia"],["خَيْرٌۭ","(akan menjadi) lebih baik"],["مِّنْهَا","daripadanya"],["وَهُم","dan mereka"],["مِّن","daripada"],["فَزَعٍۢ","(yang) keganasan"],["يَوْمَئِذٍ","(pada) hari itu"],["ءَامِنُونَ","(akan) selamat"]]],"3249":["(Dan barang siapa yang membawa kejahatan) yakni kemusyrikan (maka disungkurkanlah muka mereka ke dalam neraka) disebabkan berpaling daripadanya. Di sini hanya disebutkan muka, karena merupakan anggota tubuh yang paling mulia, pengertiannya; semua anggota tubuhnya lebih disungkurkan lagi. Kemudian dikatakan kepada mereka dengan nada mencemoohkan. (Tiadalah kalian dibalasi melainkan) pembalasan yang setimpal (dengan apa yang dahulu kamu sekalian kerjakan) berupa kemusyrikan dan kemaksiatan. Katakanlah kepada mereka,",[["وَمَن","Dan sesiapa"],["جَآءَ","datang"],["بِٱلسَّيِّئَةِ","dengan kejahatan"],["فَكُبَّتْ","akan dibuang"],["وُجُوهُهُمْ","muka mereka"],["فِى","dalam"],["ٱلنَّارِ","neraka"],["هَلْ","Adakah"],["تُجْزَوْنَ","kamu membalasnya"],["إِلَّا","kecuali"],["مَا","(untuk) apa"],["كُنتُمْ","kamu pernah (untuk)"],["تَعْمَلُونَ","lakukan"]]],"3250":["(\"Aku hanya diperintahkan untuk menyembah Rabb negeri ini) yakni Mekah (yang telah menjadihannya kota suci) suci dan aman, tidak boleh dialirkan darah manusia di dalamnya, dan tidak boleh seseorang pun dianiaya, serta binatang buruannya tidak boleh diburu dan pepohonannya tidak boleh ditebang. Yang demikian itu merupakan nikmat-nikmat Allah yang dilimpahkan kepada kabilah Quraisy sebagai penduduknya, sehingga Allah tidak menurunkan azab atas negeri mereka dan selamat Pula dari fitnah-fitnah yang melanda kawasan negeri Arab lainnya (dan kepunyaan-Nya-lah) yakni kepunyaan Allah swt. (segala sesuatu) Dia adalah Rabb, pencipta dan pemilik semuanya (dan aku diperintahkan supaya aku termasuk orang-orang yang berserah diri) kepada Allah yaitu dengan mentauhidkan-Nya.",[["إِنَّمَآ","Hanya"],["أُمِرْتُ","aku diperintah"],["أَنْ","bahawa"],["أَعْبُدَ","aku menyembah"],["رَبَّ","(yang) Tuhan"],["هَـٰذِهِ","(dari) ini"],["ٱلْبَلْدَةِ","bandar"],["ٱلَّذِى","yang Esa"],["حَرَّمَهَا","menjadikannya suci"],["وَلَهُۥ","dan kepunyaan-Nya"],["كُلُّ","semua"],["شَىْءٍۢ ۖ","benda"],["وَأُمِرْتُ","Dan aku diperintahkan"],["أَنْ","bahawa"],["أَكُونَ","aku jadi"],["مِنَ","daripada"],["ٱلْمُسْلِمِينَ","kaum muslimin"]]],"3251":["(Dan supaya aku membacakan Alquran) kepada kalian dengan bacaan yang mengajak kalian untuk beriman (Maka barang siapa yang mendapat petunjuk) dari Alquran (maka sesungguhnya ia hanyalah mendapat petunjuk untuk kebaikan dirinya) karena dia sendirilah yang mendapat kan pahalanya (dan barang siapa yang sesat) dari jalan iman, dan sesat dari jalan petunjuk (maka katakanlah) kepadanya, ('Sesungguhnya aku ini tidak lain hanyalah salah seorang pemberi peringatan.'\") yang menakut-nakuti kalian, maka tidak ada hak bagiku melainkan hanya menyampaikan saja. Ayat ini diturunkan sebelum ada perintah dari Allah untuk berperang.",[["وَأَنْ","Dan bahawa"],["أَتْلُوَا۟","aku mengaji"],["ٱلْقُرْءَانَ ۖ","al-Quran"],["فَمَنِ","Dan sesiapa"],["ٱهْتَدَىٰ","menerima hidayah"],["فَإِنَّمَا","kemudian sahaja"],["يَهْتَدِى","dia menerima hidayah"],["لِنَفْسِهِۦ ۖ","untuk dirinya sendiri"],["وَمَن","dan sesiapa"],["ضَلَّ","sesat"],["فَقُلْ","kemudian berkata"],["إِنَّمَآ","Hanya"],["أَنَا۠","aku"],["مِنَ","daripada"],["ٱلْمُنذِرِينَ","para pemberi amaran"]]],"3252":["(Dan katakanlah!, \"Segala puji bagi Allah, Dia akan memperlihatkan kepada kalian tanda-tanda kebesaran-Nya, maka kalian akan mengetahuinya) Allah memperlihatkannya kepada mereka dalam perang Badar, yaitu dengan dibunuhnya mereka dan sebagian lagi ada yang tertawan, serta para Malaikat memukuli muka dan belakang mereka, dan Allah menyegerakan mereka untuk masuk ke dalam neraka. (Dan Rabbmu tiada lalai dari apa yang kalian kerjakan.\") lafal Taa'maluna dapat dibaca Ya'maluna. Dan sesungguhnya Allah menangguhkan mereka hanya sampai pada saatnya saja.",[["وَقُلِ","Dan katakan"],["ٱلْحَمْدُ","Segala puji (semoga)"],["لِلَّهِ","kepada Allah"],["سَيُرِيكُمْ","Dia akan menunjukkan kepada kamu"],["ءَايَـٰتِهِۦ","Tanda-tandaNya"],["فَتَعْرِفُونَهَا ۚ","dan kamu akan mengenali mereka"],["وَمَا","Dan Tuhanmu tidak"],["رَبُّكَ","Dan Tuhanmu tidak"],["بِغَـٰفِلٍ","tak sedar"],["عَمَّا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"]]],"3253":["(Tha Sin Mim) hanya Allah-lah yang mengetahui maksudnya.",[["طسٓمٓ","Ta Seem Meem"]]],"3254":["(Ini adalah) (ayat-ayat Kitab) sebagian dari Alquran (yang nyata) untuk membedakan antara perkara yang hak dengan perkara yang batil.",[["تِلْكَ","Ini"],["ءَايَـٰتُ","(adalah) Ayat-ayat"],["ٱلْكِتَـٰبِ","Kitab"],["ٱلْمُبِينِ","yang jelas"]]],"3255":["(Kami membacakan) Kami menceritakan (kepadamu sebagian dari kisah) yakni cerita (Musa dan Firaun dengan benar) dengan sebenarnya (untuk orang-orang yang beriman) untuk kepentingan mereka, karena hanya merekalah orang-orang yang dapat mengambil manfaat daripadanya.",[["نَتْلُوا۟","Kami mengaji"],["عَلَيْكَ","kepada kamu"],["مِن","daripada"],["نَّبَإِ","(the) berita"],["مُوسَىٰ","(dari) Musa"],["وَفِرْعَوْنَ","dan Firaun"],["بِٱلْحَقِّ","dalam kebenaran"],["لِقَوْمٍۢ","bagi kaum"],["يُؤْمِنُونَ","yang beriman"]]],"3256":["(Sesungguhnya Firaun telah berbuat sewenang-wenang) yaitu berbuat zalim (di muka bumi) di negeri Mesir (dan menjadikan penduduknya berpecah-belah) maksudnya terpecah-pecah, semuanya berkhidmat kepada dirinya (dengan menindas segolongan dari mereka) yakni kaum Bani Israel (menyembelih anak laki-laki mereka) yang baru dilahirkan (dan membiarkan hidup anak-anak perempuan mereka) karena juru peramal telah mengatakan kepada Firaun, bahwa akan ada seorang anak lelaki yang akan dilahirkan di Bani Israel, ia bakal menjadi penyebab hilangnya takhta kerajaan. (Sesungguhnya Firaun termasuk orang-orang yang berbuat kerusakan) yakni gemar membunuh dan melakukan perbuatan-perbuatan kejam lainnya",[["إِنَّ","Sesungguhnya"],["فِرْعَوْنَ","Firaun"],["عَلَا","meninggikan dirinya"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَجَعَلَ","dan dibuat"],["أَهْلَهَا","rakyatnya"],["شِيَعًۭا","(menjadi) mazhab"],["يَسْتَضْعِفُ","menindas"],["طَآئِفَةًۭ","satu kumpulan"],["مِّنْهُمْ","antara mereka"],["يُذَبِّحُ","penyembelihan"],["أَبْنَآءَهُمْ","anak lelaki mereka"],["وَيَسْتَحْىِۦ","dan membiarkan hidup"],["نِسَآءَهُمْ ۚ","wanita mereka"],["إِنَّهُۥ","Sesungguhnya dia"],["كَانَ","adalah"],["مِنَ","daripada"],["ٱلْمُفْسِدِينَ","para perasuah"]]],"3257":["(Dan Kami hendak memberi karunia kepada orang-orang yang tertindas di bumi Mesir itu dan hendak menjadikan mereka pemimpin) menjadi panutan dalam hal kebaikan; lafal A-immatan dapat dibaca Tahqiq dan Tas-hil (dan menjadikan mereka orang-orang yang mewarisi) kerajaan Firaun.",[["وَنُرِيدُ","Dan Kami mahu"],["أَن","kepada"],["نَّمُنَّ","melimpahkan nikmat"],["عَلَى","ke atas"],["ٱلَّذِينَ","orang yang"],["ٱسْتُضْعِفُوا۟","telah ditindas"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَنَجْعَلَهُمْ","dan buat mereka"],["أَئِمَّةًۭ","pemimpin"],["وَنَجْعَلَهُمُ","dan buat mereka"],["ٱلْوَٰرِثِينَ","para pewaris"]]],"3258":["(Dan akan Kami teguhkan kedudukan mereka di muka bumi) di negeri Mesir dan negeri Syam (Dan akan Kami perlihatkan kepada Firaun dan Haman beserta tentaranya) menurut qiraat yang lain dibaca Wa Yara Firaunu Wa Hamanu Wa Junuduhuma (apa yang selalu mereka khawatirkan dari mereka itu) tentang bayi yang akan lahir, yang kelak akan melenyapkan kerajaannya.",[["وَنُمَكِّنَ","Dan [Kami] tetapkan"],["لَهُمْ","mereka"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَنُرِىَ","dan tunjukkan"],["فِرْعَوْنَ","Firaun"],["وَهَـٰمَـٰنَ","dan Haman"],["وَجُنُودَهُمَا","dan tuan rumah mereka"],["مِنْهُم","melalui mereka"],["مَّا","apa"],["كَانُوا۟","mereka adalah"],["يَحْذَرُونَ","takut"]]],"3259":["(Dan kami ilhamkan) wahyu berupa ilham atau ilham melalui mimpi (kepada ibu Musa) Musa adalah bayi yang dimaksud oleh peramal Firaun, dan tidak ada seorang pun mengetahui kelahirannya selain saudara perempuannya sendiri. (\"Susukanlah dia! Apabila kamu khawatir terhadapnya maka hanyutkanlah dia ke dalam sungai) yakni sungai Nil (dan janganlah kamu khawatir) ia akan tenggelam (dan janganlah bersedih hati) karena berpisah dengan bayimu itu (karena sesungguhnya Kami akan mengembalikannya kepadamu, dan menjadikannya salah seorang dari para Rasul.\") maka ibu Musa menyusukan Musa selama tiga bulan, selama itu Musa tidak pernah menangis. Akhirnya ibu Musa merasa khawatir akan keselamatan Musa, lalu ia menaruh Musa yang masih bayi itu ke dalam sebuah peti dilapisi dengan ter/aspal sebelah dalamnya, supaya air jangan masuk lalu dihanyutkan ke sungai Nil, di waktu malam hari.",[["وَأَوْحَيْنَآ","Dan Kami ilhamkan"],["إِلَىٰٓ","[ke]"],["أُمِّ","(si) ibu"],["مُوسَىٰٓ","(dari) Musa"],["أَنْ","bahawa"],["أَرْضِعِيهِ ۖ","susukan dia"],["فَإِذَا","tapi apabila"],["خِفْتِ","kamu takut"],["عَلَيْهِ","baginya"],["فَأَلْقِيهِ","kemudian melemparkannya"],["فِى","dalam (ke)"],["ٱلْيَمِّ","sungai itu"],["وَلَا","dan jangan"],["تَخَافِى","bertakwa"],["وَلَا","dan jangan"],["تَحْزَنِىٓ ۖ","bersedih"],["إِنَّا","Sesungguhnya Kami"],["رَآدُّوهُ","(akan) memulihkannya"],["إِلَيْكِ","kepada kamu"],["وَجَاعِلُوهُ","dan (akan) menjadikannya"],["مِنَ","daripada"],["ٱلْمُرْسَلِينَ","para Rasul"]]],"3260":["(Maka ia dipungut) berikut petinya pada keesokan harinya (oleh keluarga) yakni pembantu-pembantu (Firaun) lalu peti itu diletakkan di hadapan Firaun dan Musa dikeluarkan dari dalam peti, di kala itu Musa sedang mengisap jempolnya dari jempol itu keluar air susu (yang akibatnya dia bagi mereka akan menjadi) pada akhirnya Musa akan menjadi (musuh) kelak akan membunuh kaum laki-laki mereka (dan kesedihan) karena akan menindas kaum wanita mereka. Lafal Hazanan di sini bermakna Isim Fa'il karena diambil dari lafal Hazinahu yang semakna dengan lafal Ahzanahu. (Sesungguhnya Firaun dan Haman) pembantu Firaun (beserta tentaranya adalah orang-orang yang bersalah). Lafal Khathi-ina berasal dari Al Khathi-ah, artinya orang-orang yang durhaka, maka mereka dihukum oleh perbuatannya sendiri.",[["فَٱلْتَقَطَهُۥٓ","Kemudian mengangkatnya"],["ءَالُ","(keluarga)."],["فِرْعَوْنَ","(daripada) Firaun"],["لِيَكُونَ","supaya dia menjadi"],["لَهُمْ","kepada mereka"],["عَدُوًّۭا","seorang musuh"],["وَحَزَنًا ۗ","dan kesedihan"],["إِنَّ","Sesungguhnya"],["فِرْعَوْنَ","Firaun"],["وَهَـٰمَـٰنَ","dan Haman"],["وَجُنُودَهُمَا","dan tuan rumah mereka"],["كَانُوا۟","adalah"],["خَـٰطِـِٔينَ","orang berdosa"]]],"3261":["(Dan istri Firaun berkata) di kala Firaun beserta para pembantunya sudah bersiap-siap akan membunuh bayi itu, \"Ia adalah (biji mata bagiku dan bagimu, janganlah kalian membunuhnya, mudah-mudahan ia bermanfaat kepada kita atau kita ambil ia menjadi anak\") akhirnya mereka menuruti kemauan istri Firaun itu (sedangkan mereka tiada menyadari) akibat dari perkara mereka dengan bayi itu.",[["وَقَالَتِ","Dan berkata"],["ٱمْرَأَتُ","(si) isteri"],["فِرْعَوْنَ","(daripada) Firaun"],["قُرَّتُ","Satu keselesaan"],["عَيْنٍۢ","(dari) mata"],["لِّى","untuk aku"],["وَلَكَ ۖ","dan untuk kamu"],["لَا","Jangan"],["تَقْتُلُوهُ","bunuh dia"],["عَسَىٰٓ","mungkin"],["أَن","(itu)"],["يَنفَعَنَآ","dia boleh memberi manfaat kepada kita"],["أَوْ","atau"],["نَتَّخِذَهُۥ","kita boleh bawa dia"],["وَلَدًۭا","(sebagai) anak lelaki"],["وَهُمْ","Dan mereka"],["لَا","(tidak) tidak"],["يَشْعُرُونَ","mempersepsikan"]]],"3262":["(Dan hati ibu Musa menjadi) setelah ia mengetahui bahwa bayinya telah diambil (kosong) tidak memikirkan selain daripada bayinya. (Sesungguhnya) lafal in di sini adalah bentuk Takhfif daripada Inna, sedangkan Isimnya dibuang, pada asalnya adalah Innaha, yakni sesungguhnya ibu Musa (hampir saja ia menyatakan rahasia tentang Musa) bahwa bayi itu adalah anaknya (seandainya tidak Kami teguhkan hatinya) dengan kesabaran, yakni Kami jadikan hatinya tenang (supaya ia termasuk orang-orang yang percaya) kepada janji Allah. Jawab dari lafal Laula dapat disimpulkan dari pengertian kalimat sebelumnya.",[["وَأَصْبَحَ","Dan menjadi"],["فُؤَادُ","(hati)."],["أُمِّ","(daripada) ibu"],["مُوسَىٰ","(dari) Musa"],["فَـٰرِغًا ۖ","kosong"],["إِن","Itu"],["كَادَتْ","dia dekat"],["لَتُبْدِى","(untuk) mendedahkan"],["بِهِۦ","tentang dia"],["لَوْلَآ","jika tidak"],["أَن","bahawa"],["رَّبَطْنَا","Kami menguatkan"],["عَلَىٰ","[lebih]"],["قَلْبِهَا","hatinya"],["لِتَكُونَ","supaya dia menjadi"],["مِنَ","daripada"],["ٱلْمُؤْمِنِينَ","orang yang beriman"]]],"3263":["(Dan ibu Musa berkata kepada saudara perempuan Musa) bernama Maryam, (\"Ikutilah dia\") maksudnya ikutilah jejaknya sehingga kamu mengetahui bagaimana kesudahan beritanya. (Maka kelihatanlah olehnya Musa) dia mengawasinya (dari jauh) dari tempat yang jauh seraya menguntitnya (sedangkan mereka tidak mengetahui) bahwa dia adalah saudara perempuan dari bayi tersebut, dan bahwasanya keberadaannya itu adalah untuk mengikuti jejaknya.",[["وَقَالَتْ","Dan dia berkata"],["لِأُخْتِهِۦ","kepada kakaknya"],["قُصِّيهِ ۖ","Ikut dia"],["فَبَصُرَتْ","Jadi dia memerhati"],["بِهِۦ","dia"],["عَن","daripada"],["جُنُبٍۢ","satu jarak"],["وَهُمْ","sedangkan mereka"],["لَا","(tidak) tidak"],["يَشْعُرُونَ","mempersepsikan"]]],"3264":["(Dan Kami cegah Musa menyusu kepada perempuan-perempuan yang mau menyusukannya sebelum itu) maksudnya sebelum ia kembali berada di tangan ibunya. Yakni, Kami cegah dia untuk menerima air susu perempuan-perempuan yang mau menyusuinya selain dari air susu ibunya sendiri. Maka Nabi Musa menolak semua air susu perempuan-perempuan yang dihadirkan untuk menyusuinya (maka berkatalah ia) yakni saudara perempuan Musa, (\"Maukah kalian aku tunjukkan kepada ahlul bait) ketika dia melihat mereka menaruh rasa belas kasihan kepada Musa (yang akan memeliharanya untuk kalian) yakni, yang akan menyusuinya dan mengurusnya (dan mereka dapat berlaku baik kepadanya?\") menurut penafsiran lain Dhamir Lahu kembali kepada Raja Firaun, sebagai reaksi dari para pembantunya. Maksudnya setelah mereka mendengar usul saudara Musa, maka mereka menyetujui dan memperkuatnya dengan mengatakannya pula kepada Raja Firaun. Akhirnya permintaan Maryam dikabulkan, ia datang membawa ibu Musa, ternyata Musa mau menerima air susunya. Kemudian Maryam. memberikan pendapat kepada mereka, bahwa ibu Musa adalah seorang wanita yang harum baunya dan baik air susunya. Maka ibu Musa diizinkan untuk menyusuinya di rumahnya sendiri, akhirnya ibu Musa kembali membawa bayinya. Sebagaimana yang diungkapkan oleh firman-Nya,",[["۞ وَحَرَّمْنَا","Dan telah Kami haramkan"],["عَلَيْهِ","baginya"],["ٱلْمَرَاضِعَ","jururawat basah"],["مِن","sebelum"],["قَبْلُ","sebelum"],["فَقَالَتْ","jadi dia berkata"],["هَلْ","Adakah aku"],["أَدُلُّكُمْ","mengarahkan kamu"],["عَلَىٰٓ","kepada"],["أَهْلِ","kaum"],["بَيْتٍۢ","(dari) sebuah rumah"],["يَكْفُلُونَهُۥ","siapa yang akan membesarkannya"],["لَكُمْ","bagi kamu"],["وَهُمْ","sedangkan mereka"],["لَهُۥ","kepadanya"],["نَـٰصِحُونَ","(akan) ikhlas"]]],"3265":["(Maka Kami kembalikan Musa kepada ibunya supaya senang hatinya) karena bertemu kembali dengannya (dan tidak berduka cita) setelah itu (dan supaya ia mengetahui bahwa janji Allah itu) yang akan mengembalikan Musa kepadanya (adalah benar, tetapi kebanyakan mereka) yakni manusia (tidak mengetahui) janji ini, dan mereka tidak pula mengetahui, bahwa Maryam adalah saudara Musa dan wanita yang dibawanya adalah ibunya sendiri. Kemudian Musa tinggal bersama ibunya sampai masa penyapihan; setiap hari ibu Musa menerima upah pekerjaan menyusuinya sebanyak satu Dinar. Ibu Musa mau menerimanya karena menganggap bahwa uang itu adalah harta perang. Setelah itu ia membawanya kembali kepada Firaun, sejak itu Musa dibesarkan di lingkungan istana Firaun, sebagaimana yang telah diungkapkan oleh firman-Nya sewaktu menceritakan tentang Musa dalam surah Asy Syu'ara, yaitu, \"Bukankah kami telah mengasuhmu di dalam (keluarga) kami waktu kamu masih kanak-kanak dan kamu tinggal bersama kami beberapa tahun dari umurmu.\" (Q.S. Asy Syu'ara, 18).",[["فَرَدَدْنَـٰهُ","Maka Kami kembalikan dia"],["إِلَىٰٓ","kepada"],["أُمِّهِۦ","ibunya"],["كَىْ","bahawa"],["تَقَرَّ","mungkin terhibur"],["عَيْنُهَا","matanya"],["وَلَا","dan bukan"],["تَحْزَنَ","dia mungkin bersedih"],["وَلِتَعْلَمَ","dan dia akan tahu"],["أَنَّ","bahawa"],["وَعْدَ","Janji Allah"],["ٱللَّهِ","Janji Allah"],["حَقٌّۭ","(adalah) benar"],["وَلَـٰكِنَّ","Tetapi"],["أَكْثَرَهُمْ","kebanyakan mereka"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"3266":["(Dan setelah Musa cukup umur) telah mencapai umur tiga puluh tahun atau tiga puluh tiga tahun (dan sempurna akalnya) yaitu telah mencapai umur empat puluh tahun (Kami berikan kepadanya hikmah) yakni kebijaksanaan (dan ilmu) yaitu pengetahuan tentang agama sebelum ia diutus menjadi Nabi. (Dan demikianlah) Kami memberikan balasan kepada Musa (Kami memberi balasan kepada orang-orang yang berbuat baik) untuk diri mereka sendiri.",[["وَلَمَّا","Dan apabila"],["بَلَغَ","dia sampai"],["أَشُدَّهُۥ","kekuatan penuhnya"],["وَٱسْتَوَىٰٓ","dan menjadi matang"],["ءَاتَيْنَـٰهُ","Kami kurniakan kepadanya"],["حُكْمًۭا","kebijaksanaan"],["وَعِلْمًۭا ۚ","dan pengetahuan"],["وَكَذَٰلِكَ","Dan dengan demikian"],["نَجْزِى","Kami memberi ganjaran"],["ٱلْمُحْسِنِينَ","orang yang berbuat baik"]]],"3267":["(Dan masuklah) Musa (ke kota) yakni ke kota Firaun, yaitu kota Memphis, sesudah sekian lama ia meninggalkannya (ketika penduduknya sedang lengah) yaitu, pada saat orang-orang istirahat di siang hari (maka didapatinya di dalam kota itu dua orang laki-laki yang berkelahi; yang seorang dari bangsanya) dari kalangan Bani Israel (dan seorang lagi dari musuhnya) yakni, seorang bangsa Mesir. Pada mulanya orang Mesir itu menghina warga Bani Israel itu sewaktu orang Mesir itu menyuruhnya untuk membawa kayu bakar ke dapur raja Firaun. (Maka orang yang dari bangsanya meminta pertolongan kepadanya, untuk mengalahkan orang yang dari musuhnya) Musa berkata kepada orang Mesir itu, \"Lepaskanlah dia dan biarkan dia pergi!\". Menurut suatu riwayat disebutkan, bahwa orang Mesir itu berkata kepada Musa, \"Sungguh aku berniat untuk menyeretnya ke hadapanmu\" (lalu Musa meninjunya) memukulnya dengan kepalan tangannya. Musa sangat kuat lagi keras pukulannya (dan musuhnya itupun mati). Musa telah membunuhnya, padahal Musa tidak bermaksud untuk membunuh, lalu ia menguburnya di dalam pasir (Musa berkata, \"Ini adalah) membunuh orang ini (perbuatan setan) yang telah menggelorakan amarahku (sesungguhnya setan itu adalah musuh) bagi anak Adam (yang menyesatkan) dia (lagi nyata.\") permusuhannya.",[["وَدَخَلَ","Dan dia masuk"],["ٱلْمَدِينَةَ","bandar itu"],["عَلَىٰ","di"],["حِينِ","suatu masa"],["غَفْلَةٍۢ","(dari) ketidakpedulian"],["مِّنْ","daripada"],["أَهْلِهَا","rakyatnya"],["فَوَجَدَ","dan dijumpai"],["فِيهَا","di dalamnya"],["رَجُلَيْنِ","dua orang lelaki"],["يَقْتَتِلَانِ","bergaduh sesama sendiri"],["هَـٰذَا","ini"],["مِن","daripada"],["شِيعَتِهِۦ","partinya"],["وَهَـٰذَا","dan ini"],["مِنْ","daripada"],["عَدُوِّهِۦ ۖ","musuhnya"],["فَٱسْتَغَـٰثَهُ","Dan memanggilnya untuk meminta pertolongan"],["ٱلَّذِى","orang yang"],["مِن","(adalah) daripada"],["شِيعَتِهِۦ","partinya"],["عَلَى","terhadap"],["ٱلَّذِى","orang yang"],["مِنْ","(adalah) daripada"],["عَدُوِّهِۦ","musuhnya"],["فَوَكَزَهُۥ","maka Musa memukulnya dengan penumbuknya"],["مُوسَىٰ","maka Musa memukulnya dengan penumbuknya"],["فَقَضَىٰ","dan membunuhnya"],["عَلَيْهِ ۖ","dan membunuhnya"],["قَالَ","Dia berkata"],["هَـٰذَا","ini (ialah)"],["مِنْ","daripada"],["عَمَلِ","(perbuatan) itu"],["ٱلشَّيْطَـٰنِ ۖ","(dari) Syaitan"],["إِنَّهُۥ","Sesungguhnya dia"],["عَدُوٌّۭ","(adalah) musuh"],["مُّضِلٌّۭ","seorang yang menyesatkan"],["مُّبِينٌۭ","dengan jelas"]]],"3268":["(Musa berkata,) seraya menyesal (\"Ya Rabbku! Sesungguhnya aku telah menganiaya diriku sendiri) karena telah membunuh orang Mesir itu (karena itu ampunilah aku.\" Maka Allah mengampuninya, Sesungguhnya Dia adalah Yang Maha Pengampun lagi Maha Penyayang). Dia bersifat demikian sejak zaman Azali dan untuk selama-lamanya.",[["قَالَ","Dia berkata"],["رَبِّ","Tuhanku"],["إِنِّى","Sesungguhnya aku"],["ظَلَمْتُ","[Aku] telah berbuat salah"],["نَفْسِى","jiwa aku"],["فَٱغْفِرْ","jadi maafkan"],["لِى","[untuk] aku"],["فَغَفَرَ","Kemudian Dia mengampuni"],["لَهُۥٓ ۚ","[untuk] dia"],["إِنَّهُۥ","Sesungguhnya Dia"],["هُوَ","dia (adalah)"],["ٱلْغَفُورُ","Yang Maha Pengampun"],["ٱلرَّحِيمُ","Yang Maha Mengasihani"]]],"3269":["(Musa berkata, \"Ya Rabbku! Demi nikmat yang telah Engkau limpahkan) (kepadaku) berupa ampunan, peliharalah diriku ini (aku sekali-kali tiada akan menjadi penolong) yakni menjadi pembantu (bagi orang-orang yang berdosa.\") yaitu orang-orang kafir sesudah peristiwa ini, jika Engkau memelihara diriku.",[["قَالَ","Dia berkata"],["رَبِّ","Tuhanku"],["بِمَآ","Kerana"],["أَنْعَمْتَ","Kamu telah memihak"],["عَلَىَّ","[pada] aku"],["فَلَنْ","jadi tidak"],["أَكُونَ","aku akan jadi"],["ظَهِيرًۭا","seorang penyokong"],["لِّلْمُجْرِمِينَ","(dari) penjenayah"]]],"3270":["(Karena itu, jadilah Musa di kota itu merasa takut menunggu-nunggu dengan khawatir) apa yang bakal dilakukan oleh keluarga orang yang telah dibunuhnya itu terhadap dirinya (maka tiba-tiba orang yang meminta pertolongan kemarin berteriak-teriak meminta pertolongan kepadanya) maksudnya minta tolong lagi dari orang Mesir yang lain. (Musa berkata kepadanya, \"Sesungguhnya kamu benar-benar orang sesat yang nyata.\") kesesatannya, karena apa yang telah kamu perbuat kemarin dan sekarang ini.",[["فَأَصْبَحَ","Pada waktu pagi dia"],["فِى","dalam"],["ٱلْمَدِينَةِ","bandar itu"],["خَآئِفًۭا","takut"],["يَتَرَقَّبُ","(dan) berjaga-jaga"],["فَإِذَا","apabila dilihat"],["ٱلَّذِى","Orang yang"],["ٱسْتَنصَرَهُۥ","meminta pertolongannya"],["بِٱلْأَمْسِ","hari sebelumnya"],["يَسْتَصْرِخُهُۥ ۚ","menjerit meminta pertolongan kepadanya"],["قَالَ","Berkata"],["لَهُۥ","kepadanya"],["مُوسَىٰٓ","Musa"],["إِنَّكَ","Sesungguhnya kamu"],["لَغَوِىٌّۭ","(adalah) sesungguhnya orang yang menyimpang"],["مُّبِينٌۭ","yang nyata"]]],"3271":["(Maka tatkala) huruf An di sini adalah Zaidah (Musa hendak memegang dengan keras orang yang menjadi musuh keduanya) yakni, musuh Musa dan orang Mesir yang mengejarnya (musuhnya berkata) yaitu warga Bani Israel musuh orang Mesir yang meminta tolong kepadanya itu, karena ia menduga bahwa Musa akan memukulnya (\"Hai Musa! Apakah kamu bermaksud hendak membunuhku, sebagaimana kamu kemarin telah membunuh seorang manusia? Tiadalah) yakni tidaklah (kamu bermaksud melainkan hendak menjadi orang yang berbuat sewenang-wenang di negeri ini dan tiadalah kamu hendak menjadi salah seorang dari orang-orang yang mengadakan perdamaian\"). Ketika orang yang meminta tolong kepadanya mengatakan demikian, orang Mesir yang mengerjarnya itu mendengar apa yang dikatakannya, sehingga orang Mesir itu kini mengetahui, bahwa yang membunuh orang kemarin adalah Musa sendiri. Lalu ia pergi kepada Firaun dan menceritakan hal itu kepadanya. Firaun memerintahkan kepada algojo-algojonya untuk menangkap dan membunuh Nabi Musa. Dengan segera para algojo itu berangkat mencari Musa.",[["فَلَمَّآ","Kemudian apabila"],["أَنْ","[bahawa]"],["أَرَادَ","dia mahu"],["أَن","kepada"],["يَبْطِشَ","mogok"],["بِٱلَّذِى","orang yang"],["هُوَ","[dia] (adalah)"],["عَدُوٌّۭ","seorang musuh"],["لَّهُمَا","kepada mereka berdua"],["قَالَ","dia berkata"],["يَـٰمُوسَىٰٓ","Wahai Musa"],["أَتُرِيدُ","Adakah kamu berniat"],["أَن","kepada"],["تَقْتُلَنِى","bunuh aku"],["كَمَا","seperti"],["قَتَلْتَ","kamu membunuh"],["نَفْسًۢا","seseorang"],["بِٱلْأَمْسِ ۖ","semalam"],["إِن","Tidak"],["تُرِيدُ","kamu nak"],["إِلَّآ","tetapi"],["أَن","bahawa"],["تَكُونَ","kamu menjadi"],["جَبَّارًۭا","seorang yang zalim"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَمَا","dan bukan"],["تُرِيدُ","kamu nak"],["أَن","bahawa"],["تَكُونَ","kamu jadilah"],["مِنَ","daripada"],["ٱلْمُصْلِحِينَ","golongan reformis"]]],"3272":["(Dan datanglah seorang laki-laki) dia adalah seorang yang beriman dari kalangan keluarga Firaun (dari ujung kota) dari batas kota (bergegas-gegas) berjalan cepat dengan memotong jalan (seraya berkata, \"Hai Musa! Sesungguhnya pembesar negeri) dari kalangan kaum Firaun (sedang berunding tentang kamu) maksudnya, mereka sedang bermusyawarah tentang dirimu (untuk membunuhmu, sebab itu keluarlah) dari kota ini (sesungguhnya aku termasuk orang-orang yang memberi nasihat.\") yakni, saranku ini -perintah agar kamu keluar- adalah nasihat.",[["وَجَآءَ","Dan datang"],["رَجُلٌۭ","seorang lelaki"],["مِّنْ","daripada"],["أَقْصَا","(hujung) yang paling jauh"],["ٱلْمَدِينَةِ","(dari) bandar itu"],["يَسْعَىٰ","berlari"],["قَالَ","Dia berkata"],["يَـٰمُوسَىٰٓ","Wahai Musa"],["إِنَّ","Sesungguhnya"],["ٱلْمَلَأَ","ketua-ketua"],["يَأْتَمِرُونَ","sedang mengambil nasihat"],["بِكَ","tentang kamu"],["لِيَقْتُلُوكَ","untuk membunuh kamu"],["فَٱخْرُجْ","jadi pergilah"],["إِنِّى","sesungguhnya, aku"],["لَكَ","kepada kamu"],["مِنَ","daripada"],["ٱلنَّـٰصِحِينَ","para penasihat yang ikhlas"]]],"3273":["(Maka keluarlah Musa dari kota itu dengan rasa takut menunggu-nunggu dengan khawatir) apakah dirinya akan dapat dikejar oleh orang-orang yang mencarinya atau pertolongan Allah datang menyelamatkan dirinya? (dia berdoa, \"Ya Rabbku! Selamatkanlah aku dari orang-orang yang zalim itu\") yaitu, kaum Firaun.",[["فَخَرَجَ","Jadi dia pergi"],["مِنْهَا","daripadanya"],["خَآئِفًۭا","takut"],["يَتَرَقَّبُ ۖ","(dan) berjaga-jaga"],["قَالَ","Dia berkata"],["رَبِّ","Tuhanku"],["نَجِّنِى","Selamatkan aku"],["مِنَ","daripada"],["ٱلْقَوْمِ","rakyat"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"3274":["(Dan tatkala ia menghadap) yakni menuju (ke jurusan negeri Madyan) ke arahnya. Madyan adalah nama kota tempat nabi Syuaib, yang jauhnya kira-kira delapan hari perjalanan dari kota Mesir. Kota tersebut dinamai dengan nama pendirinya yaitu Madyan ibnu Ibrahim, sedangkan Nabi Musa belum mengetahui jalan menuju ke arahnya (ia berdoa lagi, \"Mudah-mudahan Rabbku memimpinku ke jalan yang benar\") maksudnya, jalan yang menuju ke arah negeri Madyan yang tidak terlalu jauh dan juga tidak terlalu dekat, yakni pertengahan. Allah mengutus malaikat yang membawa tongkat, lalu malaikat itu memimpin Nabi Musa menuju ke negeri Madyan.",[["وَلَمَّا","Dan apabila"],["تَوَجَّهَ","dia memalingkan mukanya"],["تِلْقَآءَ","ke arah"],["مَدْيَنَ","Madyan"],["قَالَ","dia berkata"],["عَسَىٰ","barangkali"],["رَبِّىٓ","Tuhanku"],["أَن","[bahawa]"],["يَهْدِيَنِى","akan membimbing aku"],["سَوَآءَ","(kepada) bunyi"],["ٱلسَّبِيلِ","cara"]]],"3275":["(Dan tatkala ia sampai di sumber air negeri Madyan) yaitu, sebuah sumur yang ada di negeri Madyan, makna yang dimaksud ialah dia telah sampai ke negeri Madyan (ia menjumpai di tempat itu sekumpulan) sekelompok (orang-orang yang sedang memberi minum) ternaknya (dan ia menjumpai di belakang orang banyak itu) selain mereka (dua orang wanita yang sedang menahan ternaknya) maksudnya mencegah ternaknya supaya jangan merebut bagian air minum ternak orang lain. (Musa berkata) kepada kedua wanita itu, (\"Apakah gerangan yang terjadi pada kalian berdua?\") maksudnya, mengapa kalian berdua tidak meminumkan ternak kalian berdua? (Kedua wanita itu menjawab, \"Kami tidak dapat meminumkannya sebelum penggembala-penggembala itu memulangkan ternaknya). Lafal Ar Ri'a bentuk jamak dari Ra'in artinya penggembala. Maksudnya, sebelum mereka selesai dari meminumkan ternaknya, karena keduanya takut berdesak-desakan; setelah mereka bubar, baru meminumkan ternaknya. Menurut qiraat yang lain dibaca Yushdira yang berasal dari Fi'il Ruba'i yakni Ashdara, maknanya ialah, sebelum mereka membubarkan ternaknya dari sumur itu (sedangkan bapak kami adalah orang tua yang telah lanjut umurnya\") maksudnya, tidak mampu lagi untuk meminumkan ternaknya.",[["وَلَمَّا","Dan apabila"],["وَرَدَ","dia datang"],["مَآءَ","(kepada) air"],["مَدْيَنَ","(dari) Madyan"],["وَجَدَ","dia jumpa"],["عَلَيْهِ","di atasnya"],["أُمَّةًۭ","satu kumpulan"],["مِّنَ","daripada"],["ٱلنَّاسِ","lelaki"],["يَسْقُونَ","menyiram"],["وَوَجَدَ","dan dia mendapati"],["مِن","selain mereka"],["دُونِهِمُ","selain mereka"],["ٱمْرَأَتَيْنِ","dua orang perempuan"],["تَذُودَانِ ۖ","menyimpan kembali"],["قَالَ","Dia berkata"],["مَا","Apa"],["خَطْبُكُمَا ۖ","(adalah) urusan kamu berdua"],["قَالَتَا","Mereka berkata"],["لَا","Kami tidak boleh menyiram"],["نَسْقِى","Kami tidak boleh menyiram"],["حَتَّىٰ","sehingga"],["يُصْدِرَ","bawa pergi"],["ٱلرِّعَآءُ ۖ","para gembala"],["وَأَبُونَا","dan bapa kita"],["شَيْخٌۭ","(adalah) seorang lelaki yang sangat tua"],["كَبِيرٌۭ","(adalah) seorang lelaki yang sangat tua"]]],"3276":["(Maka Musa memberi minum ternak itu untuk menolong keduanya) dari air sumur lain yang berada di dekat sumur itu, kemudian Nabi Musa mengangkat batu besar yang menutupinya, konon batu itu hanya dapat diangkat oleh sepuluh orang yang kuat (kemudian ia kembali) setelah itu Musa kembali lagi (ke tempat yang teduh) di bawah pohon Samurah, karena pada saat itu hari sangat panas dan ia dalam keadaan lapar (lalu berdoa, \"Ya Rabbku! Sesungguhnya aku terhadap kebaikan yang Engkau turunkan kepadaku) yang dimaksud adalah makanan (sangat memerlukan.\") sangat membutuhkannya. Lalu kedua wanita itu kembali ke rumah bapak mereka, kejadian ini membuat bapaknya terkejut, karena mereka berdua kembali lebih cepat dari biasanya. Maka bapaknya menanyakan tentang hal tersebut. Lalu diceritakan kepadanya tentang seorang lelaki yang telah menolongnya memberi minum ternaknya. Bapak mereka bertanya kepada salah seorang dari keduanya, \"Coba panggillah dia untuk menghadap kepadaku\". Lalu Allah berfirman,",[["فَسَقَىٰ","Jadi dia menyiram"],["لَهُمَا","bagi mereka"],["ثُمَّ","Kemudian"],["تَوَلَّىٰٓ","dia berpatah balik"],["إِلَى","kepada"],["ٱلظِّلِّ","teduh"],["فَقَالَ","dan berkata"],["رَبِّ","Tuhanku"],["إِنِّى","Memang aku"],["لِمَآ","daripada apa sahaja"],["أَنزَلْتَ","kamu hantar"],["إِلَىَّ","kepada aku"],["مِنْ","daripada"],["خَيْرٍۢ","kebaikan"],["فَقِيرٌۭ","(dalam) memerlukan"]]],"3277":["(Kemudian datanglah kepada Musa salah seorang dari kedua wanita itu berjalan kemalu-maluan) seraya menutupkan kain kerudung ke mukanya karena malu kepada Nabi Musa (ia berkata, \"Sesungguhnya bapakku memanggil kamu agar ia memberikan balasan terhadap kebaikanmu memberi minum ternak kami\") Nabi Musa memenuhi panggilannya dan menolak dalam hatinya upah yang akan diberikan kepadanya, karena seolah-olah wanita itu bermaksud hendak memberi upah dan menganggap dirinya sebagai seorang upahan. Kemudian wanita itu berjalan di muka Nabi Musa tiba-tiba angin meniup kainnya, sehingga terlihat kedua betisnya. Lalu Nabi Musa berkata kepadanya, \"Berjalanlah engkau di belakangku dan tunjukkanlah jalan itu kepadaku\". Wanita itu menuruti apa yang dikatakan oleh Nabi Musa, sehingga Nabi Musa sampai ke tempat bapak wanita itu, dia adalah Nabi Syuaib a.s. Ketika Nabi Musa sampai di hadapannya ternyata telah disiapkan makan malam, maka Nabi Syuaib berkata, \"Duduklah, kemudian makan malamlah\". Nabi Musa menjawab, \"Aku khawatir jika makan malam ini sebagai imbalan karena aku telah memberi minum ternak keduanya, sedangkan aku berasal dari ahlul bait yang tidak pernah meminta imbalan dari suatu pekerjaan yang baik\". Nabi Syuaib berkata, \"Tidak, ini merupakan tradisiku dan tradisi nenek moyangku. Kami biasa menjamu tamu kami, juga biasa memberi makan\". Nabi Musa baru mau memakannya dan menceritakan kepadanya semua apa yang telah ia alami. Untuk itu maka Allah swt. berfirman, (\"Maka tatkala Musa mendatangi bapak wanita itu dan menceritakan kepadanya kisah mengenai dirinya) lafal Al Qashash adalah Mashdar yang bermakna Isim Maf'ul; maksudnya Nabi Musa menceritakan kepadanya tentang pembunuhannya terhadap seorang bangsa Mesir dan niat bangsa Mesir untuk membunuhnya, serta kekhawatirannya terhadap Firaun (Syuaib berkata, 'Janganlah kamu takut! Kamu telah selamat dari orang-orang yang zalim'.\") karena tidak ada kekuasaan bagi Firaun atas negeri Madyan.",[["فَجَآءَتْهُ","Kemudian datang kepadanya"],["إِحْدَىٰهُمَا","salah seorang daripada dua wanita itu"],["تَمْشِى","berjalan"],["عَلَى","dengan"],["ٱسْتِحْيَآءٍۢ","rasa malu"],["قَالَتْ","Dia berkata"],["إِنَّ","Sesungguhnya"],["أَبِى","ayah aku"],["يَدْعُوكَ","memanggil kamu"],["لِيَجْزِيَكَ","supaya dia memberi ganjaran kepada kamu"],["أَجْرَ","(i) ganjaran"],["مَا","(untuk) apa"],["سَقَيْتَ","kamu menyiram"],["لَنَا ۚ","bagi kami"],["فَلَمَّا","Maka apabila"],["جَآءَهُۥ","dia datang kepadanya"],["وَقَصَّ","dan diriwayatkan"],["عَلَيْهِ","kepadanya"],["ٱلْقَصَصَ","cerita itu"],["قَالَ","dia berkata"],["لَا","Jangan"],["تَخَفْ ۖ","bertakwa"],["نَجَوْتَ","Kamu telah melarikan diri"],["مِنَ","daripada"],["ٱلْقَوْمِ","rakyat"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"3278":["(Salah seorang dari kedua wanita itu berkata) yakni wanita yang disuruh menjemput Nabi Musa yaitu yang paling besar atau yang paling kecil (\"Ya bapakku! Ambillah dia sebagai orang yang bekerja pada kita) sebagai pekerja kita, khusus untuk menggembalakan kambing milik kita, sebagai ganti kami (karena sesungguhnya orang yang paling baik yang kamu ambil untuk bekerja pada kita ialah orang yang kuat lagi dapat dipercaya\") maksudnya, jadikanlah ia pekerja padanya, karena dia adalah orang yang kuat lagi dapat dipercaya. Lalu Nabi Syuaib bertanya kepada anaknya tentang Nabi Musa. Wanita itu menceritakan kepada bapaknya semua apa yang telah dilakukan oleh Nabi Musa, mulai dari mengangkat bata penutup sumur, juga tentang perkataannya, \"Berjalanlah di belakangku\". Setelah Nabi Syuaib mengetahui melalui cerita putrinya bahwa ketika putrinya datang menjemput Nabi Musa, Nabi Musa menundukkan pandangan matanya, hal ini merupakan pertanda bahwa Nabi Musa jatuh cinta kepada putrinya, maka Nabi Syuaib bermaksud mengawinkan keduanya.",[["قَالَتْ","Berkata"],["إِحْدَىٰهُمَا","salah seorang daripada mereka"],["يَـٰٓأَبَتِ","Wahai ayahku"],["ٱسْتَـْٔجِرْهُ ۖ","Upah dia"],["إِنَّ","Sesungguhnya"],["خَيْرَ","(yang) terbaik"],["مَنِ","yang"],["ٱسْتَـْٔجَرْتَ","kamu (boleh) mengupah"],["ٱلْقَوِىُّ","(ialah) yang kuat"],["ٱلْأَمِينُ","yang boleh dipercayai"]]],"3279":["(Berkatalah dia, \"Sesungguhnya aku bermaksud menikahkan kamu dengan salah seorang dari kedua anakku ini) yaitu yang paling besar atau yang paling kecil (atas dasar kamu bekerja denganku) yakni, menggembalakan kambingku (delapan tahun) selama delapan tahun (dan jika kamu cukupkan sepuluh tahun) yakni, menggembalakan kambingku selama sepuluh tahun (maka itu adalah suatu kebaikan dari kamu) kegenapan itu (maka aku tidak hendak memberati kamu) dengan mensyaratkan sepuluh tahun. (Dan kamu Insya Allah akan mendapatiku) lafal Insya Allah di sini maksudnya untuk ber-tabarruk (termasuk orang-orang yang baik\") yaitu orang-orang yang menepati janjinya.",[["قَالَ","Dia berkata"],["إِنِّىٓ","Sesungguhnya aku"],["أُرِيدُ","[Aku] ingin"],["أَنْ","kepada"],["أُنكِحَكَ","kahwin dengan kamu"],["إِحْدَى","satu"],["ٱبْنَتَىَّ","(daripada) anak-anak perempuan aku"],["هَـٰتَيْنِ","(dari) dua ini"],["عَلَىٰٓ","pada"],["أَن","bahawa"],["تَأْجُرَنِى","kamu layan aku"],["ثَمَـٰنِىَ","(untuk) lapan"],["حِجَجٍۢ ۖ","tahun"],["فَإِنْ","tetapi jika"],["أَتْمَمْتَ","kamu lengkapkan"],["عَشْرًۭا","sepuluh"],["فَمِنْ","kemudian dari"],["عِندِكَ ۖ","kamu"],["وَمَآ","Dan tidak"],["أُرِيدُ","aku harap"],["أَنْ","kepada"],["أَشُقَّ","menyusahkan"],["عَلَيْكَ ۚ","bagi kamu"],["سَتَجِدُنِىٓ","kamu akan jumpa aku"],["إِن","jika"],["شَآءَ","Allah berkehendak"],["ٱللَّهُ","Allah berkehendak"],["مِنَ","daripada"],["ٱلصَّـٰلِحِينَ","orang yang soleh"]]],"3280":["Musa (Berkata, \"Itulah) yakni perjanjian yang telah kamu katakan itu (antara aku dan kamu. Mana saja dari kedua waktu yang ditentukan itu) delapan atau sepuluh tahun masa penggembalaan itu; huruf Ma pada lafal Ayyama adalah huruf Zaidah (aku sempurnakan) aku selesaikan (maka tidak ada tuntutan atas diriku) artinya tuntutan tambahan waktu lain. (Dan Allah atas apa yang kita ucapkan) tentang apa yang diucapkan oleh aku dan kamu (adalah sebagai saksi.\") pemelihara atau saksi. Maka perjanjian itu dinyatakan oleh keduanya, dan Nabi Syuaib memerintahkan anak perempuannya supaya memberikan tongkatnya kepada Nabi Musa untuk mengusir binatang-binatang buas dari ternak yang digembalakannya nanti. Tongkat itu adalah milik para nabi secara turun-temurun sejak Nabi Adam dan kini berada di tangan Nabi Syuaib. Tongkat itu berasal dari kayu surga, tongkat itu beralih ke tangan nabi Musa dengan sepengetahuan Nabi Syuaib.",[["قَالَ","Dia berkata"],["ذَٰلِكَ","Itu"],["بَيْنِى","(adalah) antara aku"],["وَبَيْنَكَ ۖ","dan antara kamu"],["أَيَّمَا","yang mana"],["ٱلْأَجَلَيْنِ","(daripada) dua istilah"],["قَضَيْتُ","aku lengkapkan"],["فَلَا","maka tidak"],["عُدْوَٰنَ","ketidakadilan"],["عَلَىَّ ۖ","kepada aku"],["وَٱللَّهُ","dan Allah"],["عَلَىٰ","atas"],["مَا","apa"],["نَقُولُ","kita cakap"],["وَكِيلٌۭ","(adalah) seorang Saksi"]]],"3281":["(Maka tatkala Musa telah menyelesaikan waktu yang ditentukan) yakni masa penggembalaan itu, yaitu delapan atau sepuluh tahun. Masa sepuluh tahun inilah yang diduga kuat dilakukan oleh Nabi Musa (dan dia berangkat dengan keluarganya) dengan istrinya menuju ke negeri Mesir dengan seizin bapaknya (dilihatnyalah) yakni, Nabi Musa melihat dari jarak jauh (dari arah lereng gunung Thur) Thur adalah nama sebuah gunung (api, Ia berkata kepada keluarganya, \"Tunggulah) di sini (sesungguhnya aku melihat api, mudah-mudahan aku dapat membawa suatu berita kepadamu dari tempat api itu) tentang jalan yang sebenarnya, karena pada saat itu Nabi Musa tersesat (atau membawa sesuluh) dapat dibaca Jadzwatin, Judzwatin, dan Jidzwatin, yakni sebuah obor (api agar kamu dapat menghangatkan badan\") maksudnya, berdiang dengan api itu. Huruf Tha yang ada pada lafal Tashthaluna merupakan pergantian dari huruf Ta wazan Ifti'al, karena berasal dari kata Shala bin nari atau Shaliya bin nari artinya berdiang dekat api untuk menghangatkan badan.",[["۞ فَلَمَّا","Kemudian apabila"],["قَضَىٰ","Musa menunaikannya"],["مُوسَى","Musa menunaikannya"],["ٱلْأَجَلَ","istilah tersebut"],["وَسَارَ","dan sedang dalam perjalanan"],["بِأَهْلِهِۦٓ","bersama keluarganya"],["ءَانَسَ","dia nampak"],["مِن","dalam"],["جَانِبِ","(tujuan)."],["ٱلطُّورِ","(dari) Gunung Tur"],["نَارًۭا","api"],["قَالَ","Dia berkata"],["لِأَهْلِهِ","kepada keluarganya"],["ٱمْكُثُوٓا۟","Tinggal di sini"],["إِنِّىٓ","sesungguhnya, aku"],["ءَانَسْتُ","[Aku] merasakan"],["نَارًۭا","api"],["لَّعَلِّىٓ","barangkali"],["ءَاتِيكُم","Aku akan bawa kamu"],["مِّنْهَا","dari situ"],["بِخَبَرٍ","beberapa maklumat"],["أَوْ","atau"],["جَذْوَةٍۢ","kayu yang terbakar"],["مِّنَ","daripada"],["ٱلنَّارِ","api"],["لَعَلَّكُمْ","supaya kamu"],["تَصْطَلُونَ","panaskan diri"]]],"3282":["(Maka tatkala Musa sampai ke tempat api itu, dia diseru dari arah pinggir) yakni sebelah (lembah yang kanan) yang berada di sebelah kanan Nabi Musa (pada tempat yang diberkahi) bagi Musa untuk mendengarkan Kalam Allah di tempat itu (dari sebatang pohon) lafal ayat ini menjadi Badal dari lafal Syathi' berikut pengulangan huruf Jar-nya, disebabkan pohon itu tumbuh di pinggir lembah; pohon itu adalah pohon anggur, atau pohon 'Ulaiq, atau pohon 'Ausaj (yaitu) huruf An adalah An Mufassarah bukan An Mukhaffafah (\"Hai Musa! Sesungguhnya Aku adalah Allah, Rabb semesta alam).",[["فَلَمَّآ","Tetapi apabila"],["أَتَىٰهَا","dia datang kepadanya"],["نُودِىَ","dia dipanggil"],["مِن","daripada"],["شَـٰطِئِ","(sisi)."],["ٱلْوَادِ","(dari) lembah"],["ٱلْأَيْمَنِ","yang betul"],["فِى","dalam"],["ٱلْبُقْعَةِ","tempat itu pun"],["ٱلْمُبَـٰرَكَةِ","diberkati"],["مِنَ","daripada"],["ٱلشَّجَرَةِ","pokok itu"],["أَن","bahawa"],["يَـٰمُوسَىٰٓ","Wahai Musa"],["إِنِّىٓ","Sesungguhnya"],["أَنَا","Aku"],["ٱللَّهُ","Allah"],["رَبُّ","(yang) Tuhan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"3283":["(Dan lemparkanlah tongkatmu!\") lalu Musa melemparkannya. (Tatkala Musa melihatnya bergerak-gerak) menjadi bergerak (seolah-olah dia seekor ular yang gesit) gerakannya sekalipun besar tubuhnya, dikatakan Jan artinya ular kecil padahal ular itu besar sekali, maksudnya gerakannya diserupakan dengan ular yang kecil dalam hal kegesitannya (larilah ia berbalik ke belakang) melarikan diri daripadanya (tanpa menoleh) tanpa menengok ke belakang lagi, lalu diserulah ia (\"Hai Musa! Datanglah kepada-Ku dan janganlah kamu takut. Sesungguhnya kamu termasuk orang-orang yang aman!).",[["وَأَنْ","Dan [itu]"],["أَلْقِ","melontar"],["عَصَاكَ ۖ","kakitangan kamu"],["فَلَمَّا","Tetapi apabila"],["رَءَاهَا","dia melihatnya"],["تَهْتَزُّ","bergerak"],["كَأَنَّهَا","seolah-olah ia"],["جَآنٌّۭ","(adalah) seekor ular"],["وَلَّىٰ","dia berpaling"],["مُدْبِرًۭا","(dalam) penerbangan"],["وَلَمْ","dan (tidak) tidak"],["يُعَقِّبْ ۚ","kembali"],["يَـٰمُوسَىٰٓ","Wahai Musa"],["أَقْبِلْ","Dekatkan diri"],["وَلَا","dan jangan"],["تَخَفْ ۖ","bertakwa"],["إِنَّكَ","Sesungguhnya kamu"],["مِنَ","(adalah) daripada"],["ٱلْـَٔامِنِينَ","yang selamat"]]],"3284":["(Masukkanlah) sisipkanlah (tanganmu) yang sebelah kanan, yang dimaksud adalah telapak tangannya (ke leher bajumu) maksudnya, kerah baju gamismu, kemudian keluarkanlah kembali (niscaya ia keluar) berbeda keadaannya dengan tangan yang biasanya (putih tidak bercela) maksudnya bukan karena penyakit sopak. Nabi Musa memasukkan tangannya itu sesuai dengan perintah, kemudian ia mengeluarkannya kembali, tiba-tiba tampak bagaikan cahaya matahari yang menyilaukan pandangan mata (dan dekapkanlah tanganmu itu ke dadamu bila ketakutan) dapat dibaca Ar Rahbi dan Ar Rahbu yang artinya takut disebabkan sinar tangan tadi. Maksudnya jika kamu merasa takut maka masukkan kembali tanganmu itu ke dalam bajumu, niscaya kembali kepada keadaan semula. Pengertian tangan diungkapkan dengan istilah Janah yang artinya sayap, karena kedua tangan bagi manusia fungsinya sama dengan dua sayap bagi burung (maka yang demikian itu adalah dua) dapat dibaca Tasydid dan Takhfif, yakni Fadzanika dan Fadzannika, yang dimaksud adalah tongkat dan tangan itu; keduanya merupakan lafal Muannats dan Musyar ilaih dalam bentuk mudzakar karena khabarnya mudzakar (mukjizat) yang diturunkan (dari Rabbmu yang akan kamu hadapkan kepada Firaun dan pembesar-pembesar kaumnya. Sesungguhnya mereka adalah orang-orang yang fasik\").",[["ٱسْلُكْ","Sisipkan"],["يَدَكَ","tangan kamu"],["فِى","dalam"],["جَيْبِكَ","dada kamu"],["تَخْرُجْ","ia akan keluar"],["بَيْضَآءَ","putih"],["مِنْ","tanpa"],["غَيْرِ","tanpa"],["سُوٓءٍۢ","sebarang kemudaratan"],["وَٱضْمُمْ","Dan lukis"],["إِلَيْكَ","kepada diri kamu sendiri"],["جَنَاحَكَ","tangan kamu"],["مِنَ","terhadap"],["ٱلرَّهْبِ ۖ","bertakwa"],["فَذَٰنِكَ","Jadi ini"],["بُرْهَـٰنَانِ","(adalah) dua bukti"],["مِن","daripada"],["رَّبِّكَ","Tuhanmu"],["إِلَىٰ","kepada"],["فِرْعَوْنَ","Firaun"],["وَمَلَإِي۟هِۦٓ ۚ","dan ketua-ketuanya"],["إِنَّهُمْ","Sesungguhnya mereka"],["كَانُوا۟","adalah"],["قَوْمًۭا","suatu kaum"],["فَـٰسِقِينَ","membangkang menderhaka"]]],"3285":["(Musa berkata, \"Ya Rabbku! Sesungguhnya aku, telah membunuh seorang manusia dari golongan mereka) yaitu, orang Mesir yang telah dibunuhnya tadi (maka aku takut mereka akan membunuhku) disebabkan perbuatan itu.",[["قَالَ","Dia berkata"],["رَبِّ","Tuhanku"],["إِنِّى","Sesungguhnya"],["قَتَلْتُ","Aku membunuh"],["مِنْهُمْ","daripada mereka"],["نَفْسًۭا","seorang lelaki"],["فَأَخَافُ","dan aku takut"],["أَن","bahawa"],["يَقْتُلُونِ","mereka akan membunuh aku"]]],"3286":["(Dan saudaraku Harun dia lebih fasih lidahnya daripadaku) maksudnya jelas bicaranya (maka utuslah dia bersamaku sebagai pembantuku) yang kelak akan membantuku. Lafal Rid-an menurut qiraat yang lain dibaca Riddan (untuk membenarkan aku) lafal Yushaddiqni yang dibaca Jazm adalah menjadi Jawab dari Ad Du'a. Tetapi menurut qiraat yang lain dibaca Rafa, sehingga bacaannya menjadi Yushaddiquni sebagai sifat dari lafal Rid-an (sesungguhnya aku khawatir mereka akan mendustakan aku\").",[["وَأَخِى","Dan abang aku"],["هَـٰرُونُ","Harun"],["هُوَ","dia"],["أَفْصَحُ","(adalah) lebih fasih"],["مِنِّى","daripada aku"],["لِسَانًۭا","(dalam) ucapan"],["فَأَرْسِلْهُ","jadi hantar dia"],["مَعِىَ","dengan aku"],["رِدْءًۭا","(sebagai) penolong"],["يُصَدِّقُنِىٓ ۖ","siapa yang akan mengesahkan aku"],["إِنِّىٓ","Sesungguhnya"],["أَخَافُ","aku takut"],["أَن","bahawa"],["يُكَذِّبُونِ","mereka akan menafikan aku"]]],"3287":["(Allah berfirman, \"Kami akan membantumu) memperkuatmu (dengan saudaramu, dan Kami berikan kepadamu berdua kekuasaan yang besar) berupa kemenangan yang besar (maka mereka tidak dapat mencapai kamu berdua) dengan maksud jahat mereka, maka pergilah kamu berdua (dengan membawa mukjizat Kami, kamu berdua dan orang yang mengikuti kamulah yang akan menang\") atas mereka.",[["قَالَ","Dia berkata"],["سَنَشُدُّ","Kami akan menguatkan"],["عَضُدَكَ","lengan kamu"],["بِأَخِيكَ","melalui abang kamu"],["وَنَجْعَلُ","dan Kami akan jadikan"],["لَكُمَا","untuk kamu berdua"],["سُلْطَـٰنًۭا","sebuah pihak berkuasa"],["فَلَا","jadi tidak"],["يَصِلُونَ","mereka akan sampai"],["إِلَيْكُمَا ۚ","kepada kamu berdua"],["بِـَٔايَـٰتِنَآ","Melalui Tanda-tanda Kami"],["أَنتُمَا","kamu berdua"],["وَمَنِ","dan (mereka) yang"],["ٱتَّبَعَكُمَا","ikut kamu"],["ٱلْغَـٰلِبُونَ","(akan) menjadi yang dominan"]]],"3288":["(Maka tatkala Musa datang kepada mereka dengan membawa mukjizat-mukjizat Kami yang nyata) yakni nyata keadaannya (mereka berkata, \"Ini tidak lain hanyalah sihir yang dibuat-buat) yakni sulapan ilmu sihir saja (dan kami belum pernah mendengar Seruan ini) yang telah ada (di) masa-masa (nenek moyang kami dahulu\").",[["فَلَمَّا","Tetapi apabila"],["جَآءَهُم","datang kepada mereka"],["مُّوسَىٰ","Musa"],["بِـَٔايَـٰتِنَا","dengan Tanda-tanda Kami"],["بَيِّنَـٰتٍۢ","yang nyata"],["قَالُوا۟","mereka berkata"],["مَا","Tidak"],["هَـٰذَآ","(adalah) ini"],["إِلَّا","kecuali"],["سِحْرٌۭ","sihir"],["مُّفْتَرًۭى","dicipta"],["وَمَا","dan bukan"],["سَمِعْنَا","kami dengar"],["بِهَـٰذَا","ini"],["فِىٓ","antara"],["ءَابَآئِنَا","nenek moyang kita"],["ٱلْأَوَّلِينَ","nenek moyang kita"]]],"3289":["(Berkatalah) dapat dibaca waqala dan Qala tanpa memakai Wawu (Musa, \"Rabbku lebih mengetahui) (orang yang patut membawa petunjuk dari sisi-Nya) Dhamir yang ada pada lafal 'Indahu kembali kepada Ar Rabb (dan siapa) di'athafkan kepada lafal Man sebelumnya (yang akan ada) dapat dibaca Takunu dan Yakunu (baginya kesudahan yang baik di negeri akhirat) yakni akibat yang terpuji di akhirat; maksudnya dia adalah aku sendiri, keduanya adalah aku sendiri yang berhak menyandangnya dan aku orang yang benar di dalam menyampaikan apa yang diturunkan kepadaku. (Sesungguhnya tidaklah akan mendapat kemenangan orang-orang yang zalim\") yakni orang-orang yang kafir.",[["وَقَالَ","Dan Musa berkata"],["مُوسَىٰ","Dan Musa berkata"],["رَبِّىٓ","Tuhanku"],["أَعْلَمُ","lebih tahu"],["بِمَن","daripada siapa"],["جَآءَ","telah datang"],["بِٱلْهُدَىٰ","dengan bimbingan"],["مِنْ","daripadaNya"],["عِندِهِۦ","daripadaNya"],["وَمَن","dan siapa"],["تَكُونُ","akan menjadi"],["لَهُۥ","baginya"],["عَـٰقِبَةُ","kesudahan yang baik di akhirat"],["ٱلدَّارِ ۖ","kesudahan yang baik di akhirat"],["إِنَّهُۥ","Sesungguhnya"],["لَا","tidak"],["يُفْلِحُ","akan berjaya"],["ٱلظَّـٰلِمُونَ","orang yang zalim"]]],"3290":["(Dan berkata Firaun, \"Hai pembesar kaumku! Aku tidak mengetahui tuhan bagi kalian selain aku sendiri. Maka bakarlah hai Haman, untukku tanah liat) maksudnya buatlah batu bata untukku (kemudian buatkanlah untukku bangunan yang tinggi) maksudnya gedung yang tinggi sekali (supaya aku dapat naik melihat Tuhan Musa) aku akan melihat-Nya dan berdiri di hadapan-Nya (dan sesungguhnya aku benar-benar yakin bahwa dia termasuk orang-orang yang pendusta\") di dalam pengakuannya yang mengatakan ada Tuhan lain selain aku, bahwa ia seorang Rasul.",[["وَقَالَ","Dan Firaun berkata"],["فِرْعَوْنُ","Dan Firaun berkata"],["يَـٰٓأَيُّهَا","Wahai ketua-ketua"],["ٱلْمَلَأُ","Wahai ketua-ketua"],["مَا","Tidak"],["عَلِمْتُ","aku tahu"],["لَكُم","bagi kamu"],["مِّنْ","sebarang"],["إِلَـٰهٍ","tuhan"],["غَيْرِى","selain aku"],["فَأَوْقِدْ","Jadi menyalakan"],["لِى","untuk aku"],["يَـٰهَـٰمَـٰنُ","Wahai Haman"],["عَلَى","selepas"],["ٱلطِّينِ","tanah liat"],["فَٱجْعَل","dan buat"],["لِّى","untuk aku"],["صَرْحًۭا","sebuah menara yang tinggi"],["لَّعَلِّىٓ","supaya [aku]"],["أَطَّلِعُ","Aku mungkin melihat"],["إِلَىٰٓ","di"],["إِلَـٰهِ","(yang) Tuhan"],["مُوسَىٰ","(dari) Musa"],["وَإِنِّى","Dan sesungguhnya, aku"],["لَأَظُنُّهُۥ","[Aku] fikir dia"],["مِنَ","(adalah) daripada"],["ٱلْكَـٰذِبِينَ","pendusta"]]],"3291":["(Dan berlaku angkuhlah Firaun dan bala tentaranya di bumi Mesir) di negeri Mesir (tanpa alasan yang benar dan mereka menyangka bahwa mereka tidak akan dikembalikan kepada Kami) dapat dibaca La Yurja'una dan La Yarji'una.",[["وَٱسْتَكْبَرَ","Dan dia sombong"],["هُوَ","Dan dia sombong"],["وَجُنُودُهُۥ","dan tuan rumahnya"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["بِغَيْرِ","tanpa"],["ٱلْحَقِّ","betul"],["وَظَنُّوٓا۟","dan mereka berfikir"],["أَنَّهُمْ","bahawa mereka"],["إِلَيْنَا","kepada Kami"],["لَا","tidak"],["يُرْجَعُونَ","akan dikembalikan"]]],"3292":["(Maka Kami hukum Firaun dan bala tentaranya, lalu Kami lemparkan mereka) Kami campakkan mereka (ke dalam laut) yang asin airnya, sehingga tenggelamlah mereka. (Maka lihatlah bagaimana akibat orang-orang yang zalim) sewaktu mereka menjadi binasa.",[["فَأَخَذْنَـٰهُ","Maka Kami siksa dia"],["وَجُنُودَهُۥ","dan tuan rumahnya"],["فَنَبَذْنَـٰهُمْ","dan Kami melemparkan mereka"],["فِى","dalam"],["ٱلْيَمِّ ۖ","laut"],["فَٱنظُرْ","Jadi lihat"],["كَيْفَ","bagaimana"],["كَانَ","adalah"],["عَـٰقِبَةُ","(akhirnya)."],["ٱلظَّـٰلِمِينَ","(dari) orang-orang yang zalim"]]],"3293":["(Dan Kami jadikan mereka) di dunia (pemimpin-pemimpin) A-immatan dapat dibaca Tahqiq dan Tas-hil, yakni pemimpin-pemimpin dalam kemusyrikan (yang menyeru ke neraka) disebabkan seruan mereka yang mengajak kepada kemusyrikan (dan pada hari kiamat mereka tidak akan ditolong) yaitu azab mereka tidak dapat ditolak lagi.",[["وَجَعَلْنَـٰهُمْ","Dan Kami jadikan mereka"],["أَئِمَّةًۭ","pemimpin"],["يَدْعُونَ","mengundang"],["إِلَى","kepada"],["ٱلنَّارِ ۖ","neraka"],["وَيَوْمَ","dan (pada) Hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["لَا","tidak"],["يُنصَرُونَ","mereka akan dibantu"]]],"3294":["(Dan Kami sertakan laknat kepada mereka di dunia ini) berupa kehinaan (dan pada hari kiamat mereka termasuk orang-orang yang dijauhkan) dari rahmat-Nya.",[["وَأَتْبَعْنَـٰهُمْ","Dan Kami mengikuti mereka"],["فِى","dalam"],["هَـٰذِهِ","ini"],["ٱلدُّنْيَا","dunia"],["لَعْنَةًۭ ۖ","sumpahan"],["وَيَوْمَ","dan (pada) Hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["هُم","mereka"],["مِّنَ","(akan) daripada"],["ٱلْمَقْبُوحِينَ","yang hina"]]],"3295":["(Dan sesungguhnya telah Kami berikan kepada Musa Alkitab) yaitu Taurat (sesudah Kami binasakan generasi-generasi yang terdahulu) yakni kaum Nabi Nuh, kaum 'Ad, kaum Tsamud dan lain-lainnya (untuk menjadi pelita bagi manusia) kedudukan lafal ayat ini menjadi Hal dari lafal Alkitab; itu adalah bentuk jamak dari lafal Bashirah yang artinya cahaya hati, maksudnya pelita hati bagi manusia (dan petunjuk) dari kesesatan bagi orang yang mengamalkannya (dan rahmat) bagi orang yang beriman kepadanya (agar mereka ingat) dapat mengambil pelajaran dari nasihat-nasihat yang terkandung di dalamnya.",[["وَلَقَدْ","Dan sesungguhnya"],["ءَاتَيْنَا","Kami memberi"],["مُوسَى","Musa"],["ٱلْكِتَـٰبَ","Kitab Suci"],["مِنۢ","selepas [apa]"],["بَعْدِ","selepas [apa]"],["مَآ","selepas [apa]"],["أَهْلَكْنَا","Kami telah memusnahkan"],["ٱلْقُرُونَ","generasi"],["ٱلْأُولَىٰ","bekas"],["بَصَآئِرَ","(sebagai) pencerahan"],["لِلنَّاسِ","untuk umat manusia"],["وَهُدًۭى","dan hidayah"],["وَرَحْمَةًۭ","dan belas kasihan"],["لَّعَلَّهُمْ","supaya mereka boleh"],["يَتَذَكَّرُونَ","ingat"]]],"3296":["(Dan tidaklah kamu) hai Muhammad (berada di sisi) bukit, atau lembah atau suatu tempat (yang sebelah barat) dari Musa ketika ia bermunajat (ketika Kami menyampaikan) mewahyukan (perintah ke pada Musa) supaya menyampaikannya kepada Firaun dan kaumnya (dan tiada pula kamu termasuk orang-orang yang menyaksikan) kejadian tersebut, lalu kamu mengetahuinya dan menceritakan tentangnya.",[["وَمَا","Dan tidak"],["كُنتَ","kamu dahulu"],["بِجَانِبِ","di (sisi)."],["ٱلْغَرْبِىِّ","barat"],["إِذْ","apabila"],["قَضَيْنَآ","Kami memutuskan"],["إِلَىٰ","kepada"],["مُوسَى","Musa"],["ٱلْأَمْرَ","Perintah itu"],["وَمَا","dan bukan"],["كُنتَ","kamu dahulu"],["مِنَ","antara"],["ٱلشَّـٰهِدِينَ","para saksi"]]],"3297":["(Tetapi Kami telah mengadakan beberapa generasi) yakni umat-umat sesudah Nabi Musa (dan berlalulah atas mereka masa yang panjang) waktu yang berabad-abad sehingga mereka lupa akan perjanjian-perjanjian, dan ilmu-ilmu agama pun telah terhapus pula, serta wahyu terputus. Maka Kami datangkan kamu sebagai seorang Rasul dan Kami turunkan wahyu kepadamu mengenai berita Musa dan berita nabi-nabi lainnya (dan tiadalah kamu tinggal) bermukim (bersama-sama penduduk Madyan dengan membacakan ayat-ayat Kami kepada mereka) lafal Tatlu dan seterusnya merupakan Khabar yang kedua dari lafal Kunta, maksudnya, sehingga penduduk Madyan itu mengetahui kisah umat-umat terdahulu lalu mereka mengisahkannya (tetapi Kami telah mengangkat menjadi Rasul) kamu, dan Kami mengutus utusan-utusan Kami kepadamu dengan membawa berita orang-orang dahulu.",[["وَلَـٰكِنَّآ","Tetapi Kami"],["أَنشَأْنَا","[Kami] menghasilkan"],["قُرُونًۭا","generasi"],["فَتَطَاوَلَ","dan berpanjangan"],["عَلَيْهِمُ","bagi mereka"],["ٱلْعُمُرُ ۚ","kehidupan"],["وَمَا","Dan tidak"],["كُنتَ","kamu dahulu"],["ثَاوِيًۭا","seorang penghuni"],["فِىٓ","antara"],["أَهْلِ","kaum"],["مَدْيَنَ","(dari) Madyan"],["تَتْلُوا۟","mengaji"],["عَلَيْهِمْ","kepada mereka"],["ءَايَـٰتِنَا","Ayat Kami"],["وَلَـٰكِنَّا","tetapi Kami"],["كُنَّا","[Kami] dulu"],["مُرْسِلِينَ","para Penghantar"]]],"3298":["(Dan tiadalah kamu berada di dekat bukit Thur) nama sebuah bukit (ketika) sewaktu (Kami menyeru) Musa, \"Ambillah Alkitab ini dengan sepenuh kekuatanmu\", yakni amalkanlah sekemampuanmu (tetapi) Kami utus kamu (sebagai rahmat dari Rabbmu, supaya kamu memberi peringatan kepada kaum yang sekali-kali belum datang kepada mereka pemberi peringatan sebelum kamu supaya mereka ingat) supaya mengambil pelajaran.",[["وَمَا","Dan tidak"],["كُنتَ","kamu dahulu"],["بِجَانِبِ","di (sisi)."],["ٱلطُّورِ","(dari) Tur"],["إِذْ","apabila"],["نَادَيْنَا","Kami telefon"],["وَلَـٰكِن","Tetapi"],["رَّحْمَةًۭ","(sebagai) rahmat"],["مِّن","daripada"],["رَّبِّكَ","Tuhanmu"],["لِتُنذِرَ","supaya kamu memberi amaran"],["قَوْمًۭا","suatu kaum"],["مَّآ","tidak"],["أَتَىٰهُم","(telah) datang kepada mereka"],["مِّن","sebarang"],["نَّذِيرٍۢ","pemberi amaran"],["مِّن","sebelum kamu"],["قَبْلِكَ","sebelum kamu"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَتَذَكَّرُونَ","ingat"]]],"3299":["(Dan agar mereka sewaktu ditimpa musibah) azab (disebabkan apa yang telah di kerjakan oleh tangan-tangan mereka) berupa kekafiran dan selainnya (mereka tidak akan mengatakan, \"Ya Rabb kami! Mengapa tidak) yakni kenapa tidak (Engkau utus seorang Rasul kepada kami, lalu kami mengikuti ayat-ayat Engkau) yang dibawa oleh Rasul Engkau (dan jadilah kami termasuk orang-orang yang beriman\") Jawab dari lafal Laula dibuang, dan lafal yang sesudahnya merupakan Mubtada. Maksudnya, seandainya tidak karena azab yang menimpa mereka sebagai penyebab dari perkataannya. Atau maksudnya, seandainya tidak ada perkataan mereka yang menyebabkan turunnya azab, niscaya akan Kami segerakan kepada mereka azab itu, dan niscaya pula Kami tidak akan mengutusmu kepada mereka sebagai seorang Rasul.",[["وَلَوْلَآ","Dan jika tidak"],["أَن","[bahawa]"],["تُصِيبَهُم","memukul mereka"],["مُّصِيبَةٌۢ","satu bencana"],["بِمَا","bagi apa"],["قَدَّمَتْ","telah dihantar"],["أَيْدِيهِمْ","tangan mereka"],["فَيَقُولُوا۟","dan mereka akan berkata"],["رَبَّنَا","Wahai Tuhan kami"],["لَوْلَآ","kenapa tidak"],["أَرْسَلْتَ","Kamu hantar"],["إِلَيْنَا","kepada kami"],["رَسُولًۭا","seorang Rasul"],["فَنَتَّبِعَ","jadi kami (boleh) mengikut"],["ءَايَـٰتِكَ","Ayat-ayat Mu"],["وَنَكُونَ","dan kami (akan) telah"],["مِنَ","daripada"],["ٱلْمُؤْمِنِينَ","orang yang beriman"]]],"3300":["(Maka tatkala datang kepada mereka kebenaran) yang dibawa oleh Nabi Muhammad (dari sisi Kami, mereka berkata, \"Mengapa tidak) kenapa tidak (diberikan kepadanya seperti yang telah diberikan kepada Musa?\") yaitu mukjizat-mukjizat seperti tangan yang bersinar menyilaukan, tongkat dan lain sebagainya, atau kitab yang diturunkan sekali turun. Allah swt. menjawab perkataan mereka melalui firman-Nya, (\"Dan bukankah mereka itu telah ingkar juga kepada apa yang diberikan kepada Musa dahulu?) di mana (mereka telah mengatakan) sehubungan dengan perihal Nabi Musa dan juga tentang diri Nabi Muhammad ('Dua orang ahli sihir). Menurut qiraat yang lain dibaca Sahirani, subjek yang mereka maksud adalah Alquran dan kitab Taurat (yang saling bantu membantu'.\") maksudnya mereka saling bahu membahu. (Dan mereka juga berkata, \"Sesungguhnya kami kepada masing-masing) dari kedua nabi, berikut kitab-kitabnya (tidak mempercayai\").",[["فَلَمَّا","Tetapi apabila"],["جَآءَهُمُ","datang kepada mereka"],["ٱلْحَقُّ","kebenaran"],["مِنْ","daripada Kami"],["عِندِنَا","daripada Kami"],["قَالُوا۟","mereka berkata"],["لَوْلَآ","kenapa tidak"],["أُوتِىَ","dia diberi"],["مِثْلَ","(yang) seperti"],["مَآ","apa"],["أُوتِىَ","telah diberikan"],["مُوسَىٰٓ ۚ","(kepada) Musa"],["أَوَلَمْ","tidak"],["يَكْفُرُوا۟","mereka tidak beriman"],["بِمَآ","pada apa"],["أُوتِىَ","telah diberikan"],["مُوسَىٰ","(kepada) Musa"],["مِن","sebelum"],["قَبْلُ ۖ","sebelum"],["قَالُوا۟","Mereka berkata"],["سِحْرَانِ","Dua sihir (berfungsi)"],["تَظَـٰهَرَا","saling menyokong"],["وَقَالُوٓا۟","Dan mereka berkata"],["إِنَّا","Sesungguhnya kami"],["بِكُلٍّۢ","dalam semua"],["كَـٰفِرُونَ","(adalah) orang-orang kafir"]]],"3301":["(Katakanlah) kepada mereka, (\"Datangkanlah oleh kalian sebuah kitab dari sisi Allah yang kitab itu lebih dapat memberi petunjuk daripada keduanya) yang dimaksud adalah Alquran dan Taurat (niscaya aku akan mengikutinya, jika kalian sungguh orang-orang yang benar.\") di dalam perkataannya.",[["قُلْ","Katakanlah"],["فَأْتُوا۟","Kemudian bawa"],["بِكِتَـٰبٍۢ","sebuah Buku"],["مِّنْ","daripada Allah"],["عِندِ","daripada Allah"],["ٱللَّهِ","daripada Allah"],["هُوَ","yang"],["أَهْدَىٰ","(adalah) panduan yang lebih baik"],["مِنْهُمَآ","daripada mereka berdua"],["أَتَّبِعْهُ","supaya aku dapat mengikutinya"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"3302":["(Maka jika mereka tidak menjawab kamu) maksudnya tantanganmu itu, yaitu supaya mereka mendatangkan Kitab dari sisi Allah (ketahuilah bahwa sesungguhnya mereka hanyalah mengikuti hawa nafsu mereka belaka) dalam kekafirannya itu (Dan siapakah yang lebih sesat daripada orang yang mengikuti hawa nafsunya dengan tidak mendapat petunjuk dari Allah sedikit pun?) maksudnya, tidak ada yang lebih sesat daripadanya. (Sesungguhnya Allah tidak memberi petunjuk kepada orang-orang yang zalim) yaitu orang-orang kafir.",[["فَإِن","Tetapi jika"],["لَّمْ","tidak"],["يَسْتَجِيبُوا۟","mereka bertindak balas"],["لَكَ","kepada kamu"],["فَٱعْلَمْ","maka ketahuilah"],["أَنَّمَا","itu sahaja"],["يَتَّبِعُونَ","mereka ikut"],["أَهْوَآءَهُمْ ۚ","keinginan mereka"],["وَمَنْ","Dan siapa"],["أَضَلُّ","(adalah) lebih sesat"],["مِمَّنِ","daripada (seorang) yang"],["ٱتَّبَعَ","mengikuti"],["هَوَىٰهُ","keinginannya sendiri"],["بِغَيْرِ","tanpa"],["هُدًۭى","bimbingan"],["مِّنَ","daripada"],["ٱللَّهِ ۚ","Allah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يَهْدِى","panduan"],["ٱلْقَوْمَ","rakyat"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"3303":["(Dan sesungguhnya telah Kami jelaskan) telah Kami terangkan (perkataan ini kepada mereka) yaitu Alquran (agar mereka mendapat pelajaran) yakni mengambil pelajaran daripadanya, lalu mereka beriman.",[["۞ وَلَقَدْ","Dan sesungguhnya"],["وَصَّلْنَا","Kami telah sampaikan"],["لَهُمُ","kepada mereka"],["ٱلْقَوْلَ","Firman"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَتَذَكَّرُونَ","ingat"]]],"3304":["(Orang-orang yang telah Kami datangkan kepada mereka Alkitab sebelumnya) sebelum Alquran (mereka beriman pula kepada Alquran itu). Ayat ini diturunkan berkenaan dengan segolongan orang-orang Yahudi yang masuk Islam; antara lain; Abdullah ibnu Salam. Ayat ini diturunkan pula berkenaan dengan segolongan orang-orang Anshar yang baru datang dari negeri Habsyah/Abesinia dan negeri Syam, kemudian mereka beriman kepada Nabi saw.",[["ٱلَّذِينَ","Orang yang"],["ءَاتَيْنَـٰهُمُ","Kami memberi mereka"],["ٱلْكِتَـٰبَ","Kitab Suci"],["مِن","sebelum itu"],["قَبْلِهِۦ","sebelum itu"],["هُم","mereka"],["بِهِۦ","di dalamnya"],["يُؤْمِنُونَ","beriman"]]],"3305":["(Dan apabila dibacakan kepada mereka) Alquran (mereka berkata, \"Kami beriman kepadanya; sesungguhnya Alquran itu adalah suatu kebenaran dari Rabb kami, sesungguhnya kami adalah orang-orang yang beriman sebelumnya.\") orang-orang yang mengesakan Allah.",[["وَإِذَا","Dan apabila"],["يُتْلَىٰ","ia dibacakan"],["عَلَيْهِمْ","kepada mereka"],["قَالُوٓا۟","mereka berkata"],["ءَامَنَّا","Kami beriman"],["بِهِۦٓ","di dalamnya"],["إِنَّهُ","Sesungguhnya, ia"],["ٱلْحَقُّ","(adalah) kebenaran"],["مِن","daripada"],["رَّبِّنَآ","Tuhan kami"],["إِنَّا","Sesungguhnya kami"],["كُنَّا","[kami] dulu"],["مِن","sebelum itu"],["قَبْلِهِۦ","sebelum itu"],["مُسْلِمِينَ","orang Islam"]]],"3306":["(Mereka itu diberi pahala dua kali) karena iman mereka kepada dua Kitab (disebabkan kesabaran mereka) di dalam mengamalkan kandungan kedua Kitab itu (dan mereka menolak) menutup (kejahatan dengan kebaikan) yaitu kejahatan yang mereka lakukan ditutup dengan kebaikan mereka (dan sebagian dari apa yang telah Kami rezekikan kepada mereka, mereka nafkahkan) mereka menyedekahkannya.",[["أُو۟لَـٰٓئِكَ","Mereka itu"],["يُؤْتَوْنَ","akan diberikan"],["أَجْرَهُم","ganjaran mereka"],["مَّرَّتَيْنِ","dua kali"],["بِمَا","kerana"],["صَبَرُوا۟","mereka bersabar"],["وَيَدْرَءُونَ","dan mereka menolak"],["بِٱلْحَسَنَةِ","dengan kebaikan"],["ٱلسَّيِّئَةَ","yang jahat"],["وَمِمَّا","dan dari apa"],["رَزَقْنَـٰهُمْ","Kami telah menyediakan mereka"],["يُنفِقُونَ","mereka belanjakan"]]],"3307":["(Dan apabila mereka mendengar perkataan yang tidak bermanfaat) berupa makian dan perlakuan yang menyakitkan dari pihak orang-orang kafir (mereka berpaling daripadanya dan berkata, \"Bagi kami amal-amal kami dan bagi kalian amal-amal kalian, kesejahteraan atas diri kalian), yaitu salam selamat tinggal, yang dimaksud adalah kalian selamat dari cacian kami dan hal-hal lain (kami tidak ingin bergaul dengan orang-orang jahil.\") maksudnya tidak mau berteman dengan mereka.",[["وَإِذَا","Dan apabila"],["سَمِعُوا۟","mereka dengar"],["ٱللَّغْوَ","cakap kosong"],["أَعْرَضُوا۟","mereka berpaling"],["عَنْهُ","daripadanya"],["وَقَالُوا۟","dan katakan"],["لَنَآ","Untuk kita"],["أَعْمَـٰلُنَا","perbuatan kita"],["وَلَكُمْ","dan untuk kamu"],["أَعْمَـٰلُكُمْ","perbuatan kamu"],["سَلَـٰمٌ","Damai (semoga)"],["عَلَيْكُمْ","pada kamu"],["لَا","tidak"],["نَبْتَغِى","kita cari"],["ٱلْجَـٰهِلِينَ","yang jahil"]]],"3308":["Ayat berikut ini diturunkan berkenaan dengan keinginan Nabi saw. akan keimanan pamannya yaitu Abu Thalib. (Sesungguhnya kamu tidak akan dapat memberi petunjuk kepada orang yang kamu kasihi) supaya ia mendapat hidayah (tetapi Allah memberi petunjuk kepada orang yang dikehendaki-Nya dan Allah lebih mengetahui) yakni mengetahui (orang-orang yang mau menerima petunjuk).",[["إِنَّكَ","Sesungguhnya kamu"],["لَا","(boleh) tidak"],["تَهْدِى","panduan"],["مَنْ","yang"],["أَحْبَبْتَ","kamu sayang"],["وَلَـٰكِنَّ","tetapi"],["ٱللَّهَ","Allah"],["يَهْدِى","panduan"],["مَن","yang"],["يَشَآءُ ۚ","Dia kehendaki"],["وَهُوَ","Dan Dia"],["أَعْلَمُ","(adalah) yang paling mengetahui"],["بِٱلْمُهْتَدِينَ","(dari) orang-orang yang mendapat petunjuk"]]],"3309":["(Dan mereka berkata) yaitu kaumnya, (\"Jika kami mengikuti petunjuk bersama kamu, niscaya kami akan diusir dari negeri kami\") kami akan diusir dengan cepat daripadanya. Maka Allah swt. berfirman, (Dan apakah Kami tidak meneguhkan kedudukan mereka dalam daerah haram yang aman) maksudnya, mereka hidup dengan aman di dalamnya dari segala serangan dan pembunuhan, tidak sebagaimana yang terjadi di kalangan orang-orang Arab lainnya yang saling serang menyerang dan saling bunuh membunuh (yang didatangkan) dapat dibaca Tujba dan Yujba (ke tempat itu buah-buahan dari segala penjuru) dari berbagai penjuru (sebagai rezeki) bagi mereka (dari sisi Kami?) dari hadirat Kami (tetapi kebanyakan mereka tidak mengetahui) bahwa apa yang Kami katakan itu adalah benar.",[["وَقَالُوٓا۟","Dan mereka berkata"],["إِن","Jika"],["نَّتَّبِعِ","kita ikut"],["ٱلْهُدَىٰ","bimbingan"],["مَعَكَ","bersama kamu"],["نُتَخَطَّفْ","kita akan disapu"],["مِنْ","daripada"],["أَرْضِنَآ ۚ","tanah kita"],["أَوَلَمْ","belum"],["نُمَكِّن","Kami menubuhkan"],["لَّهُمْ","bagi mereka"],["حَرَمًا","sebuah tempat perlindungan"],["ءَامِنًۭا","selamat"],["يُجْبَىٰٓ","dibawa"],["إِلَيْهِ","kepadanya"],["ثَمَرَٰتُ","buah-buahan"],["كُلِّ","(dari) semua"],["شَىْءٍۢ","benda"],["رِّزْقًۭا","suatu peruntukan"],["مِّن","daripada"],["لَّدُنَّا","Kami"],["وَلَـٰكِنَّ","Tetapi"],["أَكْثَرَهُمْ","kebanyakan mereka"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"3310":["(Dan berapa banyaknya negeri yang telah Kami binasakan yang sudah bersenang-senang dalam kehidupannya) yang dimaksud adalah penduduk negeri-negeri tersebut (maka itulah tempat kediaman mereka yang tidak didiami lagi sesudah mereka, kecuali sebagian kecil) untuk orang-orang yang lewat yang tinggal hanya sehari atau setengah hari. (Dan Kami adalah pewarisnya) dari mereka.",[["وَكَمْ","Dan berapa banyak"],["أَهْلَكْنَا","Kami telah memusnahkan"],["مِن","daripada"],["قَرْيَةٍۭ","sebuah bandar"],["بَطِرَتْ","yang bergembira"],["مَعِيشَتَهَا ۖ","(dalam) mata pencariannya"],["فَتِلْكَ","Dan ini"],["مَسَـٰكِنُهُمْ","(adalah) tempat tinggal mereka"],["لَمْ","tidak"],["تُسْكَن","telah didiami"],["مِّنۢ","selepas mereka"],["بَعْدِهِمْ","selepas mereka"],["إِلَّا","kecuali"],["قَلِيلًۭا ۖ","sedikit"],["وَكُنَّا","Dan sesungguhnya, [Kami]"],["نَحْنُ","Kami"],["ٱلْوَٰرِثِينَ","(adalah) ahli waris"]]],"3311":["(Dan tiadalah Rabbmu membinasakan kota-kota) disebabkan kelaliman yang dilakukan oleh para penduduknya (sebelum Dia mengutus di ibu kota itu) yakni pada kota terbesar negeri itu (seorang Rasul yang membacakan ayat-ayat Kami kepada mereka dan tidak pernah pula Kami membinasakan kota-kota kecuali penduduknya dalam keadaan melakukan kelaliman) yaitu mendustakan Rasul-rasul.",[["وَمَا","Dan tidak"],["كَانَ","adalah"],["رَبُّكَ","Tuhanmu"],["مُهْلِكَ","(yang) memusnahkan"],["ٱلْقُرَىٰ","bandar-bandar"],["حَتَّىٰ","sehingga"],["يَبْعَثَ","Dia (telah) menghantar"],["فِىٓ","dalam"],["أُمِّهَا","ibu mereka (bandar)"],["رَسُولًۭا","seorang Rasul"],["يَتْلُوا۟","mengaji"],["عَلَيْهِمْ","kepada mereka"],["ءَايَـٰتِنَا ۚ","Ayat Kami"],["وَمَا","Dan tidak"],["كُنَّا","Kami akan menjadi"],["مُهْلِكِى","(yang) memusnahkan"],["ٱلْقُرَىٰٓ","bandar-bandar"],["إِلَّا","kecuali"],["وَأَهْلُهَا","sedangkan rakyat mereka"],["ظَـٰلِمُونَ","(adalah) orang-orang yang zalim"]]],"3312":["(Dan apa saja yang diberikan kepada kalian, maka itu adalah kenikmatan hidup duniawi dan perhiasannya) kalian bersenang-senang dan menghias diri dengannya selama hidup kalian, kemudian semuanya akan lenyap (sedangkan apa yang di sisi Allah) yakni pahala-Nya (adalah lebih baik dan lebih kekal. Maka apakah kalian tidak memahaminya?) bahwa yang kekal itu lebih baik daripada yang lenyap. Dapat dibaca Ta'maluna dan Ya'maluna.",[["وَمَآ","Dan apa sahaja"],["أُوتِيتُم","kamu telah diberi"],["مِّن","daripada"],["شَىْءٍۢ","benda"],["فَمَتَـٰعُ","(adalah) kenikmatan"],["ٱلْحَيَوٰةِ","(dari) kehidupan"],["ٱلدُّنْيَا","dunia"],["وَزِينَتُهَا ۚ","dan perhiasannya"],["وَمَا","Dan apa"],["عِندَ","(adalah) dengan"],["ٱللَّهِ","Allah"],["خَيْرٌۭ","(lebih) baik"],["وَأَبْقَىٰٓ ۚ","dan lebih tahan lama"],["أَفَلَا","Jadi (akan) tidak"],["تَعْقِلُونَ","kamu menggunakan akal"]]],"3313":["(Maka apakah orang yang Kami janjikan kepadanya suatu janji yang baik lalu ia memperolehnya) janji yang dimaksud adalah surga (sama dengan orang yang Kami berikan kepadanya kenikmatan hidup duniawi) yang dalam waktu dekat pasti akan lenyap (kemudian dia pada hari kiamat termasuk orang-orang yang diseret) ke dalam neraka. Orang yang dimaksud pada lafal pertama adalah orang Mukmin dan pada lafal kedua adalah orang kafir maksudnya tidak ada persamaan di antara keduanya.",[["أَفَمَن","Maka adakah (dia) yang"],["وَعَدْنَـٰهُ","Kami telah berjanji kepadanya"],["وَعْدًا","sebuah janji"],["حَسَنًۭا","kebaikan"],["فَهُوَ","dan dia"],["لَـٰقِيهِ","(akan) menemuinya"],["كَمَن","seperti (yang) siapa"],["مَّتَّعْنَـٰهُ","Kami menyediakan dia"],["مَتَـٰعَ","kenikmatan"],["ٱلْحَيَوٰةِ","(dari) kehidupan"],["ٱلدُّنْيَا","dunia"],["ثُمَّ","kemudian"],["هُوَ","dia"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["مِنَ","(akan) antara"],["ٱلْمُحْضَرِينَ","yang dibentangkan"]]],"3314":["(Dan) ingatlah (hari di waktu Dia menyeru mereka) yang dimaksud adalah Allah menyeru mereka (seraya berkata, \"Di manakah sekutu-sekutu-Ku yang dahulu kalian menduga\") bahwa mereka adalah sekutu-sekutu-Ku.",[["وَيَوْمَ","Dan (hari) itu"],["يُنَادِيهِمْ","Dia akan memanggil mereka"],["فَيَقُولُ","dan katakan"],["أَيْنَ","di mana"],["شُرَكَآءِىَ","(adalah) rakan kongsi aku"],["ٱلَّذِينَ","yang"],["كُنتُمْ","kamu pernah (untuk)"],["تَزْعُمُونَ","tuntutan"]]],"3315":["(Berkatalah orang-orang yang telah tetap hukuman atas mereka) yakni mereka harus masuk ke dalam neraka, mereka adalah para pemimpin kesesatan, (\"Ya Rabb kami! Mereka inilah orang-orang yang kami sesatkan itu) lafal Haula-i adalah Mubtada dan Al Ladzina Aghwainahum adalah sifatnya (kami telah menyesatkan mereka) lafal ayat ini menjadi Khabarnya. Yaitu setelah kami sesatkan mereka, maka mereka pun tersesatlah (sebagaimana kami sendiri sesat) yakni, kami tidak memaksakan mereka untuk sesat (kami menyatakan berlepas diri kepada Engkau) dari mereka (mereka sekali-kali tidak menyembah kami\") Ma di sini adalah Nafiyah, dan sengaja Maf'ulnya didahulukan demi untuk Fashilah, atau untuk memelihara keseragaman akhir ayat.",[["قَالَ","(Akan) katakan"],["ٱلَّذِينَ","mereka"],["حَقَّ","(telah) menjadi kenyataan"],["عَلَيْهِمُ","terhadap siapa"],["ٱلْقَوْلُ","Firman"],["رَبَّنَا","Wahai Tuhan kami"],["هَـٰٓؤُلَآءِ","Ini"],["ٱلَّذِينَ","(adalah) mereka yang"],["أَغْوَيْنَآ","kita sesat"],["أَغْوَيْنَـٰهُمْ","Kami menyesatkan mereka"],["كَمَا","seperti"],["غَوَيْنَا ۖ","kami sesat"],["تَبَرَّأْنَآ","Kami mengisytiharkan kami tidak bersalah"],["إِلَيْكَ ۖ","sebelum Engkau"],["مَا","Tidak"],["كَانُوٓا۟","mereka pernah (untuk)"],["إِيَّانَا","menyembah kami"],["يَعْبُدُونَ","menyembah kami"]]],"3316":["(Dikatakan kepada mereka \"Serulah oleh kalian sekutu-sekutu kalian!\") yaitu berhala-berhala yang kalian yakini, bahwa mereka adalah sekutu-sekutu Allah (lalu mereka menyerunya, maka sekutu-sekutu itu tidak memperkenankan mereka) tidak menjawab seruan mereka (lalu mereka melihat) mereka yang diseru itu (azab) melihatnya dengan mata kepala mereka (kiranya mereka dahulu menerima petunjuk) sewaktu di dunia, mereka baru sadar setelah melihat azab di akhirat.",[["وَقِيلَ","Dan ia akan dikatakan"],["ٱدْعُوا۟","Panggil"],["شُرَكَآءَكُمْ","rakan kongsi kamu"],["فَدَعَوْهُمْ","Dan mereka akan memanggil mereka"],["فَلَمْ","tetapi tidak"],["يَسْتَجِيبُوا۟","mereka akan bertindak balas"],["لَهُمْ","kepada mereka"],["وَرَأَوُا۟","dan mereka akan melihat"],["ٱلْعَذَابَ ۚ","azab"],["لَوْ","Jika sahaja"],["أَنَّهُمْ","[bahawa] mereka"],["كَانُوا۟","telah"],["يَهْتَدُونَ","dibimbing"]]],"3317":["(Dan) ingatlah (hari di waktu Allah menyeru mereka, seraya berkata \"Apakah jawaban kalian kepada para Rasul?\") yang diutus kepada kalian.",[["وَيَوْمَ","Dan (hari) itu"],["يُنَادِيهِمْ","Dia akan memanggil mereka"],["فَيَقُولُ","dan katakan"],["مَاذَآ","Apa"],["أَجَبْتُمُ","adakah kamu menjawab"],["ٱلْمُرْسَلِينَ","para Rasul"]]],"3318":["(Maka gelaplah bagi mereka segala alasan) maksudnya alasan yang dapat menyelamatkan diri mereka tidak dapat mereka kemukakan (di hari itu) mereka tidak dapat menemukan alasan agar dirinya dapat selamat dari azab (karena itu mereka tidak saling tanya menanya) mengenai hal ini, mereka hanya diam saja.",[["فَعَمِيَتْ","Tetapi (akan) menjadi kabur"],["عَلَيْهِمُ","kepada mereka"],["ٱلْأَنۢبَآءُ","maklumat tersebut"],["يَوْمَئِذٍۢ","hari itu"],["فَهُمْ","jadi mereka"],["لَا","tidak akan bertanya antara satu sama lain"],["يَتَسَآءَلُونَ","tidak akan bertanya antara satu sama lain"]]],"3319":["(Adapun orang yang bertobat) dari kemusyrikan (dan beriman) percaya kepada keesaan Allah (serta mengerjakan amal yang saleh) yakni melaksanakan perbuatan-perbuatan yang difardukan (semoga dia termasuk orang-orang yang beruntung) yang selamat berkat adanya janji Allah.",[["فَأَمَّا","Tetapi untuk"],["مَن","(dia) siapa"],["تَابَ","bertaubat"],["وَءَامَنَ","dan beriman"],["وَعَمِلَ","dan lakukan"],["صَـٰلِحًۭا","kebenaran"],["فَعَسَىٰٓ","maka mungkin"],["أَن","[bahawa]"],["يَكُونَ","dia akan jadi"],["مِنَ","daripada"],["ٱلْمُفْلِحِينَ","yang berjaya"]]],"3320":["(Dan Rabbmu menciptakan apa saja yang dikehendaki-Nya dan memilih) apa yang dikehendaki-Nya. (Sekali-kali tidak ada bagi mereka) yakni bagi orang-orang musyrik (pilihan) maksudnya mereka tidak mempunyai pilihan apa-apa. (Maha Suci Allah dan Maha Tinggi dari apa yang mereka persekutukan) dari kemusyrikan mereka.",[["وَرَبُّكَ","Dan Tuhanmu"],["يَخْلُقُ","mencipta"],["مَا","apa"],["يَشَآءُ","Dia kehendaki"],["وَيَخْتَارُ ۗ","dan memilih"],["مَا","Tidak"],["كَانَ","mereka ada"],["لَهُمُ","bagi mereka"],["ٱلْخِيَرَةُ ۚ","pilihan"],["سُبْحَـٰنَ","Maha Suci"],["ٱللَّهِ","(kepada) Allah"],["وَتَعَـٰلَىٰ","dan Maha Tinggi Dia"],["عَمَّا","atas apa"],["يُشْرِكُونَ","mereka mempersekutukan (dengan Dia)"]]],"3321":["(Dan Rabbmu mengetahui apa yang disembunyikan dalam dada mereka) yakni yang dirahasiakan di dalam hati mereka berupa kekafiran dan dosa-dosa lainnya (dan apa yang mereka nyatakan) dengan lisan mereka dari hal-hal tersebut.",[["وَرَبُّكَ","Dan Tuhanmu"],["يَعْلَمُ","mengetahui"],["مَا","apa"],["تُكِنُّ","menyembunyikan"],["صُدُورُهُمْ","buah dada mereka"],["وَمَا","dan apa"],["يُعْلِنُونَ","mereka mengisytiharkan"]]],"3322":["(Dan Dia-lah Allah, tidak ada Tuhan yang berhak disembah melainkan Dia, bagi-Nya-lah segala puji di dunia) (dan di akhirat) yaitu di surga (dan bagi-Nya-lah segala penentuan) yakni, keputusan yang terlaksana dalam segala sesuatu (dan hanya kepada-Nya-lah kalian dikembalikan) melalui hari berbangkit.",[["وَهُوَ","Dan Dia"],["ٱللَّهُ","(ialah) Allah"],["لَآ","(ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","tetapi"],["هُوَ ۖ","Dia"],["لَهُ","KepadaNya"],["ٱلْحَمْدُ","(adalah kerana) segala pujian"],["فِى","dalam"],["ٱلْأُولَىٰ","yang pertama"],["وَٱلْـَٔاخِرَةِ ۖ","dan yang terakhir"],["وَلَهُ","Dan untuk Dia"],["ٱلْحُكْمُ","(ialah) Keputusan"],["وَإِلَيْهِ","dan kepada-Nya"],["تُرْجَعُونَ","kamu akan dikembalikan"]]],"3323":["(Katakanlah) kepada penduduk Mekah (\"Terangkanlah kepadaku) ceritakanlah kepadaku (jika Allah menjadikan untuk kalian malam itu terus menerus) selama-lamanya (sampai hari kiamat, siapakah Tuhan selain Allah) menurut dugaan kalian (yang akan mendatangkan sinar terang kepada kalian?) siang hari kalian mencari penghidupan di dalamnya. (Maka apakah kalian tidak mendengar?\") hal tersebut dengan pendengaran yang dibarengi dengan pemahaman, karenanya kalian tidak akan melakukan kemusyrikan lagi.",[["قُلْ","Katakanlah"],["أَرَءَيْتُمْ","Pernahkah kamu melihat"],["إِن","jika"],["جَعَلَ","Allah jadikan"],["ٱللَّهُ","Allah jadikan"],["عَلَيْكُمُ","bagi kamu"],["ٱلَّيْلَ","malam"],["سَرْمَدًا","berterusan"],["إِلَىٰ","sehingga"],["يَوْمِ","(the) Hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["مَنْ","yang"],["إِلَـٰهٌ","(ialah) tuhan"],["غَيْرُ","selain"],["ٱللَّهِ","Allah"],["يَأْتِيكُم","yang boleh membawa kamu"],["بِضِيَآءٍ ۖ","ringan"],["أَفَلَا","Kemudian tidak akan"],["تَسْمَعُونَ","kamu dengar"]]],"3324":["(Katakanlah) kepada mereka, (\"Terangkanlah kepadaku, jika Allah menjadikan untuk kalian siang itu terus menerus sampai hari kiamat, siapakah Tuhan selain Allah) menurut dugaan kalian (yang akan mendatangkan malam kepada kalian yang kalian berdiam diri) yakni beristirahat (padanya?) dari kelelahan dan kecapekan. (Maka apakah kalian tidak memperhatikan?\") kesalahan yang kalian lakukan sekarang, yaitu berupa perbuatan musyrik; oleh karena itu kemudian kalian meninggalkannya.",[["قُلْ","Katakanlah"],["أَرَءَيْتُمْ","Pernahkah kamu melihat"],["إِن","jika"],["جَعَلَ","Allah jadikan"],["ٱللَّهُ","Allah jadikan"],["عَلَيْكُمُ","bagi kamu"],["ٱلنَّهَارَ","hari itu"],["سَرْمَدًا","berterusan"],["إِلَىٰ","sehingga"],["يَوْمِ","(the) Hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["مَنْ","yang"],["إِلَـٰهٌ","(ialah) tuhan"],["غَيْرُ","selain"],["ٱللَّهِ","Allah"],["يَأْتِيكُم","yang boleh membawa kamu"],["بِلَيْلٍۢ","malam"],["تَسْكُنُونَ","(untuk) kamu (untuk) berehat"],["فِيهِ ۖ","di dalamnya"],["أَفَلَا","Kemudian tidak akan"],["تُبْصِرُونَ","kamu lihat"]]],"3325":["(Dan karena rahmat-Nya) rahmat Allah swt. (Dia jadikan untuk kalian malam dan siang, supaya kalian beristirahat padanya) yakni pada malam harinya (dan supaya kalian mencari sebagian dari karunia-Nya) pada siang harinya, untuk mencari penghidupan (dan agar kalian bersyukur) dengan adanya nikmat Allah pada kedua waktu itu, yaitu malam hari dan siang hari.",[["وَمِن","Dan daripada"],["رَّحْمَتِهِۦ","KerahimanNya"],["جَعَلَ","Dia buat"],["لَكُمُ","bagi kamu"],["ٱلَّيْلَ","malam"],["وَٱلنَّهَارَ","dan hari"],["لِتَسْكُنُوا۟","supaya kamu boleh berehat"],["فِيهِ","di dalamnya"],["وَلِتَبْتَغُوا۟","dan supaya kamu mencari"],["مِن","daripada"],["فَضْلِهِۦ","Bounty-Nya"],["وَلَعَلَّكُمْ","dan supaya kamu boleh"],["تَشْكُرُونَ","bersyukurlah"]]],"3326":["(Dan) ingatlah (hari di waktu Allah menyeru mereka, seraya berkata, \"Di manakah sekutu-sekutu-Ku yang dahulu kalian katakan?\") ayat ini disebutkan kembali sebagai pendahuluan dari kisah selanjutnya, yang diungkapkan oleh ayat berikut ini, yaitu,",[["وَيَوْمَ","Dan (hari) itu"],["يُنَادِيهِمْ","Dia akan memanggil mereka"],["فَيَقُولُ","dan katakan"],["أَيْنَ","di mana"],["شُرَكَآءِىَ","(adalah) rakan kongsi aku"],["ٱلَّذِينَ","yang"],["كُنتُمْ","kamu pernah (untuk)"],["تَزْعُمُونَ","tuntutan"]]],"3327":["(Dan kami datangkan) Kami hadirkan (dari tiap-tiap umat seorang saksi) seorang nabi yang menyaksikan apa yang telah mereka katakan (lalu Kami berkata) kepada mereka, (\"Tunjukkanlah bukti kebenaran kalian\") yang menunjukkan kebenaran dari kemusyrikan yang kalian lakukan itu (maka tahulah mereka bahwasanya yang hak) menyandang sifat Tuhan (kepunyaan Allah) tiada seorang pun yang berserikat dengan-Nya dalam hal ini (dan lenyaplah) yakni hilanglah (dari mereka apa yang dahulunya mereka ada-adakan) di dunia, yaitu dakwaan bahwa di samping Allah ada tuhan yang lain; Maha Tinggi Allah dari hal itu.",[["وَنَزَعْنَا","Dan Kami akan menarik keluar"],["مِن","daripada"],["كُلِّ","setiap"],["أُمَّةٍۢ","bangsa"],["شَهِيدًۭا","seorang saksi"],["فَقُلْنَا","dan Kami akan berkata"],["هَاتُوا۟","bawa"],["بُرْهَـٰنَكُمْ","bukti kamu"],["فَعَلِمُوٓا۟","Kemudian mereka akan tahu"],["أَنَّ","bahawa"],["ٱلْحَقَّ","kebenaran"],["لِلَّهِ","(adalah) untuk Allah"],["وَضَلَّ","dan (akan) hilang"],["عَنْهُم","daripada mereka"],["مَّا","apa"],["كَانُوا۟","mereka pernah (untuk)"],["يَفْتَرُونَ","mencipta"]]],"3328":["(Sesungguhnya Karun adalah termasuk kaum Musa) dia adalah saudara sepupu Nabi Musa sendiri, yaitu anak saudara lelaki ayah Nabi Musa yang kawin dengan saudara perempuan ibu Nabi Musa, dan Karun beriman kepada Nabi Musa (maka ia berlaku aniaya terhadap mereka) yaitu bersifat takabur; sombong dan merasa paling banyak hartanya (dan Kami telah menganugerahkan kepadanya perbendaharaan harta yang kunci-kuncinya sungguh berat dipikul) terasa berat apabila dipikul (oleh sejumlah) segolongan (orang-orang yang mempunyai) yang memiliki (kekuatan) maksudnya, kunci-kunci itu sangat berat dirasakan oleh mereka. Huruf Ba yang ada pada lafal Bil 'ushbah berfungsi untuk Ta'diyah. Menurut suatu pendapat dikatakan, bahwa jumlah mereka ada tujuh puluh orang; dan menurut pendapat yang lain dikatakan bahwa jumlah mereka ada empat puluh orang, sedangkan menurut yang lainnya lagi berjumlah sepuluh orang, dan menurut yang lainnya lagi selain dari itu. Ingatlah (ketika kaumnya berkata kepadanya) yaitu orang-orang yang beriman dari kalangan kaum Bani Israel berkata kepada Karun (\"Janganlah kamu bangga) dan sombong karena memiliki banyak harta, (sesungguhnya Allah tidak menyukai orang-orang yang terlalu membanggakan diri\") dengan harta yang dimilikinya.",[["۞ إِنَّ","Sesungguhnya"],["قَـٰرُونَ","Qarun"],["كَانَ","adalah"],["مِن","daripada"],["قَوْمِ","kaum"],["مُوسَىٰ","(dari) Musa"],["فَبَغَىٰ","tetapi dia menindas"],["عَلَيْهِمْ ۖ","[pada] mereka"],["وَءَاتَيْنَـٰهُ","Dan Kami berikan kepadanya"],["مِنَ","daripada"],["ٱلْكُنُوزِ","khazanah"],["مَآ","yang"],["إِنَّ","sesungguhnya"],["مَفَاتِحَهُۥ","(the) kuncinya"],["لَتَنُوٓأُ","akan membebankan"],["بِٱلْعُصْبَةِ","sebuah syarikat (lelaki)"],["أُو۟لِى","yang mempunyai kekuatan yang besar"],["ٱلْقُوَّةِ","yang mempunyai kekuatan yang besar"],["إِذْ","Apabila"],["قَالَ","berkata"],["لَهُۥ","kepadanya"],["قَوْمُهُۥ","umatnya"],["لَا","Jangan"],["تَفْرَحْ ۖ","bergembira"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يُحِبُّ","cinta"],["ٱلْفَرِحِينَ","yang bergembira"]]],"3329":["(Dan carilah) upayakanlah (pada apa yang telah dianugerahkan Allah kepada kalian) berupa harta benda (kebahagiaan negeri akhirat) seumpamanya kamu menafkahkannya di jalan ketaatan kepada Allah (dan janganlah kamu melupakan) jangan kamu lupa (bagianmu dari kenikmatan duniawi) yakni hendaknya kamu beramal dengannya untuk mencapai pahala di akhirat (dan berbuat baiklah) kepada orang-orang dengan bersedekah kepada mereka (sebagaimana Allah telah berbuat baik kepadamu, dan janganlah kamu berbuat) mengadakan (kerusakan di muka bumi) dengan mengerjakan perbuatan-perbuatan maksiat. (Sesungguhnya Allah tidak menyukai orang-orang yang berbuat kerusakan) maksudnya Allah pasti akan menghukum mereka.",[["وَٱبْتَغِ","Tetapi cari"],["فِيمَآ","melalui apa"],["ءَاتَىٰكَ","Allah telah memberi kamu"],["ٱللَّهُ","Allah telah memberi kamu"],["ٱلدَّارَ","rumah itu"],["ٱلْـَٔاخِرَةَ ۖ","(dari) Akhirat"],["وَلَا","dan jangan"],["تَنسَ","lupa"],["نَصِيبَكَ","bahagian kamu"],["مِنَ","daripada"],["ٱلدُّنْيَا ۖ","dunia"],["وَأَحْسِن","Dan berbuat baik"],["كَمَآ","seperti"],["أَحْسَنَ","Allah telah baik"],["ٱللَّهُ","Allah telah baik"],["إِلَيْكَ ۖ","kepada kamu"],["وَلَا","Dan jangan"],["تَبْغِ","mencari"],["ٱلْفَسَادَ","rasuah"],["فِى","dalam"],["ٱلْأَرْضِ ۖ","bumi"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يُحِبُّ","cinta"],["ٱلْمُفْسِدِينَ","para perasuah"]]],"3330":["(Karun berkata, \"Sesungguhnya aku hanya diberi harta itu) harta yang ada padanya itu (karena ilmu yang ada padaku\") sebagai imbalan dari pengetahuan yang aku miliki; dia seorang yang paling ulung di kalangan Bani Israel mengenai kitab Taurat, sesudah Musa dan Harun. Allah berfirman, (Dan apakah ia tidak mengetahui bahwasanya Allah sungguh telah membinasakan umat-umat sebelumnya) yakni, bangsa-bangsa sebelumnya (yang lebih kuat daripadanya dan lebih banyak mengumpulkan harta?) maksudnya, Karun mengetahui kisah mereka, kemudian mereka dibinasakan oleh Allah. (Dan tidaklah perlu ditanyakan kepada orang-orang yang berdosa itu, tentang dosa-dosa mereka) karena Allah mengetahui hal tersebut, maka mereka dimasukkan ke neraka tanpa dihisab lagi.",[["قَالَ","Dia berkata"],["إِنَّمَآ","Hanya"],["أُوتِيتُهُۥ","Aku telah diberikannya"],["عَلَىٰ","pada (akaun)"],["عِلْمٍ","(dari) pengetahuan"],["عِندِىٓ ۚ","aku ada"],["أَوَلَمْ","tidak"],["يَعْلَمْ","dia tahu"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["قَدْ","sesungguhnya"],["أَهْلَكَ","musnah"],["مِن","sebelum dia"],["قَبْلِهِۦ","sebelum dia"],["مِنَ","daripada"],["ٱلْقُرُونِ","generasi"],["مَنْ","yang"],["هُوَ","[mereka]"],["أَشَدُّ","(adalah) lebih kuat"],["مِنْهُ","daripada dia"],["قُوَّةًۭ","(dalam) kekuatan"],["وَأَكْثَرُ","dan lebih besar"],["جَمْعًۭا ۚ","(dalam) pengumpulan"],["وَلَا","Dan tidak"],["يُسْـَٔلُ","akan dipersoalkan"],["عَن","tentang"],["ذُنُوبِهِمُ","dosa mereka"],["ٱلْمُجْرِمُونَ","penjenayah"]]],"3331":["(Maka keluarlah) Karun (kepada kaumnya dalam kemegahannya) berikut para pengikutnya yang banyak jumlahnya; mereka semuanya menaiki kendaraan seraya memakai pakaian emas dan sutra. Kuda-kuda serta keledai-keledai yang mereka naiki pun dihiasnya. (Berkatalah orang-orang yang menghendaki kehidupan dunia, \"Aduhai!) huruf Ya di sini menunjukkan makna Tanbih (Kiranya kita mempunyai seperti apa yang telah diberikan kepada Karun) dalam masalah keduniawian (sesungguhnya ia benar-benar mempunyai keberuntungan) yakni bagian (yang besar.\") yang sangat banyak keberuntungannya.",[["فَخَرَجَ","Jadi dia pergi"],["عَلَىٰ","kepada"],["قَوْمِهِۦ","umatnya"],["فِى","dalam"],["زِينَتِهِۦ ۖ","perhiasannya"],["قَالَ","Berkata"],["ٱلَّذِينَ","orang yang"],["يُرِيدُونَ","keinginan"],["ٱلْحَيَوٰةَ","kehidupan"],["ٱلدُّنْيَا","dunia"],["يَـٰلَيْتَ","O! Adakah itu"],["لَنَا","bagi kami"],["مِثْلَ","(yang) seperti"],["مَآ","apa"],["أُوتِىَ","telah diberikan"],["قَـٰرُونُ","(kepada) Qarun"],["إِنَّهُۥ","Sesungguhnya dia"],["لَذُو","(adalah) pemiliknya"],["حَظٍّ","(dari) nasib"],["عَظِيمٍۢ","yang besar"]]],"3332":["(Berkatalah) kepada mereka (orang-orang yang dianugerahi ilmu) tentang apa yang telah dijanjikan oleh Allah kelak di akhirat, (\"Kecelakaan yang besarlah bagi kalian) lafal Wailakum ini adalah kalimat hardikan (pahala Allah) di akhirat berupa surga (adalah lebih baik bagi orang-orang yang beriman dan beramal saleh) daripada apa yang diberikan oleh Allah kepada Karun di dunia (dan tidak diperoleh pahala itu) yakni surga (kecuali oleh orang-orang yang sabar\") di dalam menjalankan ketaatan dan menjauhi maksiat.",[["وَقَالَ","Tetapi berkata"],["ٱلَّذِينَ","orang yang"],["أُوتُوا۟","telah diberikan"],["ٱلْعِلْمَ","pengetahuan itu"],["وَيْلَكُمْ","Celakalah kamu"],["ثَوَابُ","(The) ganjaran"],["ٱللَّهِ","(milik) Allah"],["خَيْرٌۭ","(lebih) baik"],["لِّمَنْ","untuk (dia) yang"],["ءَامَنَ","beriman"],["وَعَمِلَ","dan melakukan"],["صَـٰلِحًۭا","benar (perbuatan)"],["وَلَا","Dan tidak"],["يُلَقَّىٰهَآ","ia diberikan"],["إِلَّا","kecuali"],["ٱلصَّـٰبِرُونَ","(kepada) orang-orang yang sabar"]]],"3333":["(Maka Kami benamkan dia) Karun (beserta rumahnya ke dalam bumi. Maka tidak ada lagi baginya suatu golongan pun yang menolongnya terhadap azab Allah) seumpamanya penolong itu dapat mencegah kebinasaan dari diri Karun. (Dan tiadalah ia termasuk orang-orang yang dapat membela dirinya) dari azab Allah.",[["فَخَسَفْنَا","Kemudian Kami telan"],["بِهِۦ","dia"],["وَبِدَارِهِ","dan rumahnya"],["ٱلْأَرْضَ","bumi"],["فَمَا","Kemudian tidak"],["كَانَ","adalah"],["لَهُۥ","baginya"],["مِن","sebarang"],["فِئَةٍۢ","kumpulan"],["يَنصُرُونَهُۥ","(untuk) menolongnya"],["مِن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["وَمَا","dan bukan"],["كَانَ","adalah"],["مِنَ","(dia) daripada"],["ٱلْمُنتَصِرِينَ","mereka yang (boleh) mempertahankan diri"]]],"3334":["(Dan jadilah orang-orang yang kemarin mencita-citakan kedudukan Karun itu) dalam waktu yang singkat (mereka berkata, \"Aduhai! Benarlah Allah melapangkan) yakni meluaskan (rezeki bagi siapa yang Dia kehendaki dari hamba-hamba-Nya dan membatasinya) menyempitkannya bagi orang-orang yang dikehendaki-Nya. Lafal Way adalah Isim Fi'il yang artinya aku sangat kagum, dan huruf Kaf mempunyai makna huruf Lam. Maksudnya, aku sangat takjub karena sesungguhnya Allah melapangkan dan seterusnya (kalau Allah tidak melimpahkan harunia-Nya atas kita, benar-benar Dia telah membenamkan kita pula) dapat dibaca Lakhasafa dan Lakhusifa (Aduhai benarlah, tidak beruntung orang-orang yang mengingkari.\") nikmat Allah seperti Karun tadi.",[["وَأَصْبَحَ","Dan bermula"],["ٱلَّذِينَ","orang yang"],["تَمَنَّوْا۟","(telah) berhajat"],["مَكَانَهُۥ","kedudukannya"],["بِٱلْأَمْسِ","hari sebelumnya"],["يَقُولُونَ","(untuk) berkata"],["وَيْكَأَنَّ","Ah! Itu"],["ٱللَّهَ","Allah"],["يَبْسُطُ","memanjang"],["ٱلرِّزْقَ","peruntukan itu"],["لِمَن","untuk siapa"],["يَشَآءُ","Dia kehendaki"],["مِنْ","daripada"],["عِبَادِهِۦ","hambanya"],["وَيَقْدِرُ ۖ","dan menyekatnya"],["لَوْلَآ","Jika tidak"],["أَن","bahawa"],["مَّنَّ","Allah telah memberi nikmat"],["ٱللَّهُ","Allah telah memberi nikmat"],["عَلَيْنَا","[kepada] kami"],["لَخَسَفَ","Dia akan menyebabkan ia menelan kita"],["بِنَا ۖ","Dia akan menyebabkan ia menelan kita"],["وَيْكَأَنَّهُۥ","Ah! Itu"],["لَا","tidak"],["يُفْلِحُ","akan berjaya"],["ٱلْكَـٰفِرُونَ","orang kafir"]]],"3335":["(Negeri akhirat itu,) yakni surga (Kami jadikan untuk orang-orang yang tidak ingin menyombongkan diri di muka bumi) dengan melakukan kelaliman (dan tidak pula berbuat kerusakan) dengan melakukan perbuatan-perbuatan maksiat. (Dan kesudahan yang baik itu) yakni yang terpuji (adalah bagi orang orang yang bertakwa) maksudnya bagi orang-orang yang takut kepada azab Allah, yaitu dengan melakukan perbuatan-perbuatan ketaatan kepada-Nya.",[["تِلْكَ","Itu"],["ٱلدَّارُ","Rumah itu"],["ٱلْـَٔاخِرَةُ","(dari) Akhirat"],["نَجْعَلُهَا","Kami menetapkannya"],["لِلَّذِينَ","kepada mereka yang"],["لَا","jangan"],["يُرِيدُونَ","keinginan"],["عُلُوًّۭا","kemuliaan"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَلَا","dan bukan"],["فَسَادًۭا ۚ","rasuah"],["وَٱلْعَـٰقِبَةُ","Dan kesudahan yang baik"],["لِلْمُتَّقِينَ","(adalah) untuk orang-orang yang bertakwa"]]],"3336":["(Barang siapa yang datang dengan membawa kebaikan, maka baginya pahala yang lebih baik daripada kebaikannya itu) sebagai imbalan daripada kebaikan yang dibawanya, yaitu sebanyak sepuluh kali lipat dari pahala kebaikannya (dan barang siapa yang datang dengan membawa kejahatan, maka tidaklah diberi pembalasan kepada orang-orang yang telah mengerjakan kejahatan itu melainkan) pembalasan yang seimbang (dengan apa yang dahulu mereka kerjakan) yakni dengan kejahatannya.",[["مَن","Siapa pun"],["جَآءَ","datang"],["بِٱلْحَسَنَةِ","dengan kebaikan (perbuatan)"],["فَلَهُۥ","kemudian untuk dia"],["خَيْرٌۭ","(akan menjadi) lebih baik"],["مِّنْهَا ۖ","daripadanya"],["وَمَن","dan sesiapa"],["جَآءَ","datang"],["بِٱلسَّيِّئَةِ","dengan kejahatan (perbuatan)"],["فَلَا","maka tidak"],["يُجْزَى","akan diberi ganjaran"],["ٱلَّذِينَ","orang yang"],["عَمِلُوا۟","lakukan"],["ٱلسَّيِّـَٔاتِ","kejahatan (perbuatan)"],["إِلَّا","kecuali"],["مَا","apa"],["كَانُوا۟","mereka pernah (untuk)"],["يَعْمَلُونَ","lakukan"]]],"3337":["(Sesungguhnya yang mewajibkan atasmu Alquran) yakni yang menurunkannya (benar-benar akan mengembalikan kamu ke tempat kembali) ke Mekah, dan bahwa Nabi saw. telah rindu sekali kepada kota Mekah (katakanlah, \"Rabbku mengetahui) tentang (orang yang membawa petunjuk dan orang yang dalam kesesatan yang nyata\"). Ayat ini diturunkan sebagai jawaban atas perkataan orang-orang kafir Mekah terhadap Nabi saw.; mereka menuduhnya bahwa ia sesat. Makna ayat ini, dia yakni Nabi saw. datang dengan membawa petunjuk sedangkan mereka adalah orang-orang yang berada dalam kesesatan. Dan lafal A'lam bermakna Alimun yakni mengetahui.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِى","Dia Siapa"],["فَرَضَ","ditahbiskan"],["عَلَيْكَ","ke atas kamu"],["ٱلْقُرْءَانَ","al-Quran"],["لَرَآدُّكَ","(akan) membawa kamu kembali"],["إِلَىٰ","kepada"],["مَعَادٍۢ ۚ","tempat kembali"],["قُل","Katakanlah"],["رَّبِّىٓ","Tuhanku"],["أَعْلَمُ","(adalah) yang paling mengetahui"],["مَن","(daripadanya) siapa"],["جَآءَ","datang"],["بِٱلْهُدَىٰ","dengan bimbingan"],["وَمَنْ","dan siapa"],["هُوَ","dia"],["فِى","(berada) dalam"],["ضَلَـٰلٍۢ","satu kesilapan"],["مُّبِينٍۢ","nyata"]]],"3338":["(Dan kamu tidak pernah mengharap agar diturunkan kepadamu Alkitab) yakni Alquran (tetapi) ia diturunkan kepadamu (karena suatu rahmat yang besar dari Rabbmu, sebab itu janganlah sekali-kali kamu menjadi penolong) pembantu (bagi orang-orang kafir) dalam agama mereka di mana mereka mengajak kamu untuk memasukinya.",[["وَمَا","Dan tidak"],["كُنتَ","kamu dahulu"],["تَرْجُوٓا۟","mengharapkan"],["أَن","bahawa"],["يُلْقَىٰٓ","akan diturunkan"],["إِلَيْكَ","kepada kamu"],["ٱلْكِتَـٰبُ","Kitab"],["إِلَّا","kecuali"],["رَحْمَةًۭ","(sebagai) rahmat"],["مِّن","daripada"],["رَّبِّكَ ۖ","Tuhanmu"],["فَلَا","Jadi (jangan)"],["تَكُونَنَّ","jadilah"],["ظَهِيرًۭا","seorang pembantu"],["لِّلْكَـٰفِرِينَ","kepada orang-orang kafir"]]],"3339":["(Dan janganlah sekali-kali mereka dapat menghalangimu) asal kata Yashuddunnaka adalah Yashuddunaka, kemudian huruf Nun alamat Rafa'nya dibuang karena lafal dijazamkan, demikian pula huruf Wawu Fa'il tetapi bukan karena bertemu dengan huruf mati lainnya (dari menyampaikan ayat-ayat Allah, sesudah ayat-ayat itu diturunkan kepadamu) maksudnya, janganlah kamu memandang mereka dalam hal tersebut (dan serulah) manusia (kepada jalan Rabbmu) dengan menganjurkan mereka untuk mengesakan-Nya dan menyembah-Nya (dan janganlah sekali-kali kamu termasuk orang-orang musyrik) yaitu, dengan membantu mereka. 'Amil Jazm tidak berpengaruh terhadap Fi'il yaitu lafal Wa La Takunanna, karena Fi'il ini bersifat Mabni, sebagai akibat kemasukan Nun Taukid.",[["وَلَا","Dan (jangan)"],["يَصُدُّنَّكَ","mengelak kamu"],["عَنْ","daripada"],["ءَايَـٰتِ","(the) Ayat"],["ٱللَّهِ","(milik) Allah"],["بَعْدَ","selepas"],["إِذْ","[apabila]"],["أُنزِلَتْ","mereka telah didedahkan"],["إِلَيْكَ ۖ","kepada kamu"],["وَٱدْعُ","Dan ajaklah (orang-orang)"],["إِلَىٰ","kepada"],["رَبِّكَ ۖ","Tuhanmu"],["وَلَا","Dan jangan"],["تَكُونَنَّ","jadilah"],["مِنَ","daripada"],["ٱلْمُشْرِكِينَ","orang musyrik"]]],"3340":["(Janganlah kamu seru) janganlah kamu sembah (di samping Allah, tuhan apa pun yang lain. Tidak ada Tuhan yang berhak disembah melainkan Dia. Tiap-tiap sesuatu pasti binasa, kecuali Dia) kecuali Allah. (Bagi-Nya-lah segala penentuan) yakni, keputusan yang terlaksana (dan hanya kepada-Nya-lah kalian dikembalikan) setelah kalian dibangkitkan dari kubur masing-masing.",[["وَلَا","Dan jangan"],["تَدْعُ","menyeru"],["مَعَ","dengan"],["ٱللَّهِ","Allah"],["إِلَـٰهًا","tuhan"],["ءَاخَرَ ۘ","lain"],["لَآ","(Ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","kecuali"],["هُوَ ۚ","Dia"],["كُلُّ","Setiap"],["شَىْءٍ","perkara"],["هَالِكٌ","(akan) musnah"],["إِلَّا","kecuali"],["وَجْهَهُۥ ۚ","Wajahnya"],["لَهُ","KepadaNya"],["ٱلْحُكْمُ","(ialah) Keputusan"],["وَإِلَيْهِ","dan kepada-Nya"],["تُرْجَعُونَ","kamu akan dikembalikan"]]],"3341":["(Alif Lam Mim) hanya Allah yang lebih mengetahui maksudnya.",[["الٓمٓ","Alif Laam Mim"]]],"3342":["(Apakah manusia itu mengira bahwa mereka dibiarkan saja mengatakan) mengenai ucapan mereka yang mengatakan, (\"Kami telah beriman\", sedangkan mereka tidak diuji lagi?) diuji lebih dulu dengan hal-hal yang akan menampakkan hakikat keimanan mereka. Ayat ini diturunkan berkenaan dengan orang-orang yang masuk Islam, kemudian mereka disiksa oleh orang-orang musyrik.",[["أَحَسِبَ","Fikirkanlah"],["ٱلنَّاسُ","manusia"],["أَن","bahawa"],["يُتْرَكُوٓا۟","mereka akan ditinggalkan"],["أَن","kerana"],["يَقُولُوٓا۟","mereka berkata"],["ءَامَنَّا","Kami beriman"],["وَهُمْ","dan mereka"],["لَا","tidak akan diuji"],["يُفْتَنُونَ","tidak akan diuji"]]],"3343":["(Dan sesungguhnya Kami telah menguji orang-orang yang sebelum mereka. Sesungguhnya Allah mengetahui orang-orang yang benar) di dalam keimanan mereka dengan pengetahuan yang menyaksikan (dan sesungguhnya Dia mengetahui orang-orang yang dusta) di dalam keimanannya.",[["وَلَقَدْ","Dan sesungguhnya"],["فَتَنَّا","Kami menguji"],["ٱلَّذِينَ","orang yang"],["مِن","(ada) sebelum mereka"],["قَبْلِهِمْ ۖ","(ada) sebelum mereka"],["فَلَيَعْلَمَنَّ","Dan Allah pasti akan menerangkan"],["ٱللَّهُ","Dan Allah pasti akan menerangkan"],["ٱلَّذِينَ","orang yang"],["صَدَقُوا۟","(adalah) benar"],["وَلَيَعْلَمَنَّ","dan Dia pasti akan nyata"],["ٱلْكَـٰذِبِينَ","pendusta"]]],"3344":["(Ataukah orang-orang yang mengerjakan kejahatan itu mengira) berupa perbuatan musyrik dan perbuatan maksiat (bahwa mereka akan luput dari Kami) maksudnya mereka dapat selamat sehingga Kami tidak membalas mereka (Amat buruklah) alangkah jeleknya (apa) yang (mereka putuskan) itu; seburuk-buruk keputusan adalah keputusan mereka.",[["أَمْ","Atau"],["حَسِبَ","fikir"],["ٱلَّذِينَ","orang yang"],["يَعْمَلُونَ","lakukan"],["ٱلسَّيِّـَٔاتِ","perbuatan jahat"],["أَن","bahawa"],["يَسْبِقُونَا ۚ","mereka boleh mengatasi Kami"],["سَآءَ","Jahat adalah"],["مَا","apa"],["يَحْكُمُونَ","mereka menilai"]]],"3345":["(Barang siapa yang mengharap) merasa takut (bertemu dengan Allah, maka sesungguhnya waktu Allah itu) yang dijanjikan-Nya (pasti datang) maka hendaknya dia bersiap sedia untuk itu. (Dan Dialah Yang Maha Mendengar) perkataan hamba-hamba-Nya (lagi Maha Mengetahui) perbuatan-perbuatan mereka.",[["مَن","Siapa pun"],["كَانَ","[adalah]"],["يَرْجُوا۟","harapan"],["لِقَآءَ","(untuk) mesyuarat"],["ٱللَّهِ","(dengan) Allah"],["فَإِنَّ","maka sesungguhnya"],["أَجَلَ","(the) Penggal"],["ٱللَّهِ","(milik) Allah"],["لَـَٔاتٍۢ ۚ","(ada) pasti datang"],["وَهُوَ","Dan Dia"],["ٱلسَّمِيعُ","(ialah) Yang Maha Mendengar"],["ٱلْعَلِيمُ","yang Maha Mengetahui"]]],"3346":["(Dan barang siapa yang berjihad) maksudnya jihad fisik atau jihad nafsi (maka sesungghnya jihadnya itu adalah untuk dirinya sendiri) karena manfaat atau pahala dari jihadnya itu kembali kepada dirinya sendiri, bukan kepada Allah. (Sesungguhnya Allah benar-benar Maha Kaya dari semesta alam) yaitu dari manusia, jin dan Malaikat, dalam arti kata Dia tidak memerlukan sesuatu pun dari mereka, juga Dia tidak membutuhkan ibadah mereka kepada-Nya.",[["وَمَن","Dan sesiapa"],["جَـٰهَدَ","berusaha"],["فَإِنَّمَا","kemudian sahaja"],["يُجَـٰهِدُ","dia berusaha"],["لِنَفْسِهِۦٓ ۚ","untuk dirinya sendiri"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَغَنِىٌّ","(adalah) Bebas daripada keperluan"],["عَنِ","daripada"],["ٱلْعَـٰلَمِينَ","dunia"]]],"3347":["(Orang-orang yang beriman dan beramal saleh, benar-benar akan Kami hapuskan dari mereka dosa-dosa mereka) melalui amal-amal saleh yang mereka lakukan (dan benar-benar akan Kami beri mereka balasan yang lebih baik) di-nashab-kannya lafal Ahsana karena huruf Jar-nya dibuang, makna yang dimaksud daripadanya ialah pahala yang baik (dari apa yang mereka kerjakan) yakni, dari amal-amal saleh mereka.",[["وَٱلَّذِينَ","Dan orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","benar (perbuatan)"],["لَنُكَفِّرَنَّ","nescaya Kami hapuskan"],["عَنْهُمْ","daripada mereka"],["سَيِّـَٔاتِهِمْ","perbuatan jahat mereka"],["وَلَنَجْزِيَنَّهُمْ","dan sesungguhnya Kami akan memberi balasan kepada mereka"],["أَحْسَنَ","(yang) terbaik"],["ٱلَّذِى","apa"],["كَانُوا۟","mereka gunakan"],["يَعْمَلُونَ","(untuk) melakukan"]]],"3348":["(Dan Kami perintahkan manusia berbuat kebaikan kepada dua orang ibu-bapaknya) artinya perintah untuk berbuat baik, antara lain berbakti kepada kedua ibu-bapak. (Dan jika keduanya memaksamu untuk mempersekutukan Aku dengan sesuatu yang tentang hal itu kamu) yakni terhadap perbuatan musyrik itu (tidak mempunyai pengetahuan) untuk menyetujui dan menentangnya, dan hal itu tidak dapat dimengerti olehmu (maka janganlah kamu mengikuti keduanya) dalam kemusyrikannya. (Hanya kepada-Ku-lah kembali kalian lalu Aku kabarkan kepada kalian apa yang telah kalian kerjakan) maka Aku akan membalasnya kepada kalian.",[["وَوَصَّيْنَا","Dan telah Kami perintahkan"],["ٱلْإِنسَـٰنَ","(pada) lelaki"],["بِوَٰلِدَيْهِ","kebaikan kepada ibu bapanya"],["حُسْنًۭا ۖ","kebaikan kepada ibu bapanya"],["وَإِن","tetapi jika"],["جَـٰهَدَاكَ","mereka berdua berjuang menentang kamu"],["لِتُشْرِكَ","untuk membuat kamu bergaul"],["بِى","dengan Aku"],["مَا","apa"],["لَيْسَ","tidak"],["لَكَ","kamu ada"],["بِهِۦ","daripadanya"],["عِلْمٌۭ","sebarang pengetahuan"],["فَلَا","maka (buat) jangan"],["تُطِعْهُمَآ ۚ","taat kepada mereka berdua"],["إِلَىَّ","Kepada Aku"],["مَرْجِعُكُمْ","(adalah) kamu kembali"],["فَأُنَبِّئُكُم","dan aku akan maklumkan kepada kamu"],["بِمَا","tentang apa"],["كُنتُمْ","kamu guna"],["تَعْمَلُونَ","(untuk) melakukan"]]],"3349":["(orang-orang yang beriman dan mengerjakan amal saleh, benar-benar Kami masukkan mereka ke dalam golongan orang-orang yang saleh) maksudnya para nabi dan kekasih-kekasih Allah, umpamanya Kami akan menghimpun mereka bersama-sama dengan para nabi dan para wali.",[["وَٱلَّذِينَ","Dan orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","amal soleh"],["لَنُدْخِلَنَّهُمْ","Kami pasti akan mengakui mereka"],["فِى","antara"],["ٱلصَّـٰلِحِينَ","orang yang soleh"]]],"3350":["(Di antara manusia ada orang yang berkata, \"Kami beriman kepada Allah\", maka apabila ia disakiti, -karena beriman- kepada Allah, ia menganggap fitnah manusia itu) yakni perlakuan mereka yang menyakitkan kepada dirinya (sebagai azab Allah) yaitu ketakutannya terhadap siksaan mereka disamakan seperti takut kepada azab Allah. Sehingga akhirnya dia mau menuruti kemauan mereka, lalu ia menjadi orang yang munafik. (Dan sungguh jika) huruf Lam pada lafal la in menunjukkan makna sumpah (datang pertolongan) kepada orang-orang Mukmin (dari Rabbmu) lalu orang-orang Mukmin memperoleh banyak ganimah (mereka pasti akan berkata) Lafal Layaqulunna dibuang daripadanya Nun alamat Rafa', karena jika dibiarkan, maka akan berturut-turutlah huruf Nun, sehingga jadilah Layaqulunna yang pada asalnya adalah Layaqulunanna, dan dibuang daripadanya Wawu Dhamir jamak bukan karena sebab bertemunya dua huruf yang disukunkan. (\"Sesungguhnya kami adalah beserta kalian\") dalam hal iman, karena itu maka ajaklah kami bersama-sama mendapat bagian ganimah itu. Maka Allah swt. berfirman (Bukankah Allah lebih mengetahui) yakni mengetahui (apa yang ada dalam dada semua manusia?) yakni apa yang ada di dalam hati mereka, apakah keimanan ataukah kemunafikan? Memang benar Allah lebih mengetahui.",[["وَمِنَ","Dan daripada"],["ٱلنَّاسِ","manusia"],["مَن","(adakah dia) siapa"],["يَقُولُ","berkata"],["ءَامَنَّا","Kami beriman"],["بِٱللَّهِ","kepada Allah"],["فَإِذَآ","Tetapi apabila"],["أُوذِىَ","dia dicederakan"],["فِى","dalam"],["ٱللَّهِ","(Jalan) Allah"],["جَعَلَ","dia menganggap"],["فِتْنَةَ","(perbicaraan)."],["ٱلنَّاسِ","(daripada) rakyat"],["كَعَذَابِ","sebagai hukuman"],["ٱللَّهِ","(milik) Allah"],["وَلَئِن","Tetapi jika"],["جَآءَ","datang"],["نَصْرٌۭ","kemenangan"],["مِّن","daripada"],["رَّبِّكَ","Tuhanmu"],["لَيَقُولُنَّ","pasti mereka berkata"],["إِنَّا","Sesungguhnya kami"],["كُنَّا","adalah"],["مَعَكُمْ ۚ","bersama kamu"],["أَوَلَيْسَ","bukan"],["ٱللَّهُ","Allah"],["بِأَعْلَمَ","paling mengetahui"],["بِمَا","tentang apa"],["فِى","(berada) dalam"],["صُدُورِ","(the) buah dada"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"3351":["(Dan sesungguhnya Allah benar-benar mengetahui orang-orang yang beriman) maksudnya mengenai hati mereka (dan sesungguhnya Dia mengetahui orang-orang yang munafik) maka kelak Dia akan membalas masing-masing golongan itu. Lam yang terdapat pada kedua Fi'il ayat ini menunjukkan makna Qasam.",[["وَلَيَعْلَمَنَّ","Dan Allah pasti akan menerangkan"],["ٱللَّهُ","Dan Allah pasti akan menerangkan"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَلَيَعْلَمَنَّ","Dan Dia pasti akan nyata"],["ٱلْمُنَـٰفِقِينَ","golongan munafik"]]],"3352":["(Dan berkatalah orang-orang kafir kepada orang-orang yang beriman, \"Ikutilah jalan kami) maksudnya cara mereka dalam beragama (dan nanti kami akan memikul dosa-dosa kalian\") karena kalian menuruti kami jika memang kalian berdosa. Lafal Amar sekali pun sebagai kalimat Insya' akan tetapi menunjukkan makna Khabar atau kalimat berita. Maka Allah berfirman (dan mereka sendiri sedikit pun tidak sanggup memikul dosa-dosa mereka. Sesungguhnya mereka adalah benar-benar pendusta) dalam perkataannya itu.",[["وَقَالَ","Dan berkata"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["لِلَّذِينَ","kepada mereka yang"],["ءَامَنُوا۟","beriman"],["ٱتَّبِعُوا۟","Ikut"],["سَبِيلَنَا","cara kita"],["وَلْنَحْمِلْ","dan kami akan bawa"],["خَطَـٰيَـٰكُمْ","dosa kamu"],["وَمَا","Tetapi tidak"],["هُم","mereka"],["بِحَـٰمِلِينَ","(akan) akan membawa"],["مِنْ","daripada"],["خَطَـٰيَـٰهُم","dosa mereka"],["مِّن","sebarang"],["شَىْءٍ ۖ","perkara"],["إِنَّهُمْ","Sesungguhnya mereka"],["لَكَـٰذِبُونَ","(adalah) sesungguhnya pendusta"]]],"3353":["(Dan sesungguhnya mereka akan memikul beban mereka) dosa-dosa mereka (dan beban-beban dosa yang lain di samping beban-beban dasa mereka sendiri) disebabkan perkataan mereka kepada orang-orang yang beriman, sebagaimana yang diungkapkan oleh firman-Nya tadi, yaitu, \"Ikutilah jalan kami\", dan juga disebabkan penyesatan yang mereka lakukan kepada orang-orang yang mengikuti mereka (dan sesungguhnya mereka akan ditanya pada hari kiamat tentang apa-apa yang selalu mereka ada-adakan) yakni kedustaan mereka terhadap Allah. Pertanyaan ini menunjukkan nada celaan, dan huruf Lam yang terdapat pada kedua Fi'il tadi menunjukkan makna Qasam, sedangkan Fa'il masing-masing yaitu berupa Wau Dhamir Jamak dibuang, dan demikian pula huruf Nun alamat Rafa'nya.",[["وَلَيَحْمِلُنَّ","Tetapi pasti mereka akan membawa"],["أَثْقَالَهُمْ","bebanan mereka"],["وَأَثْقَالًۭا","dan bebanan"],["مَّعَ","dengan"],["أَثْقَالِهِمْ ۖ","bebanan mereka"],["وَلَيُسْـَٔلُنَّ","dan sesungguhnya mereka akan ditanya"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["عَمَّا","tentang apa"],["كَانُوا۟","mereka gunakan"],["يَفْتَرُونَ","(untuk) mencipta"]]],"3354":["(Dan sesungguhnya Kami telah mengutus Nuh kepada kaumnya) sewaktu Nabi Nuh diangkat menjadi Rasul ia berumur empat puluh tahun atau lebih dari itu (maka ia tinggal di antara mereka selama sembilan ratus lima puluh tahun) seraya menyeru mereka untuk mentauhidkan Allah, tetapi mereka yakni kaumnya, tetap mendustakannya. (Maka mereka ditimpa banjir besar) yaitu, air bah yang sangat tinggi sehingga tenggelamlah mereka semuanya (dan mereka adalah orang-orang yang zalim) maksudnya adalah orang-orang yang menyekutukan Allah.",[["وَلَقَدْ","Dan sesungguhnya"],["أَرْسَلْنَا","Kami utus"],["نُوحًا","Nuh"],["إِلَىٰ","kepada"],["قَوْمِهِۦ","umatnya"],["فَلَبِثَ","dan dia kekal"],["فِيهِمْ","antara mereka"],["أَلْفَ","seribu"],["سَنَةٍ","tahun"],["إِلَّا","jimat"],["خَمْسِينَ","lima puluh"],["عَامًۭا","tahun"],["فَأَخَذَهُمُ","kemudian menangkap mereka"],["ٱلطُّوفَانُ","banjir"],["وَهُمْ","sedangkan mereka"],["ظَـٰلِمُونَ","(adalah) orang-orang yang zalim"]]],"3355":["(Maka Kami selamatkan dia) Nabi Nuh (dan penumpang-penumpang bahtera itu) yang bersama Nabi Nuh di dalam bahtera (dan Kami jadikan peristiwa itu tanda) pelajaran (bagi semua umat manusia) yang datang sesudah mereka, jika mereka berbuat durhaka kepada Rasul-rasul mereka. Setelah peristiwa banjir besar itu Nabi Nuh hidup selama enam puluh tahun atau lebih, sehingga jumlah manusia menjadi banyak.",[["فَأَنجَيْنَـٰهُ","Tetapi Kami selamatkan dia"],["وَأَصْحَـٰبَ","dan (orang-orang) itu"],["ٱلسَّفِينَةِ","(dari) kapal itu"],["وَجَعَلْنَـٰهَآ","dan Kami membuatnya"],["ءَايَةًۭ","sebuah Tanda"],["لِّلْعَـٰلَمِينَ","untuk dunia"]]],"3356":["(Dan) ingatlah (Ibrahim ketika ia berkata kepada kaumnya, \"Sembahlah Allah dan bertakwalah kalian kepada-Nya!) takutlah kalian akan azab dan hukuman-Nya. (Demikian itu lebih baik bagi kalian) daripada apa yang sekarang kalian kerjakan yaitu menyembah berhala (jika kalian mengetahui) mana yang baik dan mana yang tidak baik.",[["وَإِبْرَٰهِيمَ","Dan Ibrahim"],["إِذْ","apabila"],["قَالَ","dia berkata"],["لِقَوْمِهِ","kepada umatnya"],["ٱعْبُدُوا۟","Ibadah"],["ٱللَّهَ","Allah"],["وَٱتَّقُوهُ ۖ","dan takut kepada-Nya"],["ذَٰلِكُمْ","Itu"],["خَيْرٌۭ","(lebih) baik"],["لَّكُمْ","bagi kamu"],["إِن","jika"],["كُنتُمْ","kamu"],["تَعْلَمُونَ","mengetahui"]]],"3357":["(Sesungguhnya apa yang kalian sembah selain Allah itu) (adalah berhala-berhala, dan kalian membuat dusta) kalian mengatakan kebohongan, bahwa berhala-berhala itu adalah sekutu-sekutu Allah. (Sesungguhnya yang kalian. sembah selain Allah itu tidak mampu memberikan rezeki kepada kalian) maksudnya mereka tidak akan mampu memberi rezeki kepada kalian (maka mintalah rezeki di sisi Allah) yakni mintalah rezeki itu kepada-Nya (dan sembahlah Dia dan bersyukurlah kepada-Nya. Hanya kepada-Nya-lah kalian akan dikembalikan).",[["إِنَّمَا","Hanya"],["تَعْبُدُونَ","kamu menyembah"],["مِن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["أَوْثَـٰنًۭا","berhala"],["وَتَخْلُقُونَ","dan kamu mencipta"],["إِفْكًا ۚ","kepalsuan"],["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","mereka yang"],["تَعْبُدُونَ","kamu menyembah"],["مِن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["لَا","jangan"],["يَمْلِكُونَ","memiliki"],["لَكُمْ","bagi kamu"],["رِزْقًۭا","sebarang peruntukan"],["فَٱبْتَغُوا۟","Jadi carilah"],["عِندَ","daripada"],["ٱللَّهِ","Allah"],["ٱلرِّزْقَ","peruntukan itu"],["وَٱعْبُدُوهُ","dan menyembah Dia"],["وَٱشْكُرُوا۟","dan bersyukurlah"],["لَهُۥٓ ۖ","kepada-Nya"],["إِلَيْهِ","KepadaNya"],["تُرْجَعُونَ","kamu akan dikembalikan"]]],"3358":["(Dan jika kalian mendustakan) aku, hai penduduk Mekah (maka umat sebelum kalian juga telah mendustakan) umat-umat sebelumku. (Dan kewajiban Rasul itu tidak lain hanyalah menyampaikan agama Allah dengan seterang-terangnya\") dengan penyampaian yang sejelas-jelasnya. Pada kedua kisah ini terkandung makna yang dapat menghibur hati Nabi saw. dan Allah berfirman kepada kaumnya,",[["وَإِن","Dan jika"],["تُكَذِّبُوا۟","kamu nafikan"],["فَقَدْ","maka sesungguhnya"],["كَذَّبَ","dinafikan"],["أُمَمٌۭ","(the) negara"],["مِّن","sebelum kamu"],["قَبْلِكُمْ ۖ","sebelum kamu"],["وَمَا","Dan tidak"],["عَلَى","(berada) di atas"],["ٱلرَّسُولِ","Rasul"],["إِلَّا","kecuali"],["ٱلْبَلَـٰغُ","pengangkutan itu"],["ٱلْمُبِينُ","yang nyata"]]],"3359":["(Dan apakah mereka tidak memperhatikan) dapat dibaca Yarau dan Tarau, artinya memikirkan (bagaimana Allah menciptakan manusia dari permulaannya) lafal Yubdi-u menurut suatu qiraat dibaca Yabda-u berasal dari Bada-a, makna yang dimaksud bagaimana Allah menciptakan mereka dari permulaan (kemudian) Dia (mengulanginya kembali) maksudnya mengulangi penciptaan-Nya kembali sebagaimana permulaan Dia menciptakan mereka. (Sesungguhnya yang demikian itu) yaitu hal yang telah disebutkan mengenai penciptaan pertama dan penciptaan kedua (adalah mudah bagi Allah) dan kenapa mereka mengingkari adanya penciptaan yang kedua itu; yang dimaksud adalah hari berbangkit.",[["أَوَلَمْ","Jangan"],["يَرَوْا۟","mereka lihat"],["كَيْفَ","bagaimana"],["يُبْدِئُ","Allah berasal"],["ٱللَّهُ","Allah berasal"],["ٱلْخَلْقَ","penciptaan"],["ثُمَّ","kemudian"],["يُعِيدُهُۥٓ ۚ","mengulanginya"],["إِنَّ","Sesungguhnya"],["ذَٰلِكَ","bahawa"],["عَلَى","bagi"],["ٱللَّهِ","Allah"],["يَسِيرٌۭ","(adalah) mudah"]]],"3360":["(Katakanlah, \"Berjalanlah kalian di muka bumi, maka perhatikanlah bagaimana Allah memulai penciptaan-Nya) yakni menciptakan orang-orang yang sebelum kalian, kemudian Dia mematikan mereka (lalu Allah menjadikannya sekali lagi) dapat dibaca An Nasy-atal akhirata dan An Nasy-atal ukhra. (Sesungguhnya Allah Maha Kuasa atas segala sesuatu) antara lain ialah memulai dan mengulanginya.",[["قُلْ","Katakanlah"],["سِيرُوا۟","Perjalanan"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["فَٱنظُرُوا۟","dan lihat"],["كَيْفَ","bagaimana"],["بَدَأَ","Dia berasal"],["ٱلْخَلْقَ ۚ","penciptaan"],["ثُمَّ","Kemudian"],["ٱللَّهُ","Allah"],["يُنشِئُ","akan menghasilkan"],["ٱلنَّشْأَةَ","penciptaan"],["ٱلْـَٔاخِرَةَ ۚ","yang terakhir"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["عَلَىٰ","pada"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌۭ","(adalah) Maha Kuasa"]]],"3361":["(Allah mengazab siapa yang dikehendaki-Nya) menerima azab-Nya (dan memberi rahmat kepada siapa yang dikehendaki-Nya) untuk menerima rahmat-Nya (dan hanya kepada-Nya-lah kalian akan dikembalikan) yakni, hanya kepada-Nya-lah kalian kembali.",[["يُعَذِّبُ","Dia menghukum"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["وَيَرْحَمُ","dan mempunyai belas kasihan"],["مَن","(pada) siapa"],["يَشَآءُ ۖ","Dia kehendaki"],["وَإِلَيْهِ","dan kepada-Nya"],["تُقْلَبُونَ","kamu akan dikembalikan"]]],"3362":["(Dan kalian sekali-kali tidak dapat melepaskan diri) dari jangkauan kekuasaan Rabb kalian (di bumi dan tidak pula di langit) jika kalian berada padanya; makna yang dimaksud ialah bahwa kalian tidak akan dapat terlepas daripada-Nya di mana pun kalian berada (dan sekali-kali tiadalah bagi kalian seorang pelindung pun selain dari Allah) yang dapat mencegah azab-Nya atas kalian (dan tidak pula seorang penolong) yang dapat menolong kalian dari azab-Nya.",[["وَمَآ","Dan tidak"],["أَنتُم","kamu"],["بِمُعْجِزِينَ","boleh melarikan diri"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَلَا","dan bukan"],["فِى","dalam"],["ٱلسَّمَآءِ ۖ","syurga itu"],["وَمَا","Dan tidak"],["لَكُم","bagi kamu"],["مِّن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["مِن","sebarang"],["وَلِىٍّۢ","pelindung"],["وَلَا","dan bukan"],["نَصِيرٍۢ","seorang penolong"]]],"3363":["(Orang-orang yang kafir kepada ayat-ayat Allah dan pertemuan dengan Dia) tidak percaya pada Alquran dan adanya hari berbangkit (mereka putus asa dari rahmat-Ku) surga-Ku (dan mereka itu mendapat azab yang pedih) yakni azab yang menyakitkan.",[["وَٱلَّذِينَ","Dan orang yang"],["كَفَرُوا۟","kufur"],["بِـَٔايَـٰتِ","dalam (the) Tanda-tanda"],["ٱللَّهِ","(milik) Allah"],["وَلِقَآئِهِۦٓ","dan pertemuan (dengan)Nya"],["أُو۟لَـٰٓئِكَ","mereka"],["يَئِسُوا۟","(telah) putus asa"],["مِن","daripada"],["رَّحْمَتِى","Kerahiman-Ku"],["وَأُو۟لَـٰٓئِكَ","Dan mereka"],["لَهُمْ","bagi mereka"],["عَذَابٌ","(ialah) azab"],["أَلِيمٌۭ","yang pedih"]]],"3364":["Allah berfirman sehubungan dengan kisah Nabi Ibrahim a.s.: (Maka tiadalah jawaban kaumnya selain mengatakan, \"Bunuhlah atau bakarlah dia,\" lalu Allah menyelamatkannya dari api) mereka melemparkannya ke dalam api, sedangkan Allah menjadikan api itu dingin dan keselamatan bagi Ibrahim. (Sesungguhnya pada yang demikian itu) yakni diselamatkannya Nabi Ibrahim dari api (benar-benar terdapat tanda-tanda kebesaran Allah) yaitu tidak berpengaruhnya api terhadap diri Nabi Ibrahim, padahal api itu sangat besar nyalanya, kemudian dalam waktu yang sangat singkat Allah menjadikan bekas api itu sebuah taman (bagi orang-orang yang beriman) yakni bagi orang-orang yang percaya kepada keesaan Allah dan kekuasaan-Nya, karena hanya mereka saja yang dapat mengambil manfaat dari kisah ini.",[["فَمَا","Dan tidak"],["كَانَ","adalah"],["جَوَابَ","(the) jawapan"],["قَوْمِهِۦٓ","(dari) kaumnya"],["إِلَّآ","kecuali"],["أَن","bahawa"],["قَالُوا۟","mereka berkata"],["ٱقْتُلُوهُ","Bunuh dia"],["أَوْ","atau"],["حَرِّقُوهُ","bakar dia"],["فَأَنجَىٰهُ","Tetapi Allah menyelamatkannya"],["ٱللَّهُ","Tetapi Allah menyelamatkannya"],["مِنَ","daripada"],["ٱلنَّارِ ۚ","api"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَـٰتٍۢ","sesungguhnya (adalah) tanda-tanda"],["لِّقَوْمٍۢ","bagi kaum"],["يُؤْمِنُونَ","yang beriman"]]],"3365":["(Dan berkatalah dia) Nabi Ibrahim (\"Sesungguhnya berhala-berhala yang kalian sembah selain Allah) huruf ma adalah mashdariyyah (adalah untuk menciptakan perasaan kasih sayang di antara kalian) lafal ayat ini adalah khabar dari inna. Tetapi menurut qiraat yang lain dibaca nashab sehingga menjadi mawaddatan sebagai maf`ul lah, sedangkan huruf maa tadi dianggap sebagai maa kaffah, yakni yang mencegah beramalnya inna. Maksudnya, kalian menjadikan penyembahan kepada berhala-berhala itu sebagai sarana untuk memelihara kasih sayang di antara kalian (dalam kehidupan dunia ini, kemudian di hari kiamat sebagian kalian mengingkari sebagian yang lain) yakni para pemimpin penyembah berhala itu cuci tangan dari apa yang dilakukan oleh para pengikutnya (dan sebagian kalian mengutuk sebagian yang lain) yakni para pengikut mengutuk para pemimpin mereka (dan tempat kembali kalian) semuanya (ialah neraka, dan sekali-kali tak ada bagi kalian para penolong pun.\") yang dapat mencegah kalian dari masuk neraka.",[["وَقَالَ","Dan dia berkata"],["إِنَّمَا","Hanya"],["ٱتَّخَذْتُم","kamu telah mengambil"],["مِّن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["أَوْثَـٰنًۭا","berhala"],["مَّوَدَّةَ","(kerana) cinta"],["بَيْنِكُمْ","antara kamu"],["فِى","dalam"],["ٱلْحَيَوٰةِ","kehidupan"],["ٱلدُّنْيَا ۖ","dunia"],["ثُمَّ","Kemudian"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["يَكْفُرُ","kamu akan menafikan"],["بَعْضُكُم","satu sama lain"],["بِبَعْضٍۢ","satu sama lain"],["وَيَلْعَنُ","dan kutuk"],["بَعْضُكُم","satu sama lain"],["بَعْضًۭا","satu sama lain"],["وَمَأْوَىٰكُمُ","dan tempat tinggal kamu"],["ٱلنَّارُ","(akan menjadi) Neraka"],["وَمَا","dan bukan"],["لَكُم","bagi kamu"],["مِّن","sebarang"],["نَّـٰصِرِينَ","pembantu"]]],"3366":["(Maka berimanlah kepadanya) percayalah kepada Nabi Ibrahim (Luth) ia adalah anak saudara lelaki Nabi Ibrahim bernama Haran. (Dan berkatalah dia) Nabi Ibrahim: (\"Sesungguhnya aku akan berpindah\") dari kaumku (kepada Rabbku) yaitu akan berpindah ke tempat yang diperintahkan oleh Rabbku, kemudian Nabi Ibrahim meninggalkan kaumnya dari pedalaman negeri Irak menuju ke negeri Syam. (Sesungguhnya Dialah Yang Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Bijaksana) dalam perbuatan-Nya.",[["۞ فَـَٔامَنَ","Dan beriman"],["لَهُۥ","[dalam] dia"],["لُوطٌۭ ۘ","Lut"],["وَقَالَ","dan dia berkata"],["إِنِّى","Sesungguhnya aku (adalah)"],["مُهَاجِرٌ","berhijrah"],["إِلَىٰ","kepada"],["رَبِّىٓ ۖ","Tuhanku"],["إِنَّهُۥ","Sesungguhnya Dia"],["هُوَ","[Dia] (adalah)"],["ٱلْعَزِيزُ","Yang Maha Perkasa"],["ٱلْحَكِيمُ","Yang Maha Bijaksana"]]],"3367":["(Dan Kami anugerahkan kepada Ibrahim) setelah berputra Ismail (Ishak dan Yakub) Yakub lahir sesudah Ishak (dan Kami jadikan pada keturunannya kenabian) semua nabi sesudah Nabi Ibrahim terdiri dari keturunannya (dan Alkitab) sekalipun lafal Alkitab bentuknya mufrad atau tunggal, tetapi makna yang dimaksud adalah jamak yaitu kitab Taurat, Injil, Zabur dan Alquran (dan Kami berikan kepadanya balasannya di dunia) yaitu dia menjadi buah tutur yang baik di kalangan para pemeluk setiap agama (dan sesungguhnya dia di akhirat benar-benar termasuk orang-orang yang saleh) yakni orang-orang yang mempunyai kedudukan yang tinggi di akhirat.",[["وَوَهَبْنَا","Dan Kami kabulkan"],["لَهُۥٓ","kepadanya"],["إِسْحَـٰقَ","Ishak"],["وَيَعْقُوبَ","dan Yaqub"],["وَجَعَلْنَا","dan Kami letakkan"],["فِى","dalam"],["ذُرِّيَّتِهِ","keturunannya"],["ٱلنُّبُوَّةَ","kenabian"],["وَٱلْكِتَـٰبَ","dan Kitab"],["وَءَاتَيْنَـٰهُ","Dan Kami berikan kepadanya"],["أَجْرَهُۥ","pahalanya"],["فِى","dalam"],["ٱلدُّنْيَا ۖ","dunia"],["وَإِنَّهُۥ","Dan sesungguhnya, dia"],["فِى","dalam"],["ٱلْـَٔاخِرَةِ","akhirat"],["لَمِنَ","(adalah) pasti, antara"],["ٱلصَّـٰلِحِينَ","orang yang soleh"]]],"3368":["(Dan) ingatlah (ketika Luth berkata kepada kaumnya, \"Sesungguhnya kalian) inna dapat dibaca tahqiq dan tashil (benar-benar mengerjakan perbuatan yang amat keji) yakni mendatangi dubur laki-laki/homosex (yang belum pernah dikerjakan oleh seorang pun dari umat-umat sebelum kalian.\") baik oleh manusia maupun jin.",[["وَلُوطًا","Dan Lut"],["إِذْ","apabila"],["قَالَ","dia berkata"],["لِقَوْمِهِۦٓ","kepada umatnya"],["إِنَّكُمْ","Sesungguhnya kamu"],["لَتَأْتُونَ","komited"],["ٱلْفَـٰحِشَةَ","maksiat itu"],["مَا","tidak"],["سَبَقَكُم","telah mendahului kamu"],["بِهَا","dengannya"],["مِنْ","sebarang"],["أَحَدٍۢ","satu"],["مِّنَ","daripada"],["ٱلْعَـٰلَمِينَ","dunia"]]],"3369":["(Apakah sesungguhnya kalian patut mendatangi laki-laki, menyamun) orang-orang yang lewat di tempat kalian, kemudian kalian melakukan perbuatan keji terhadapnya di tempat kalian, sehingga orang-orang tidak mau lagi lewat di jalan kalian (dan kalian mengerjakan di tempat-tempat pertemuan kalian) yakni tempat kalian berkumpul (perbuatan kemungkaran) yakni sebagian kalian melakukan perbuatan keji dengan sebagian yang lain. (Maka jawaban kaumnya tidak lain hanya mengatakan, \"Datangkanlah kepada kami azab Allah, jika kamu termasuk orang-orang yang benar.\") menganggap keji perbuatan ini, dan bahwasanya azab akan menimpa atas para pelakunya.",[["أَئِنَّكُمْ","Sesungguhnya kamu"],["لَتَأْتُونَ","pendekatan"],["ٱلرِّجَالَ","kaum lelaki"],["وَتَقْطَعُونَ","dan kamu memotong"],["ٱلسَّبِيلَ","jalan raya"],["وَتَأْتُونَ","dan komited"],["فِى","dalam"],["نَادِيكُمُ","mesyuarat kamu"],["ٱلْمُنكَرَ ۖ","jahat"],["فَمَا","Dan tidak"],["كَانَ","adalah"],["جَوَابَ","(the) jawapan"],["قَوْمِهِۦٓ","(dari) kaumnya"],["إِلَّآ","kecuali"],["أَن","bahawa"],["قَالُوا۟","mereka berkata"],["ٱئْتِنَا","Bawa kepada kami"],["بِعَذَابِ","azab"],["ٱللَّهِ","(milik) Allah"],["إِن","jika"],["كُنتَ","kamu"],["مِنَ","daripada"],["ٱلصَّـٰدِقِينَ","yang benar"]]],"3370":["(Luth berdoa, \"Ya Rabbku, tolonglah aku) dengan membuktikan apa yang telah aku katakan kepada mereka, yaitu menurunkan azab (atas kaum yang berbuat kerusakan itu.\") Maksudnya mereka yang durhaka karena melakukan homosex, Allah memperkenankan doa Nabi Luth.",[["قَالَ","Dia berkata"],["رَبِّ","Tuhanku"],["ٱنصُرْنِى","Tolong aku"],["عَلَى","terhadap"],["ٱلْقَوْمِ","manusia"],["ٱلْمُفْسِدِينَ","para perasuah"]]],"3371":["(Dan tatkala utusan Kami/para malaikat datang kepada Ibrahim membawa kabar gembira) mengenai akan lahirnya Ishak dan Yakub sesudahnya (mereka mengatakan, \"Sesungguhnya kami akan menghancurkan penduduk negeri ini) yang ditempati oleh kaum Nabi Luth (sesungguhnya penduduknya adalah orang-orang yang lalim.\") yakni orang-orang yang kafir.",[["وَلَمَّا","Dan apabila"],["جَآءَتْ","datang"],["رُسُلُنَآ","utusan kami"],["إِبْرَٰهِيمَ","(kepada) Ibrahim"],["بِٱلْبُشْرَىٰ","dengan berita gembira"],["قَالُوٓا۟","mereka berkata"],["إِنَّا","Sesungguhnya kami"],["مُهْلِكُوٓا۟","(akan) akan memusnahkan"],["أَهْلِ","kaum"],["هَـٰذِهِ","(dari) ini"],["ٱلْقَرْيَةِ ۖ","bandar"],["إِنَّ","Sesungguhnya"],["أَهْلَهَا","rakyatnya"],["كَانُوا۟","adalah"],["ظَـٰلِمِينَ","orang yang zalim"]]],"3372":["(Berkata dia) Ibrahim (\"Sesungguhnya di kota itu ada Luth.\" Mereka berkata) para Malaikat itu berkata: (\"Kami lebih mengetahui siapa yang ada di kota itu, Kami sungguh-sungguh akan menyelamatkan dia) lanunajjiyannahu dapat dibaca secara takhfif yaitu lanunjiyannahu, dapat pula dibaca tasydid, yaitu lanunajjiyannahu (beserta pengikut-pengikutnya kecuali istrinya. Dia adalah termasuk orang-orang yang tertinggal.\") termasuk orang-orang yang dibinasakan.",[["قَالَ","Dia berkata"],["إِنَّ","Sesungguhnya"],["فِيهَا","di dalamnya"],["لُوطًۭا ۚ","(ialah) Lut"],["قَالُوا۟","Mereka berkata"],["نَحْنُ","Kami"],["أَعْلَمُ","lebih tahu"],["بِمَن","yang"],["فِيهَا ۖ","(ada) di dalamnya"],["لَنُنَجِّيَنَّهُۥ","Kami pasti akan menyelamatkannya"],["وَأَهْلَهُۥٓ","dan keluarganya"],["إِلَّا","kecuali"],["ٱمْرَأَتَهُۥ","isterinya"],["كَانَتْ","dia"],["مِنَ","(adalah) daripada"],["ٱلْغَـٰبِرِينَ","mereka yang tinggal di belakang"]]],"3373":["(Dan tatkala datang utusan-utusan Kami itu kepada Luth, dia merasa susah karena kedatangan mereka) dia merasa susah disebabkan adanya mereka (dan merasa tidak mempunyai kekuatan untuk melindungi mereka) karena mereka memiliki wajah-wajah tampan, mereka menyamar sebagai tamu Nabi Luth. Nabi Luth merasa takut kaumnya akan melakukan hal-hal yang tidak diinginkan terhadap tamu-tamunya, maka para utusan itu memberitahukan kepadanya, bahwa mereka adalah utusan dari Rabbnya (dan mereka berkata, \"Janganlah kamu takut dan jangan pula susah. Sesungguhnya kami akan menyelamatkan kamu) dapat dibaca munajjuuka dan munjuuka (dan pengikut-pengikutmu kecuali istrimu, dia adalah termasuk orang-orang yang tertinggal\") dinashabkannya lafal ahlaka karena diathafkan secara mahal kepada huruf kaf yang ada pada lafal munajjuuka.",[["وَلَمَّآ","Dan apabila"],["أَن","[bahawa]"],["جَآءَتْ","datang"],["رُسُلُنَا","utusan kami"],["لُوطًۭا","(kepada) Lut"],["سِىٓءَ","dia tertekan"],["بِهِمْ","bagi mereka"],["وَضَاقَ","dan berasa tertekan"],["بِهِمْ","bagi mereka"],["ذَرْعًۭا","(dan) gelisah"],["وَقَالُوا۟","Dan mereka berkata"],["لَا","Jangan"],["تَخَفْ","bertakwa"],["وَلَا","dan jangan"],["تَحْزَنْ ۖ","bersedih"],["إِنَّا","Sesungguhnya kami"],["مُنَجُّوكَ","(akan) menyelamatkan kamu"],["وَأَهْلَكَ","dan keluarga kamu"],["إِلَّا","kecuali"],["ٱمْرَأَتَكَ","isteri kamu"],["كَانَتْ","dia"],["مِنَ","(adalah) daripada"],["ٱلْغَـٰبِرِينَ","mereka yang tinggal di belakang"]]],"3374":["(Sesungguhnya Kami akan menurunkan) dapat dibaca munziluuna dan munazziluuna (azab atas penduduk kota ini) yakni siksaan (dari langit karena) perbuatan (kefasikan yang mereka kerjakan) disebabkan kefasikan mereka.",[["إِنَّا","Sesungguhnya kami"],["مُنزِلُونَ","(akan) menjatuhkan"],["عَلَىٰٓ","pada"],["أَهْلِ","kaum"],["هَـٰذِهِ","(dari) ini"],["ٱلْقَرْيَةِ","bandar"],["رِجْزًۭا","azab"],["مِّنَ","daripada"],["ٱلسَّمَآءِ","(langit)."],["بِمَا","kerana"],["كَانُوا۟","mereka telah"],["يَفْسُقُونَ","membangkang menderhaka"]]],"3375":["(Dan sesungguhnya Kami tinggalkan daripadanya satu tanda yang nyata) yang jelas, yaitu berupa bekas-bekas kehancuran mereka (bagi orang-orang yang berakal) bagi mereka yang mau berpikir.",[["وَلَقَد","Dan sesungguhnya"],["تَّرَكْنَا","Kami telah pergi"],["مِنْهَآ","mengenainya"],["ءَايَةًۢ","satu tanda"],["بَيِّنَةًۭ","(sebagai) bukti"],["لِّقَوْمٍۢ","bagi kaum"],["يَعْقِلُونَ","yang menggunakan akal"]]],"3376":["(Dan) Kami utus (kepada penduduk Madyan saudara mereka Syuaib, maka ia berkata, \"Hai kaumku! Sembahlah oleh kalian Allah, harapkanlah pahala hari akhir) maksudnya takutlah kalian akan hari itu, yaitu hari kiamat (dan janganlah kalian berkeliaran di muka bumi berbuat kerusakan.\") Lafal mufsidiina berkedudukan sebagai hal atau kata keterangan keadaan yang mengukuhkan makna 'amilnya. Lafal ta'tsau berasal dari lafal 'atsiya yang artinya membuat kerusakan.",[["وَإِلَىٰ","Dan kepada"],["مَدْيَنَ","Madyan"],["أَخَاهُمْ","abang mereka"],["شُعَيْبًۭا","Shuaib"],["فَقَالَ","Dan dia berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["ٱعْبُدُوا۟","Ibadah"],["ٱللَّهَ","Allah"],["وَٱرْجُوا۟","dan mengharapkan"],["ٱلْيَوْمَ","Hari itu"],["ٱلْـَٔاخِرَ","yang Terakhir"],["وَلَا","dan jangan"],["تَعْثَوْا۟","melakukan kejahatan"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["مُفْسِدِينَ","(sebagai) perasuah"]]],"3377":["(Maka mereka mendustakan Syuaib, lalu mereka ditimpa gempa yang dahsyat) gempa yang sangat kuat goncangannya (dan jadilah mereka mayit-mayit yang bergelimpangan di rumah-rumah mereka) yakni mereka mati dalam keadaan terduduk di atas lutut mereka di tempat tinggal masing-masing.",[["فَكَذَّبُوهُ","Tetapi mereka menafikannya"],["فَأَخَذَتْهُمُ","jadi merampas mereka"],["ٱلرَّجْفَةُ","gempa bumi"],["فَأَصْبَحُوا۟","dan mereka menjadi"],["فِى","dalam"],["دَارِهِمْ","rumah mereka"],["جَـٰثِمِينَ","jatuh tersungkur"]]],"3378":["(Dan) Kami binasakan (kaum Ad dan Tsamud) lafal tsamuuda dapat pula dibaca tsamuudan dengan memakai harakat tanwin, maksudnya adalah nama kabilah (dan sungguh telah nyata bagi kalian) kebinasaan mereka (dari puing-puing tempat tinggal mereka) di daerah Al-Hijr dan negeri Yaman. (Dan setan menjadikan mereka memandang baik perbuatan-perbuatan mereka) seperti kekafiran dan kemaksiatan (lalu ia menghalangi mereka dari jalan) yang benar (sedangkan mereka adalah orang-orang yang berpandangan tajam) yakni memiliki pandangan tentang perkara hak itu tetapi mereka tidak mau mengikutinya.",[["وَعَادًۭا","Dan Aad"],["وَثَمُودَا۟","dan kaum Thamud"],["وَقَد","dan sesungguhnya"],["تَّبَيَّنَ","(telah) menjadi jelas"],["لَكُم","kepada kamu"],["مِّن","daripada"],["مَّسَـٰكِنِهِمْ ۖ","kediaman mereka"],["وَزَيَّنَ","Dan dibuat kelihatan adil"],["لَهُمُ","kepada mereka"],["ٱلشَّيْطَـٰنُ","syaitan"],["أَعْمَـٰلَهُمْ","perbuatan mereka"],["فَصَدَّهُمْ","dan mengelak mereka"],["عَنِ","daripada"],["ٱلسَّبِيلِ","Jalan"],["وَكَانُوا۟","walaupun mereka"],["مُسْتَبْصِرِينَ","dikurniakan wawasan"]]],"3379":["(Dan) telah Kami binasakan pula (Qarun, Firaun dan Haman. Dan sesungguhnya telah datang kepada mereka) sebelumnya (Musa dengan membawa keterangan-keterangan yang nyata) hujah-hujah yang jelas dan gamblang. (Akan tetapi mereka berlaku sombong di muka bumi dan tiadalah mereka orang-orang yang luput) dari azab Kami.",[["وَقَـٰرُونَ","Dan Qarun"],["وَفِرْعَوْنَ","dan Firaun"],["وَهَـٰمَـٰنَ ۖ","dan Haman"],["وَلَقَدْ","Dan sungguh"],["جَآءَهُم","datang kepada mereka"],["مُّوسَىٰ","Musa"],["بِٱلْبَيِّنَـٰتِ","dengan bukti yang jelas"],["فَٱسْتَكْبَرُوا۟","tetapi mereka sombong"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَمَا","dan bukan"],["كَانُوا۟","mereka boleh"],["سَـٰبِقِينَ","mengatasi Kami"]]],"3380":["(Maka masing-masing) dari orang-orang yang telah disebutkan di atas tadi (Kami siksa disebabkan dosanya, maka di antara mereka ada yang Kami timpakan kepadanya hujan batu kerikil) yaitu angin topan yang dibarengi dengan batu-batu kerikil, sebagaimana azab yang telah menimpa kaum Nabi Luth (dan di antara mereka ada yang ditimpa suara keras yang mengguntur) seperti azab yang menimpa kaum Tsamud (dan di antara mereka ada yang Kami benamkan ke dalam bumi) sebagaimana yang dialami oleh Qarun (dan di antara mereka ada yang Kami tenggelamkan) seperti yang menimpa kaum Nabi Nuh dan Firaun beserta kaumnya (dan Allah sekali-kali tidak hendak menganiaya mereka) maksudnya tidak akan mengazab mereka dengan tanpa dosa (akan tetapi merekalah yang menganiaya diri mereka sendiri) disebabkan mereka telah melakukan dosa.",[["فَكُلًّا","Jadi masing-masing"],["أَخَذْنَا","Kami rampas"],["بِذَنۢبِهِۦ ۖ","kerana dosanya"],["فَمِنْهُم","Kemudian daripada mereka"],["مَّنْ","(adakah dia) yang"],["أَرْسَلْنَا","Kami utus"],["عَلَيْهِ","pada dia"],["حَاصِبًۭا","ribut yang ganas"],["وَمِنْهُم","dan daripada mereka"],["مَّنْ","(adakah dia) yang"],["أَخَذَتْهُ","merampasnya"],["ٱلصَّيْحَةُ","tangisan yang mengerikan"],["وَمِنْهُم","dan daripada mereka"],["مَّنْ","(adakah dia) yang"],["خَسَفْنَا","Kami menyebabkan untuk menelan"],["بِهِ","dia"],["ٱلْأَرْضَ","bumi"],["وَمِنْهُم","dan daripada mereka"],["مَّنْ","(adakah dia) yang"],["أَغْرَقْنَا ۚ","Kami lemas"],["وَمَا","Dan tidak"],["كَانَ","adalah"],["ٱللَّهُ","Allah"],["لِيَظْلِمَهُمْ","untuk menzalimi mereka"],["وَلَـٰكِن","tetapi"],["كَانُوٓا۟","mereka adalah"],["أَنفُسَهُمْ","diri mereka"],["يَظْلِمُونَ","melakukan kesalahan"]]],"3381":["(Perumpamaan orang-orang yang mengambil pelindung-pelindung selain Allah) yakni berhala-berhala yang mereka harapkan dapat memberi manfaat kepada diri mereka (adalah seperti laba-laba yang membuat rumah) untuk tempat tinggalnya. (Dan sesungguhnya rumah yang paling lemah) yang paling rapuh (ialah rumah laba-laba) karena tidak dapat melindungi diri dari panas matahari dan dari dinginnya udara, demikian pula berhala-berhala itu, mereka tidak dapat memberikan manfaat apa pun kepada para penyembahnya (kalau mereka mengetahui) hal tersebut, tentu mereka tidak akan menyembahnya.",[["مَثَلُ","(The) contoh"],["ٱلَّذِينَ","orang yang"],["ٱتَّخَذُوا۟","ambil"],["مِن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["أَوْلِيَآءَ","pelindung"],["كَمَثَلِ","(adalah) seperti"],["ٱلْعَنكَبُوتِ","labah-labah itu"],["ٱتَّخَذَتْ","yang mengambil"],["بَيْتًۭا ۖ","sebuah rumah"],["وَإِنَّ","Dan sesungguhnya"],["أَوْهَنَ","yang paling lemah"],["ٱلْبُيُوتِ","(dari) rumah"],["لَبَيْتُ","sesungguhnya (ialah) rumah itu"],["ٱلْعَنكَبُوتِ ۖ","(dari) labah-labah"],["لَوْ","jika (sahaja)"],["كَانُوا۟","mereka"],["يَعْلَمُونَ","mengetahui"]]],"3382":["(Sesungguhnya Allah mengetahui yang) arti huruf maa di sini bermakna alladzii, yakni apa yang (mereka seru) mereka sembah; lafal yad'uuna dapat pula dibaca tad'uuna (selain Allah) yakni selain daripada-Nya (yakni apa saja dan Dia Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Bijaksana) di dalam perbuatan-Nya.",[["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يَعْلَمُ","mengetahui"],["مَا","apa"],["يَدْعُونَ","mereka menyeru"],["مِن","selain Dia"],["دُونِهِۦ","selain Dia"],["مِن","sebarang"],["شَىْءٍۢ ۚ","perkara"],["وَهُوَ","Dan Dia"],["ٱلْعَزِيزُ","(ialah) Yang Maha Perkasa"],["ٱلْحَكِيمُ","Yang Maha Bijaksana"]]],"3383":["(Dan perumpamaan-perumpamaan ini) yang ada dalam Alquran (Kami buatkan) Kami jadikan (untuk manusia; dan tiada yang memahaminya) yang mengerti akan perumpamaan-perumpamaan ini (kecuali orang-orang yang berilmu) yakni, orang-orang yang berpikir.",[["وَتِلْكَ","Dan ini"],["ٱلْأَمْثَـٰلُ","contoh"],["نَضْرِبُهَا","Kami menetapkan"],["لِلنَّاسِ ۖ","kepada manusia"],["وَمَا","tetapi tidak"],["يَعْقِلُهَآ","akan memahami mereka"],["إِلَّا","kecuali"],["ٱلْعَـٰلِمُونَ","mereka yang berpengetahuan"]]],"3384":["(Allah menciptakan langit dan bumi dengan hak) dengan benar. (Sesungguhnya pada yang demikian itu terdapat tanda-tanda) yang menunjukkan akan kekuasaan Allah swt. (bagi orang-orang mukmin) orang-orang mukmin disebutkan secara khusus karena hanya mereka sajalah yang dapat mengambil manfaat dari hal tersebut untuk memperkuat keimanannya, berbeda dengan orang-orang kafir.",[["خَلَقَ","Allah cipta"],["ٱللَّهُ","Allah cipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["بِٱلْحَقِّ ۚ","dalam kebenaran"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَةًۭ","(adalah) sesungguhnya suatu tanda"],["لِّلْمُؤْمِنِينَ","untuk orang yang beriman"]]],"3385":["(Bacalah apa yang telah diwahyukan kepadamu, yaitu Alkitab) kitab Alquran (dan dirikanlah salat. Sesungguhnya salat itu mencegah dari perbuatan-perbuatan keji dan mungkar) menurut syariat seharusnya salat menjadi benteng bagi seseorang dari perbuatan-perbuatan keji dan mungkar, selagi ia benar-benar mengerjakannya. (Dan sesungguhnya mengingat Allah adalah lebih besar keutamaannya) daripada ibadah-ibadah dan amal-amal ketaatan lainnya. (Dan Allah mengetahui apa yang kalian kerjakan) maka Dia membalasnya kepada kalian.",[["ٱتْلُ","mengaji"],["مَآ","apa"],["أُوحِىَ","telah didedahkan"],["إِلَيْكَ","kepada kamu"],["مِنَ","daripada"],["ٱلْكِتَـٰبِ","Kitab"],["وَأَقِمِ","dan menubuhkan"],["ٱلصَّلَوٰةَ ۖ","solat"],["إِنَّ","Sesungguhnya"],["ٱلصَّلَوٰةَ","solat"],["تَنْهَىٰ","menghalang"],["عَنِ","daripada"],["ٱلْفَحْشَآءِ","maksiat itu"],["وَٱلْمُنكَرِ ۗ","dan perbuatan jahat"],["وَلَذِكْرُ","dan sesungguhnya ingatan itu"],["ٱللَّهِ","(milik) Allah"],["أَكْبَرُ ۗ","(adalah) terbesar"],["وَٱللَّهُ","Dan Allah"],["يَعْلَمُ","mengetahui"],["مَا","apa"],["تَصْنَعُونَ","kamu lakukan"]]]});